insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (142, 11, 6, 17, 'سورة هود ٦ – ١٧', '«وما من دابة في الأرض إلا على الله رزقها»، «ليبلوكم أيكم أحسن عملاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 142) = $j$[{"lbl": "الآيات ٦ – ٨", "q": "۞وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ ﴿٦﴾ وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٧﴾ وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ أُمَّةٖ مَّعۡدُودَةٖ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٨﴾", "w": [["من دابة", "حيّ يدبّ على الأرض أي يمشي، من إنسان وحيوان."], ["مستقرها", "مكان استقرارها من الأرض."], ["ومستودعها", "مكان استيداعها قبل استقرارها، كأصلاب الرجال وأرحام النساء."], ["في ستة أيام", "الأحد والاثنين والثلاثاء والأربعاء والخميس والجمعة."], ["وكان عرشه على الماء", "إذ لم يكن قد خلق شيئاً من المخلوقات سواه."], ["ليبلوكم", "ليختبركم ليرى أيكم أحسن عملاً."], ["إلى أمة معدودة", "إلى طائفة من الزمن معدودة."]], "m": "لما أخبر تعالى أنه عليم بذات الصدور، ذكر مظاهر علمه وقدرته: ما من دابة في الأرض، من إنسان أو حيوان يزحف أو يمشي أو يطير، إلا وقد تكفّل الله برزقها، ويعلم مكان استقرارها في الأرض، ومستودعها بعد موتها إلى أن تُبعث، كلٌّ مدوّن قبل خلقه في كتاب المقادير. وهو الذي خلق السماوات السبع والأرض في ستة أيام، وخلق العرش قبل ذلك، والعرش سرير الملك ومنه يتم تدبير كل شيء، ولم يكن إلا الماء، خلقكم وخلق كل شيء لأجلكم ليختبركم أيكم أطوع له وأحسن عملاً، بإخلاصه لله وفعله على نحو ما شرعه الله وبيّنه رسوله. وبهذه المظاهر استوجب العبادة وحده، وعُلم أنه لا يخفى عليه شيء، فكيف يحاول الجهلة إخفاء ما في صدورهم؟ ولئن قلت للمشركين: إنكم مبعوثون من بعد الموت، ليقولن: ما هذا إلا سحر مبين. ولئن أخّرنا عنهم العذاب إلى أوقات معدودة ليقولن إنكاراً واستخفافاً: ما يحبسه؟ ألا يوم يأتيهم ليس مصروفاً عنهم، ونزل بهم ما كانوا به يستهزئون.", "h": ["سعة علم الله تعالى وتكفّله بأرزاق مخلوقاته من إنسان وحيوان.", "بيان خلق الأكوان، وعلة الخلق.", "تقرير مبدأ البعث الآخر بعد تقرير الألوهية لله تعالى.", "لا ينبغي الاغترار بإمهال الله تعالى لأهل معصيته، فإنه قد يأخذهم فجأة وهم لا يشعرون."], "k": "«إلا على الله رزقها»… تكفّل ربي برزقي؛ فهل يشغلني الرزق عن «أيكم أحسن عملاً»؟"}, {"lbl": "الآيات ٩ – ١١", "q": "وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ ﴿٩﴾ وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ ﴿١٠﴾ إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ﴿١١﴾", "w": [["أذقنا الإنسان", "أنلناه رحمة، أي غنى وصحة."], ["ثم نزعناها منه", "سلبناها منه."], ["ليؤوس كفور", "كثير اليأس أي القنوط، شديد الكفر."], ["السيئات", "جمع سيئة، وهي ما يسوء من المصائب."], ["فرح فخور", "كثير الفرح والسرور والبطر."], ["صبروا", "على الضراء والمكاره."], ["مغفرة", "لذنوبهم."], ["وأجر كبير", "الجنة دار الأبرار."]], "m": "يخبر تعالى أن الإنسان الذي لم يستنر بنور الإيمان ولم يتحلَّ بصالح الأعمال، إن أذاقه الله رحمة منه برخاء وسعة عيش وصحة بدن، ثم نزعها منه لأمر أراده، إنه لكثير اليأس والقنوط، جحود لما كان أنعم به عليه. ولئن أذاقه طعم نعمة ورخاء وصحة بعد فقر ومرض، بدل أن يحمد الله ويشكره، يقول متبجّحاً: ذهب السيئات عني، إنه لكثير السرور، كثير الفخر والمباهاة، وعلّة هذا ظلمة النفس بسبب الكفر والمعاصي. أما المؤمن المطيع فعلى العكس: إن أصابته سراء شكر، وإن أصابته ضراء صبر، لما في قلبه من نور الإيمان وفي نفسه من زكاة الأعمال، وهو ما تضمّنه قوله: إلا الذين صبروا وعملوا الصالحات أولئك لهم مغفرة لذنوبهم وأجر كبير عند ربهم، وهو الجنة.", "h": ["أن الإنسان قبل أن يُطهَّر بالإيمان والعمل الصالح يكون في غاية الضعف والانحطاط.", "ذم الفرح بالدنيا والفخر بها.", "بيان كمال المؤمن الروحي المتمثّل في الصبر والشكر، وبيان جزائه بالمغفرة والجنة."], "k": "«إلا الذين صبروا وعملوا الصالحات»… في الضيق صبر، وفي السعة شكر؛ فبأيّهما أنا أضعف؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرٞۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ ﴿١٢﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٣﴾ فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ﴿١٤﴾", "w": [["فلعلك تارك", "للاستفهام الإنكاري، أي لا يقع منك ترك ولا يضق صدرك."], ["وضائق به صدرك", "أي بتلاوته عليهم كراهية أن يقولوا كذا وكذا."], ["كنز", "مال كثير تنفق منه على نفسك وعلى أتباعك."], ["وكيل", "رقيب حفيظ."], ["افتراه", "اختلقه وكذبه."]], "m": "بعد أن كثرت مطالبة المشركين الرسول ﷺ باقتراحات، منها: لولا أُنزل عليه ملك فيكون معه نذيراً، أو يُلقى إليه كنز، قال تعالى لرسوله: فلعلك تارك بعض ما يوحى إليك فلا تبلّغه لتهاونهم به وإعراضهم عنه، وضائق به صدرك كراهة أن تواجههم به فيقولوا: لولا أُنزل عليه كنز يدل على رسالته، أو جاء معه ملك يصدّقه؟ لا ينبغي أن يكون ذلك منك، فبلّغ ولا يضق صدرك، إنما أنت نذير، والله على كل شيء وكيل، رقيب حفيظ، وليس عليك من ذلك شيء. أم يقولون: افترى القرآن من نفسه؟ قل: فأتوا بعشر سور مثله مفتريات، وادعوا من استطعتم لإعانتكم إن كنتم صادقين، فإن لم يستجب لنصرتكم من دعوتم وعجزتم، فاعلموا أنما أُنزل القرآن بعلم الله، وذلك أقوى برهان على أنه وحيه، وأن لا إله إلا هو، فهل أنتم مسلمون بعد قيام الحجة عليكم؟", "h": ["بيان ولاية الله لرسوله، وتسديده له وتأييده.", "بيان ما كان عليه المشركون من عناد في الحق ومكابرة.", "بيان أن الرسول ﷺ لم يُكلَّف هداية الناس، وإنما كُلّف إنذارهم عاقبة كفرهم وعصيانهم، وعلى الله تعالى بعد ذلك مجازاتهم.", "تحدّي الله تعالى منكري النبوة والتوحيد بالإتيان بعشر سور من مثل القرآن فعجزوا، وقامت عليهم الحجة، وثبت أن القرآن كلام الله ووحيه، وأن محمداً عبده ورسوله، وأن الله لا إله إلا هو."], "k": "«إنما أنت نذير والله على كل شيء وكيل»… عليّ البلاغ، والنتائج على الله؛ فلماذا يضيق صدري؟"}, {"lbl": "الآيات ١٥ – ١٧", "q": "مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ ﴿١٥﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ ﴿١٦﴾ أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَـٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿١٧﴾", "w": [["زينة الحياة الدنيا", "المال والولد وأنواع اللباس والطعام والشراب."], ["كتاب موسى", "التوراة."], ["ومن يكفر به", "أي بالقرآن."], ["فالنار موعده", "مكان وُعد به، فهو لا محالة نازل به."], ["في مرية منه", "في شك منه."]], "m": "لما أقام الله الحجة على المكذّبين بعجزهم، لم يبق إلا أن يختار المرء أحد الطريقين: الدنيا أو الآخرة. من كان يريد الحياة الدنيا وزينتها من مال وولد وجاه وسلطان وفاخر اللباس، نوفّ إليهم نتاج عملهم فيها وافياً غير منقوص على قدر جهدهم، ولا يبخسهم كفرُهم، ثم إن لم يتوبوا هلكوا كافرين، ليس لهم في الآخرة إلا النار، وحبط ما صنعوا فيها، وبطل ما كانوا يعملون. أفمن كان على بينة من ربه، بما أوحي إليه من القرآن وأدلته على التوحيد والنبوة والمعاد، ويتبعه شاهد منه، وهو لسان الصدق الذي ينطق به وكمالاته الخلقية والروحية، حتى نظر إليه أعرابي فقال: والله ما هو بوجه كذّاب، ومن قبله كتاب موسى إماماً ورحمة يشهد له بما حمل من نعوته ونعوت أمته، أفمن هو على هذه البينات كمن لا برهان له إلا تقليد الضُّلّال؟ أولئك يؤمنون بالقرآن الحق، ومن يكفر به من الأحزاب، أي سائر الطوائف والأمم، فالنار موعده. فلا تك في شك من أن موعد من يكفر به النار، إنه الحق من ربك، ولكن أكثر الناس لا يؤمنون وإن ظهرت الأدلة وقويت البراهين.", "h": ["بيان حقيقة، وهي أن الكفر غير مانع من أن ينتج الكافر بحسب جهده من كسب يده، فيحصد إذا زرع، ويربح إذا اتّجر، وينتج إذا صنع.", "بيان أن الكافر لا ينتفع من عمله في الدنيا ولو كان صالحاً، وأن الخسران لازم له.", "المسلمون على بينة من دينهم، وسائر أهل الأديان الأخرى لا بينة لهم، وهم في ظلام التقليد وضلال الكفر والجهل.", "بيان سنة الله في الناس، وهي أن أكثرهم لا يؤمنون."], "k": "«من كان يريد الحياة الدنيا وزينتها»… عملي الصالح، لأي الدارين أنويه حين أعمله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 142;
insert into public.tdb_cards(topic, i, body) select 142, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦ – ٨", "q": "۞وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ ﴿٦﴾ وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٧﴾ وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ أُمَّةٖ مَّعۡدُودَةٖ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٨﴾", "w": [["من دابة", "حيّ يدبّ على الأرض أي يمشي، من إنسان وحيوان."], ["مستقرها", "مكان استقرارها من الأرض."], ["ومستودعها", "مكان استيداعها قبل استقرارها، كأصلاب الرجال وأرحام النساء."], ["في ستة أيام", "الأحد والاثنين والثلاثاء والأربعاء والخميس والجمعة."], ["وكان عرشه على الماء", "إذ لم يكن قد خلق شيئاً من المخلوقات سواه."], ["ليبلوكم", "ليختبركم ليرى أيكم أحسن عملاً."], ["إلى أمة معدودة", "إلى طائفة من الزمن معدودة."]], "m": "لما أخبر تعالى أنه عليم بذات الصدور، ذكر مظاهر علمه وقدرته: ما من دابة في الأرض، من إنسان أو حيوان يزحف أو يمشي أو يطير، إلا وقد تكفّل الله برزقها، ويعلم مكان استقرارها في الأرض، ومستودعها بعد موتها إلى أن تُبعث، كلٌّ مدوّن قبل خلقه في كتاب المقادير. وهو الذي خلق السماوات السبع والأرض في ستة أيام، وخلق العرش قبل ذلك، والعرش سرير الملك ومنه يتم تدبير كل شيء، ولم يكن إلا الماء، خلقكم وخلق كل شيء لأجلكم ليختبركم أيكم أطوع له وأحسن عملاً، بإخلاصه لله وفعله على نحو ما شرعه الله وبيّنه رسوله. وبهذه المظاهر استوجب العبادة وحده، وعُلم أنه لا يخفى عليه شيء، فكيف يحاول الجهلة إخفاء ما في صدورهم؟ ولئن قلت للمشركين: إنكم مبعوثون من بعد الموت، ليقولن: ما هذا إلا سحر مبين. ولئن أخّرنا عنهم العذاب إلى أوقات معدودة ليقولن إنكاراً واستخفافاً: ما يحبسه؟ ألا يوم يأتيهم ليس مصروفاً عنهم، ونزل بهم ما كانوا به يستهزئون.", "h": ["سعة علم الله تعالى وتكفّله بأرزاق مخلوقاته من إنسان وحيوان.", "بيان خلق الأكوان، وعلة الخلق.", "تقرير مبدأ البعث الآخر بعد تقرير الألوهية لله تعالى.", "لا ينبغي الاغترار بإمهال الله تعالى لأهل معصيته، فإنه قد يأخذهم فجأة وهم لا يشعرون."], "k": "«إلا على الله رزقها»… تكفّل ربي برزقي؛ فهل يشغلني الرزق عن «أيكم أحسن عملاً»؟"}, {"lbl": "الآيات ٩ – ١١", "q": "وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ ﴿٩﴾ وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ ﴿١٠﴾ إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ﴿١١﴾", "w": [["أذقنا الإنسان", "أنلناه رحمة، أي غنى وصحة."], ["ثم نزعناها منه", "سلبناها منه."], ["ليؤوس كفور", "كثير اليأس أي القنوط، شديد الكفر."], ["السيئات", "جمع سيئة، وهي ما يسوء من المصائب."], ["فرح فخور", "كثير الفرح والسرور والبطر."], ["صبروا", "على الضراء والمكاره."], ["مغفرة", "لذنوبهم."], ["وأجر كبير", "الجنة دار الأبرار."]], "m": "يخبر تعالى أن الإنسان الذي لم يستنر بنور الإيمان ولم يتحلَّ بصالح الأعمال، إن أذاقه الله رحمة منه برخاء وسعة عيش وصحة بدن، ثم نزعها منه لأمر أراده، إنه لكثير اليأس والقنوط، جحود لما كان أنعم به عليه. ولئن أذاقه طعم نعمة ورخاء وصحة بعد فقر ومرض، بدل أن يحمد الله ويشكره، يقول متبجّحاً: ذهب السيئات عني، إنه لكثير السرور، كثير الفخر والمباهاة، وعلّة هذا ظلمة النفس بسبب الكفر والمعاصي. أما المؤمن المطيع فعلى العكس: إن أصابته سراء شكر، وإن أصابته ضراء صبر، لما في قلبه من نور الإيمان وفي نفسه من زكاة الأعمال، وهو ما تضمّنه قوله: إلا الذين صبروا وعملوا الصالحات أولئك لهم مغفرة لذنوبهم وأجر كبير عند ربهم، وهو الجنة.", "h": ["أن الإنسان قبل أن يُطهَّر بالإيمان والعمل الصالح يكون في غاية الضعف والانحطاط.", "ذم الفرح بالدنيا والفخر بها.", "بيان كمال المؤمن الروحي المتمثّل في الصبر والشكر، وبيان جزائه بالمغفرة والجنة."], "k": "«إلا الذين صبروا وعملوا الصالحات»… في الضيق صبر، وفي السعة شكر؛ فبأيّهما أنا أضعف؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرٞۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ ﴿١٢﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٣﴾ فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ﴿١٤﴾", "w": [["فلعلك تارك", "للاستفهام الإنكاري، أي لا يقع منك ترك ولا يضق صدرك."], ["وضائق به صدرك", "أي بتلاوته عليهم كراهية أن يقولوا كذا وكذا."], ["كنز", "مال كثير تنفق منه على نفسك وعلى أتباعك."], ["وكيل", "رقيب حفيظ."], ["افتراه", "اختلقه وكذبه."]], "m": "بعد أن كثرت مطالبة المشركين الرسول ﷺ باقتراحات، منها: لولا أُنزل عليه ملك فيكون معه نذيراً، أو يُلقى إليه كنز، قال تعالى لرسوله: فلعلك تارك بعض ما يوحى إليك فلا تبلّغه لتهاونهم به وإعراضهم عنه، وضائق به صدرك كراهة أن تواجههم به فيقولوا: لولا أُنزل عليه كنز يدل على رسالته، أو جاء معه ملك يصدّقه؟ لا ينبغي أن يكون ذلك منك، فبلّغ ولا يضق صدرك، إنما أنت نذير، والله على كل شيء وكيل، رقيب حفيظ، وليس عليك من ذلك شيء. أم يقولون: افترى القرآن من نفسه؟ قل: فأتوا بعشر سور مثله مفتريات، وادعوا من استطعتم لإعانتكم إن كنتم صادقين، فإن لم يستجب لنصرتكم من دعوتم وعجزتم، فاعلموا أنما أُنزل القرآن بعلم الله، وذلك أقوى برهان على أنه وحيه، وأن لا إله إلا هو، فهل أنتم مسلمون بعد قيام الحجة عليكم؟", "h": ["بيان ولاية الله لرسوله، وتسديده له وتأييده.", "بيان ما كان عليه المشركون من عناد في الحق ومكابرة.", "بيان أن الرسول ﷺ لم يُكلَّف هداية الناس، وإنما كُلّف إنذارهم عاقبة كفرهم وعصيانهم، وعلى الله تعالى بعد ذلك مجازاتهم.", "تحدّي الله تعالى منكري النبوة والتوحيد بالإتيان بعشر سور من مثل القرآن فعجزوا، وقامت عليهم الحجة، وثبت أن القرآن كلام الله ووحيه، وأن محمداً عبده ورسوله، وأن الله لا إله إلا هو."], "k": "«إنما أنت نذير والله على كل شيء وكيل»… عليّ البلاغ، والنتائج على الله؛ فلماذا يضيق صدري؟"}, {"lbl": "الآيات ١٥ – ١٧", "q": "مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ ﴿١٥﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ ﴿١٦﴾ أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَـٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿١٧﴾", "w": [["زينة الحياة الدنيا", "المال والولد وأنواع اللباس والطعام والشراب."], ["كتاب موسى", "التوراة."], ["ومن يكفر به", "أي بالقرآن."], ["فالنار موعده", "مكان وُعد به، فهو لا محالة نازل به."], ["في مرية منه", "في شك منه."]], "m": "لما أقام الله الحجة على المكذّبين بعجزهم، لم يبق إلا أن يختار المرء أحد الطريقين: الدنيا أو الآخرة. من كان يريد الحياة الدنيا وزينتها من مال وولد وجاه وسلطان وفاخر اللباس، نوفّ إليهم نتاج عملهم فيها وافياً غير منقوص على قدر جهدهم، ولا يبخسهم كفرُهم، ثم إن لم يتوبوا هلكوا كافرين، ليس لهم في الآخرة إلا النار، وحبط ما صنعوا فيها، وبطل ما كانوا يعملون. أفمن كان على بينة من ربه، بما أوحي إليه من القرآن وأدلته على التوحيد والنبوة والمعاد، ويتبعه شاهد منه، وهو لسان الصدق الذي ينطق به وكمالاته الخلقية والروحية، حتى نظر إليه أعرابي فقال: والله ما هو بوجه كذّاب، ومن قبله كتاب موسى إماماً ورحمة يشهد له بما حمل من نعوته ونعوت أمته، أفمن هو على هذه البينات كمن لا برهان له إلا تقليد الضُّلّال؟ أولئك يؤمنون بالقرآن الحق، ومن يكفر به من الأحزاب، أي سائر الطوائف والأمم، فالنار موعده. فلا تك في شك من أن موعد من يكفر به النار، إنه الحق من ربك، ولكن أكثر الناس لا يؤمنون وإن ظهرت الأدلة وقويت البراهين.", "h": ["بيان حقيقة، وهي أن الكفر غير مانع من أن ينتج الكافر بحسب جهده من كسب يده، فيحصد إذا زرع، ويربح إذا اتّجر، وينتج إذا صنع.", "بيان أن الكافر لا ينتفع من عمله في الدنيا ولو كان صالحاً، وأن الخسران لازم له.", "المسلمون على بينة من دينهم، وسائر أهل الأديان الأخرى لا بينة لهم، وهم في ظلام التقليد وضلال الكفر والجهل.", "بيان سنة الله في الناس، وهي أن أكثرهم لا يؤمنون."], "k": "«من كان يريد الحياة الدنيا وزينتها»… عملي الصالح، لأي الدارين أنويه حين أعمله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (143, 11, 18, 24, 'سورة هود ١٨ – ٢٤', '«ومن أظلم ممن افترى على الله كذباً»، «مثل الفريقين كالأعمى والأصم والبصير والسميع»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 143) = $j$[{"lbl": "الآيات ١٨ – ٢٢", "q": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَـٰٓئِكَ يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَـٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ ﴿١٨﴾ ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ﴿١٩﴾ أُوْلَـٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ ﴿٢٠﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٢١﴾ لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ﴿٢٢﴾", "w": [["ومن أظلم ممن افترى على الله كذباً", "لا أحد، فالاستفهام للنفي."], ["يعرضون على ربهم", "يوم القيامة."], ["الأشهاد", "جمع شاهد، وهم هنا الملائكة."], ["لعنة الله", "طرده وإبعاده."], ["على الظالمين", "المشركين."], ["سبيل الله", "الإسلام."], ["عوجاً", "معوجّة."], ["معجزين في الأرض", "فائتين الله عز وجل، بل هو قادر على أخذهم."], ["من أولياء", "أنصار يمنعونهم من عذاب الله."], ["وما كانوا يبصرون", "ذلك لفرط كراهيتهم للحق، فلا يستطيعون سماعه ولا رؤيته."]], "m": "بعد أن قرّر تعالى مصير المكذّبين بالقرآن، ذكر نوعاً من إجرام المجرمين: لا أحد أعظم ظلماً ممن افترى على الله كذباً، أيّ نوع من الكذب وإن قلّ، أولئك يُعرضون يوم القيامة على ربهم، ويقول الأشهاد من الملائكة: هؤلاء الذين كذبوا على ربهم، ثم يُعلن معلن: ألا لعنة الله على الظالمين، بُعداً لهم من الجنة. ثم وضّح جناياتهم: الذين يصرفون أنفسهم وغيرهم عن الإسلام، ويبغونه معوجّاً كما يهوون، يريدون أن يبيح لهم المحرّمات من الربا والزنى والسفور، وأن يأذن لهم في عبادة القبور والأشجار والأحجار، ويضاف إلى هذا كفرهم بالآخرة. أولئك لم يكونوا معجزين الله في الأرض مهما رأوا أنفسهم أقوياء، وما لهم من دون الله من أنصار، يُضاعف لهم العذاب لأنهم صدّوا أنفسهم وصدّوا غيرهم، وهذا هو العدل. ما كانوا يستطيعون السمع وما كانوا يبصرون، لشدة كراهيتهم للحق وأهله والداعين إليه.", "h": ["عظم ذنب من يكذب على الله تعالى بنسبة الولد أو الشريك إليه، أو بالقول عليه بدون علم منه.", "عظم جرم من يصد عن الإسلام بلسانه أو بحاله أو سلطانه.", "عظم ذنب من يريد إخضاع الشريعة الإسلامية لهواه وشهواته بالتأويلات الباطلة والفتاوى غير المسؤولة، ممن باعوا آخرتهم بدنياهم.", "بيان أن من كره قولاً أو شخصاً لا يستطيع رؤيته ولا سماعه."], "k": "«ويبغونها عوجاً»… هل أطلب من الدين ما يوافق هواي، أم أطوّع هواي لما جاء به الدين؟"}, {"lbl": "الآيتان ٢٣ – ٢٤", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٣﴾ ۞مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ ﴿٢٤﴾", "w": [["لا جرم", "حقاً وصدقاً أنهم في الآخرة هم الأخسرون."], ["وأخبتوا إلى ربهم", "تطامنوا أو خشعوا لربهم بطاعته وخشيته."], ["مثل الفريقين", "فريق المؤمنين وفريق الكافرين."], ["أفلا تذكرون", "أفلا تتعظون، فتستغفروا ربكم ثم تتوبوا إليه؟"]], "m": "أولئك البعداء هم الذين خسروا أنفسهم حيث استقروا في دار الشقاء، وغاب عنهم ما كانوا يزعمون من شركاء يشفعون لهم، لا جرم أنهم في الآخرة هم الأكثر خسراناً، لأنهم أضافوا إلى كفرهم جريمة تكفير غيرهم وصدّهم عن الإسلام. ولما ذكر حال الكافرين ذكر حال المؤمنين: إن الذين آمنوا بالله ووعده ووعيده وبرسوله وما جاء به، وعملوا الصالحات من صلاة وزكاة، وأخبتوا إلى ربهم، فأسلموا له وجوههم وقلوبهم وانقادوا له بجوارحهم، أولئك أصحاب الجنة هم فيها خالدون. ثم ذكر مقارنة بين الفريقين توضيحاً: مثل فريق الكفر كالأعمى والأصم، ومثل فريق الإيمان كالبصير والسميع، هل يستويان؟ لا، فأيّ عاقل يرضى أن يكون العمى والصمم وصفاً له؟ أفلا تتعظون بهذا المثل فتتوبوا إلى ربكم؟", "h": ["استحسان المقارنات بين الأشياء المتضادة للعبرة والاتعاظ.", "الكافر ميت موتاً معنوياً، فلذا هو لا يسمع ولا يبصر، والمسلم حيّ، فلذا هو سميع بصير.", "بيان ورثة دار النعيم، وهم أهل الإيمان والطاعة، وورثة دار الخسران، وهم أهل الكفر والظلم."], "k": "«وأخبتوا إلى ربهم»… الإخبات خشوع القلب وانقياد الجوارح؛ فأين قلبي في صلاتي القادمة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 143;
