insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (144, 11, 25, 35, 'سورة هود ٢٥ – ٣٥', 'نوح ﵇ وقومه: «وما أنا بطارد الذين آمنوا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 144) = $j$[{"lbl": "الآيات ٢٥ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ﴿٢٥﴾ أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ ﴿٢٦﴾ فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ ﴿٢٧﴾", "w": [["إني لكم نذير مبين", "بيّن النذارة."], ["عذاب يوم أليم", "هو عذابه يوم القيامة."], ["الملأ", "الأشراف وأهل الحل والعقد في البلاد."], ["أراذلنا", "جمع أرذل، وهو الأكثر خسّة ودناءة."], ["بادي الرأي", "ظاهر الرأي، لا عمق عندك في التفكير والتصور."]], "m": "هذه بداية قصة نوح ﵇، وهي بداية لخمس قصص في سورة هود: ولقد أرسلنا نوحاً إلى قومه فقال: إني لكم نذير بيّن النذارة، أخوّفكم عاقبة كفركم وشرككم بعبادة الأوثان، ألّا تعبدوا إلا الله، إني أخاف عليكم إن أصررتم عذاب يوم أليم، يوم القيامة. فقال الملأ الذين كفروا من قومه، أشرافهم وأهل الحل والعقد: ما نراك إلا بشراً مثلنا، فلا فضل لك علينا فكيف تكون رسولاً؟ وما نراك اتّبعك إلا الذين هم أراذلنا، سَفَلتنا من أهل المهن المحتقرة، بادي الرأي، أي ظاهر الرأي لا عمق ولا سلامة في التصور، وما نرى لكم علينا من فضل تستحقون به أن نتبعكم ونترك ديننا، بل نظنكم كاذبين.", "h": ["إن نوحاً، واسمه عبد الغفار، أول رسول إلى أهل الأرض بعد أن أشركوا بربهم وعبدوا غيره من الأوثان والآلهة الباطلة.", "قوله: «ألا تعبدوا إلا الله» هو معنى لا إله إلا الله.", "التذكير بعذاب يوم القيامة.", "أتباع الرسل هم الفقراء والضعفاء، وخصومهم الأغنياء والأشراف والكبراء.", "احتقار أهل الكبر لمن دونهم، وفي الحديث: «الكبر بطر الحق وغمط الناس»."], "k": "«وما نراك اتبعك إلا الذين هم أراذلنا»… هل أزن الناس بالمال والمكانة، أم بما في قلوبهم من الحق؟"}, {"lbl": "الآيات ٢٨ – ٣١", "q": "قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ ﴿٢٨﴾ وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ﴿٢٩﴾ وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ ﴿٣٠﴾ وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿٣١﴾", "w": [["أرأيتم", "أخبروني."], ["بينة من ربي", "على علم علّمنيه الله فعلمت أنه لا إله إلا الله."], ["فعميت عليكم", "خفيت عليكم فلم تروها."], ["بطارد الذين آمنوا", "بمبعدهم عني ومن حولي."], ["خزائن الله", "التي فيها الفضل والمال."], ["تزدري أعينكم", "تحتقر أعينكم."]], "m": "قال نوح لقومه: أخبروني إن كنت على علم يقيني من ربي بعبادته وتوحيده والدعوة إلى ذلك، وآتاني رحمة من عنده، وهي الوحي والنبوة والتوفيق لعبادته، فخفيت عليكم فلم تروها، فماذا أصنع معكم؟ أنجبركم أنا ومن آمن بي على رؤيتها والإيمان بها وأنتم لها كارهون، والكاره للشيء لا يكاد يراه ولا يسمعه؟ ويا قوم لا أطلب منكم أجراً على إبلاغكم، إن أجري إلا على الله الذي كلّفني ووعدني، وما أنا بمطيعكم في طرد المؤمنين من حولي كما اقترحتم، إنهم ملاقو ربهم فيحاسبهم ويجازيهم، فكيف أبعدهم عن سماع الحق؟ والعبرة بزكاة النفوس وطهارة الأرواح بالإيمان والعمل الصالح لا بالشرف والمال والجاه، ولكني أراكم قوماً تجهلون. ويا قوم من يمنعني من عذاب الله إن عصيته فطردتهم، ولا علّة لذلك إلا أنهم فقراء ضعفاء؟ أفلا تتفكرون فتعلموا خطأكم؟ ولا أقول لكم عندي خزائن الله، ولا أعلم الغيب فأعرف ما تخفيه الصدور، ولا أقول إني ملك، ولا أقول للذين تحتقرهم أعينكم لفقرهم وضعفهم: لن يؤتيهم الله خيراً، الله أعلم بما في أنفسهم، إني إذاً لمن الظالمين.", "h": ["كُره الشيء يجعل صاحبه لا يراه ولا يسمعه ولا يفهم ما يقال له فيه.", "كراهية أخذ الأجرة على الدعوة والتربية والتعليم الديني.", "وجوب احترام الضعفاء وإكرامهم، وحرمة احتقارهم وازدرائهم.", "علم الغيب استأثر الله تعالى به دون سائر خلقه، إلا من علّمه الله شيئاً منه فإنه يعلمه.", "حرمة غمط الناس وازدرائهم والسخرية منهم."], "k": "«الله أعلم بما في أنفسهم»… مَن أحتقره اليوم قد يكون عند الله خيراً مني؛ فهل أكفّ عن الازدراء؟"}, {"lbl": "الآيات ٣٢ – ٣٤", "q": "قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٣٢﴾ قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿٣٣﴾ وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٣٤﴾", "w": [["جادلتنا", "خاصمتنا تريد إسقاطنا وعدم اعتبارنا في ديننا وما نحن عليه."], ["بما تعدنا", "من العذاب إن لم نؤمن بما تدعونا إليه."], ["إن كنت من الصادقين", "في دعواك النبوة والإخبار عن الله عز وجل."], ["بمعجزين", "بغالبين ولا فائتين الله تعالى متى أراد عذابكم."], ["نصحي", "تخويفي إياكم عذاب ربكم إن بقيتم على الكفر به وبلقائه ورسوله."], ["أن يغويكم", "يوقعكم في الضلال ويبقيكم فيه فلا يهديكم أبداً."]], "m": "قال قوم نوح: يا نوح قد خاصمتنا وأكثرت جدالنا، فعجّل العذاب الذي تعدنا إن كنت من الصادقين. فقال نوح بما علّمه ربه: إنما يأتيكم به الله إن شاء، وما أنتم بفائتيه ولا هاربين منه. ولا ينفعكم نصحي، أي لا تقبلونه مهما أردته وبالغت فيه، إن كان الله يريد أن يغويكم لما فرط منكم من عناد وكفر ومكابرة، إذ مثلكم لا يستحق هداية الله، بل الأولى به الضلالة حتى يهلك ضالاً. هو ربكم وإليه ترجعون، فالأمر له: إن يشأ يرحمكم وإن يشأ يعذبكم، وإن كانت حكمته تنفي أن يعذّب الصالحين ويرحم الغواة.", "h": ["مشروعية الجدال لإحقاق الحق وإبطال الباطل، بشرط الأسلوب الحسن.", "إرادة الله تعالى قبل كل إرادة، وما شاءه الله يكون، وما لم يشأه لم يكن.", "لا ينفع نصح الناصحين ما لم يُرد الله الخير للمنصوح له.", "ينبغي عدم إصدار حكم على عبد لم يمت فيُعرف بالموت مآله، إلا قول: الله أعلم."], "k": "«ولا ينفعكم نصحي إن أردت أن أنصح لكم»… النصيحة بذرة، والهداية من الله؛ فهل أدعو لمن أنصحه؟"}, {"lbl": "الآية ٣٥", "q": "أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ ﴿٣٥﴾", "w": [["أم يقولون", "بل يقولون."], ["افتراه", "اختلقه وقاله من نفسه ولم يوحَ به إليه."], ["فعليّ إجرامي", "عاقبة الكذب، الذي هو الإجرام، تعود عليّ لا على غيري."], ["وأنا بريء", "أتبرّأ وأتنصّل من إجرامكم فلا أتحمّل مسؤوليته."], ["مما تجرمون", "على أنفسكم بإفسادها بالشرك والكفر والعصيان."]], "m": "أوقع الله هذه الآية بين أجزاء الحديث عن نوح وقومه، وحسن موقعها هنا لأن الحديث عن نوح وقومه لا يتأتّى لأحد إلا لنبي يوحى إليه لبُعده في التاريخ، فقصّ النبي ﷺ له دليل على نبوته. أم يقولون: افترى القرآن وكذبه؟ قل: إن افتريته كما زعمتم فعليّ إثم كذبي، وأنا بريء مما تجرمون أنتم بتكذيبكم إياي وكفركم بربكم ورسوله ووعده ووعيده.", "h": ["جواز الاعتراض في الكلام إذا حسن موقعه، لإقامته حجة أو إبطال باطل أو تنبيه على أمر مهم.", "قصّ القصص أكبر دليل على صدق النبي ﷺ في دعوى النبوة ودعوته إلى الله تعالى.", "تقرير مبدأ تحمّل كل إنسان مسؤولية عمله، وأن لا تزر وازرة وزر أخرى."], "k": "«فعليّ إجرامي وأنا بريء مما تجرمون»… كلٌّ يحمل عمله؛ فماذا أحمل أنا لذلك اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 144;
insert into public.tdb_cards(topic, i, body) select 144, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٥ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ﴿٢٥﴾ أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ ﴿٢٦﴾ فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ ﴿٢٧﴾", "w": [["إني لكم نذير مبين", "بيّن النذارة."], ["عذاب يوم أليم", "هو عذابه يوم القيامة."], ["الملأ", "الأشراف وأهل الحل والعقد في البلاد."], ["أراذلنا", "جمع أرذل، وهو الأكثر خسّة ودناءة."], ["بادي الرأي", "ظاهر الرأي، لا عمق عندك في التفكير والتصور."]], "m": "هذه بداية قصة نوح ﵇، وهي بداية لخمس قصص في سورة هود: ولقد أرسلنا نوحاً إلى قومه فقال: إني لكم نذير بيّن النذارة، أخوّفكم عاقبة كفركم وشرككم بعبادة الأوثان، ألّا تعبدوا إلا الله، إني أخاف عليكم إن أصررتم عذاب يوم أليم، يوم القيامة. فقال الملأ الذين كفروا من قومه، أشرافهم وأهل الحل والعقد: ما نراك إلا بشراً مثلنا، فلا فضل لك علينا فكيف تكون رسولاً؟ وما نراك اتّبعك إلا الذين هم أراذلنا، سَفَلتنا من أهل المهن المحتقرة، بادي الرأي، أي ظاهر الرأي لا عمق ولا سلامة في التصور، وما نرى لكم علينا من فضل تستحقون به أن نتبعكم ونترك ديننا، بل نظنكم كاذبين.", "h": ["إن نوحاً، واسمه عبد الغفار، أول رسول إلى أهل الأرض بعد أن أشركوا بربهم وعبدوا غيره من الأوثان والآلهة الباطلة.", "قوله: «ألا تعبدوا إلا الله» هو معنى لا إله إلا الله.", "التذكير بعذاب يوم القيامة.", "أتباع الرسل هم الفقراء والضعفاء، وخصومهم الأغنياء والأشراف والكبراء.", "احتقار أهل الكبر لمن دونهم، وفي الحديث: «الكبر بطر الحق وغمط الناس»."], "k": "«وما نراك اتبعك إلا الذين هم أراذلنا»… هل أزن الناس بالمال والمكانة، أم بما في قلوبهم من الحق؟"}, {"lbl": "الآيات ٢٨ – ٣١", "q": "قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ ﴿٢٨﴾ وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ﴿٢٩﴾ وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ ﴿٣٠﴾ وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿٣١﴾", "w": [["أرأيتم", "أخبروني."], ["بينة من ربي", "على علم علّمنيه الله فعلمت أنه لا إله إلا الله."], ["فعميت عليكم", "خفيت عليكم فلم تروها."], ["بطارد الذين آمنوا", "بمبعدهم عني ومن حولي."], ["خزائن الله", "التي فيها الفضل والمال."], ["تزدري أعينكم", "تحتقر أعينكم."]], "m": "قال نوح لقومه: أخبروني إن كنت على علم يقيني من ربي بعبادته وتوحيده والدعوة إلى ذلك، وآتاني رحمة من عنده، وهي الوحي والنبوة والتوفيق لعبادته، فخفيت عليكم فلم تروها، فماذا أصنع معكم؟ أنجبركم أنا ومن آمن بي على رؤيتها والإيمان بها وأنتم لها كارهون، والكاره للشيء لا يكاد يراه ولا يسمعه؟ ويا قوم لا أطلب منكم أجراً على إبلاغكم، إن أجري إلا على الله الذي كلّفني ووعدني، وما أنا بمطيعكم في طرد المؤمنين من حولي كما اقترحتم، إنهم ملاقو ربهم فيحاسبهم ويجازيهم، فكيف أبعدهم عن سماع الحق؟ والعبرة بزكاة النفوس وطهارة الأرواح بالإيمان والعمل الصالح لا بالشرف والمال والجاه، ولكني أراكم قوماً تجهلون. ويا قوم من يمنعني من عذاب الله إن عصيته فطردتهم، ولا علّة لذلك إلا أنهم فقراء ضعفاء؟ أفلا تتفكرون فتعلموا خطأكم؟ ولا أقول لكم عندي خزائن الله، ولا أعلم الغيب فأعرف ما تخفيه الصدور، ولا أقول إني ملك، ولا أقول للذين تحتقرهم أعينكم لفقرهم وضعفهم: لن يؤتيهم الله خيراً، الله أعلم بما في أنفسهم، إني إذاً لمن الظالمين.", "h": ["كُره الشيء يجعل صاحبه لا يراه ولا يسمعه ولا يفهم ما يقال له فيه.", "كراهية أخذ الأجرة على الدعوة والتربية والتعليم الديني.", "وجوب احترام الضعفاء وإكرامهم، وحرمة احتقارهم وازدرائهم.", "علم الغيب استأثر الله تعالى به دون سائر خلقه، إلا من علّمه الله شيئاً منه فإنه يعلمه.", "حرمة غمط الناس وازدرائهم والسخرية منهم."], "k": "«الله أعلم بما في أنفسهم»… مَن أحتقره اليوم قد يكون عند الله خيراً مني؛ فهل أكفّ عن الازدراء؟"}, {"lbl": "الآيات ٣٢ – ٣٤", "q": "قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٣٢﴾ قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ ﴿٣٣﴾ وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٣٤﴾", "w": [["جادلتنا", "خاصمتنا تريد إسقاطنا وعدم اعتبارنا في ديننا وما نحن عليه."], ["بما تعدنا", "من العذاب إن لم نؤمن بما تدعونا إليه."], ["إن كنت من الصادقين", "في دعواك النبوة والإخبار عن الله عز وجل."], ["بمعجزين", "بغالبين ولا فائتين الله تعالى متى أراد عذابكم."], ["نصحي", "تخويفي إياكم عذاب ربكم إن بقيتم على الكفر به وبلقائه ورسوله."], ["أن يغويكم", "يوقعكم في الضلال ويبقيكم فيه فلا يهديكم أبداً."]], "m": "قال قوم نوح: يا نوح قد خاصمتنا وأكثرت جدالنا، فعجّل العذاب الذي تعدنا إن كنت من الصادقين. فقال نوح بما علّمه ربه: إنما يأتيكم به الله إن شاء، وما أنتم بفائتيه ولا هاربين منه. ولا ينفعكم نصحي، أي لا تقبلونه مهما أردته وبالغت فيه، إن كان الله يريد أن يغويكم لما فرط منكم من عناد وكفر ومكابرة، إذ مثلكم لا يستحق هداية الله، بل الأولى به الضلالة حتى يهلك ضالاً. هو ربكم وإليه ترجعون، فالأمر له: إن يشأ يرحمكم وإن يشأ يعذبكم، وإن كانت حكمته تنفي أن يعذّب الصالحين ويرحم الغواة.", "h": ["مشروعية الجدال لإحقاق الحق وإبطال الباطل، بشرط الأسلوب الحسن.", "إرادة الله تعالى قبل كل إرادة، وما شاءه الله يكون، وما لم يشأه لم يكن.", "لا ينفع نصح الناصحين ما لم يُرد الله الخير للمنصوح له.", "ينبغي عدم إصدار حكم على عبد لم يمت فيُعرف بالموت مآله، إلا قول: الله أعلم."], "k": "«ولا ينفعكم نصحي إن أردت أن أنصح لكم»… النصيحة بذرة، والهداية من الله؛ فهل أدعو لمن أنصحه؟"}, {"lbl": "الآية ٣٥", "q": "أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ ﴿٣٥﴾", "w": [["أم يقولون", "بل يقولون."], ["افتراه", "اختلقه وقاله من نفسه ولم يوحَ به إليه."], ["فعليّ إجرامي", "عاقبة الكذب، الذي هو الإجرام، تعود عليّ لا على غيري."], ["وأنا بريء", "أتبرّأ وأتنصّل من إجرامكم فلا أتحمّل مسؤوليته."], ["مما تجرمون", "على أنفسكم بإفسادها بالشرك والكفر والعصيان."]], "m": "أوقع الله هذه الآية بين أجزاء الحديث عن نوح وقومه، وحسن موقعها هنا لأن الحديث عن نوح وقومه لا يتأتّى لأحد إلا لنبي يوحى إليه لبُعده في التاريخ، فقصّ النبي ﷺ له دليل على نبوته. أم يقولون: افترى القرآن وكذبه؟ قل: إن افتريته كما زعمتم فعليّ إثم كذبي، وأنا بريء مما تجرمون أنتم بتكذيبكم إياي وكفركم بربكم ورسوله ووعده ووعيده.", "h": ["جواز الاعتراض في الكلام إذا حسن موقعه، لإقامته حجة أو إبطال باطل أو تنبيه على أمر مهم.", "قصّ القصص أكبر دليل على صدق النبي ﷺ في دعوى النبوة ودعوته إلى الله تعالى.", "تقرير مبدأ تحمّل كل إنسان مسؤولية عمله، وأن لا تزر وازرة وزر أخرى."], "k": "«فعليّ إجرامي وأنا بريء مما تجرمون»… كلٌّ يحمل عمله؛ فماذا أحمل أنا لذلك اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (145, 11, 36, 49, 'سورة هود ٣٦ – ٤٩', 'السفينة والطوفان: «اركبوا فيها بسم الله مجراها ومرساها»، و«إنه ليس من أهلك»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 145) = $j$[{"lbl": "الآيات ٣٦ – ٣٩", "q": "وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ ﴿٣٦﴾ وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ﴿٣٧﴾ وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ﴿٣٨﴾ فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ﴿٣٩﴾", "w": [["وأوحي إلى نوح", "أُعلم بطريق الوحي الذي هو الإعلام السريع."], ["فلا تبتئس", "لا تحزن ولا يشتد بك الحزن، فإني منجيك ومهلكهم."], ["الفلك", "السفينة التي أمرناك بصنعها لحمل المؤمنين عليها."], ["سخروا منه", "استهزؤوا به كقولهم: تحمل هذا الفلك إلى البحر أو تحمل البحر إليه؟"], ["يخزيه", "يذلّه ويهينه."], ["ويحل عليه عذاب مقيم", "ينزل به عذاب النار يوم القيامة فلا يفارقه."]], "m": "وأوحى الله إلى نوح ﵇ أنه لن يؤمن من قومك بعد اليوم إلا من قد آمن، فلا تغتمّ ولا تحزن بما كانوا يفعلون من الشر والفساد والكفر، فإني منجيك ومن معك من المؤمنين ومهلكهم بالغرق. واصنع السفينة تحت بصرنا وبتوجيهنا وتعليمنا، إذ لم يكن يعرف السفن ولا كيفية صنعها، ولا تسألني لهم صرف العذاب ولا تشفع لهم، إنهم مغرقون. ويصنع الفلك بقطع الخشب ونجره وتركيبه، وكلما مرّ عليه أشراف قومه سخروا منه: يا نوح أصبحت نجاراً؟ أتنقل البحر إليها أم تنقلها إلى البحر؟ فيردّ عليهم: إن تسخروا منا فإنا نسخر منكم كما تسخرون، فسوف تعلمون من يأتيه عذاب يذلّه ويكسر أنف كبريائه، ويحلّ عليه عذاب النار الدائم يوم القيامة.", "h": ["كراهية الحزن والأسى والأسف على ما يقوم به أهل الباطل والشر والفساد.", "بيان تاريخ صنع السفن، وأنها بتعليم الله لنوح ﵇.", "بيان سنة البشر في الاستهزاء والسخرية بأهل الحق ودعاته، لظلمة نفوسهم بالكفر.", "بيان صدق وعد الله رسله."], "k": "«إن تسخروا منا فإنا نسخر منكم»… سخرية الناس من طاعتي لا تضرّني؛ فهل أثبت كما ثبت نوح؟"}, {"lbl": "الآيات ٤٠ – ٤٤", "q": "حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ ﴿٤٠﴾ ۞وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ ﴿٤١﴾ وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ ﴿٤٢﴾ قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ ﴿٤٣﴾ وَقِيلَ يَـٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤٤﴾", "w": [["فار التنور", "خرج الماء وارتفع من التنور، وهو مكان طبخ الخبز."], ["زوجين اثنين", "من كل ذكر وأنثى من سائر أنواع المخلوقات اثنين."], ["وأهلك", "زوجتك وأولادك."], ["مجراها ومرساها", "إجراؤها وإرساؤها."], ["في موج كالجبال", "الموج ارتفاع ماء البحر، وكونه كالجبال أي في الارتفاع."], ["يعصمني من الماء", "يمنعني من الماء أن يغرقني."]], "m": "واصل نوح صنع السفينة حتى إذا جاء أمرنا بإهلاك المشركين وفار التنور، أي خرج الماء من داخله وتلك علامة بداية الطوفان، قلنا: احمل فيها من كل نوع من الحيوانات زوجين ذكراً وأنثى، واحمل أهلك من زوجة وولد: سام وحام ويافث، إلا من سبق عليه القول بالإهلاك كامرأته واعلة وولده كنعان، واحمل من آمن من سائر الناس، وما آمن معه إلا قليل. وقال نوح للمؤمنين: اركبوا فيها، باسم الله تجري وباسم الله ترسو، إن ربي لغفور رحيم، فلا يهلكنا بما قد يكون لنا من ذنب. وهي تجري بهم في موج كالجبال في ارتفاعه، ونادى نوح ابنه كنعان وهو في معزل عن السفينة، رفض الركوب لعقوقه وكفره: يا بنيّ اركب معنا ولا تكن مع الكافرين. قال: سآوي إلى جبل يمنعني من الماء. قال: لا عاصم اليوم من أمر الله إلا من رحمه الله، وحال بينهما الموج فكان من المغرقين. وقيل: يا أرض ابلعي ماءك، ويا سماء أقلعي عن الإمطار، والآمر هو الله، ونقص الماء ونضب، وقُضي الأمر، ورست السفينة على الجودي، جبل بالجزيرة قرب الموصل، وقيل: هلاكاً للقوم الظالمين، فلم يبق منهم أحد.", "h": ["الإيمان ينجي، والكفر يهلك ويردي.", "مشروعية التسمية عند الركوب في سفينة أو غيرها.", "عقوق الوالدين كثيراً ما يسبب الهلاك في الدنيا، أما عذاب الآخرة فهو لازم له.", "مظهر من مظاهر رحمة الوالد بولده.", "مظاهر عظمة الرب تعالى، وإطاعة الخلق أمره حتى الأرض والسماء."], "k": "«لا عاصم اليوم من أمر الله إلا من رحم»… على أي «جبل» أعتمد غير الله؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ ﴿٤٥﴾ قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ ﴿٤٦﴾ قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ ﴿٤٧﴾ قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ ﴿٤٨﴾ تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ ﴿٤٩﴾", "w": [["من أهلي", "من جملة أهلي من أزواج وأولاد."], ["وإن وعدك الحق", "الثابت الذي لا يُخلف."], ["إنه عمل غير صالح", "إن سؤالك هذا إياي عمل غير صالح."], ["أعظك", "أنهاك وأخوّفك من أن تكون من الجاهلين."], ["من الجاهلين", "من الذين لا يعرفون جلالي وصدق وعدي ووفائي."], ["سنمتعهم", "بالأرزاق والمتع إلى نهاية آجالهم، ثم يحلّ بهم عذابي."], ["للمتقين", "الذين يتقون الله فيعبدونه ولا يشركون به شيئاً."]], "m": "ونادى نوح ربه حال الإركاب وامتناع ولده: رب إن ابني من أهلي، وقد وعدتني أن تنجيني وأهلي، وإن وعدك الحق الذي لا خُلف فيه، وأنت أحكم الحاكمين، وهذا ابني سيهلك إن لم ترحمه. فأجابه الرب: إنه ليس من أهلك الذين وعدتك بإنجائهم، لأنه على غير دينك، إن سؤالك إنجاء ولدك وهو كافر، وقد أعلمتك أني مغرق الكافرين، عمل غير صالح، فلا تسألني ما ليس لك به علم، إني أعظك أن تكون من الجاهلين. قال نوح: رب إني أعوذ بك أن أسألك ما ليس لي به علم، وإلا تغفر لي وترحمني أكن من الخاسرين. قيل: يا نوح اهبط من السفينة بسلام منا وبركات عليك وعلى أمم من ذرية من معك، وأمم من ذريتهم سنمتعهم في الدنيا بالأرزاق ثم يمسهم منا عذاب أليم لأنهم ينحرفون عن الإسلام، وهذا من الغيب فكان كما أخبر. تلك القصة من أنباء الغيب نوحيها إليك، ما كنت تعلمها أنت ولا قومك من قبل هذا القرآن، فاصبر على أذى قومك مبلّغاً، إن العاقبة الحميدة للمتقين.", "h": ["رابطة الإيمان والتقوى أعظم من رابطة النسب.", "حرمة العمل بغير علم، فلا يحل الإقدام على أمر حتى يُعلم حكم الله فيه.", "ذم الجهل وأهله.", "شرف نوح ﵇، وأنه أحد أولي العزم من الرسل.", "بيان العبرة من القصص القرآني، وهي تسلية الرسول ﷺ والمؤمنين.", "تقرير نبوة الرسول ﷺ وإثباتها ببرهان عقلي، وهو الإخبار بالغيب الذي لا يُعلم إلا من طريق الوحي.", "بيان فضل الصبر، وأن العاقبة الحميدة للمتقين، وهم أهل التوحيد والعمل الصالح."], "k": "«رب إني أعوذ بك أن أسألك ما ليس لي به علم»… هل أسأل ربي وأنا راضٍ بما يختاره لي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 145;
insert into public.tdb_cards(topic, i, body) select 145, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٦ – ٣٩", "q": "وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ ﴿٣٦﴾ وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ﴿٣٧﴾ وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ﴿٣٨﴾ فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ﴿٣٩﴾", "w": [["وأوحي إلى نوح", "أُعلم بطريق الوحي الذي هو الإعلام السريع."], ["فلا تبتئس", "لا تحزن ولا يشتد بك الحزن، فإني منجيك ومهلكهم."], ["الفلك", "السفينة التي أمرناك بصنعها لحمل المؤمنين عليها."], ["سخروا منه", "استهزؤوا به كقولهم: تحمل هذا الفلك إلى البحر أو تحمل البحر إليه؟"], ["يخزيه", "يذلّه ويهينه."], ["ويحل عليه عذاب مقيم", "ينزل به عذاب النار يوم القيامة فلا يفارقه."]], "m": "وأوحى الله إلى نوح ﵇ أنه لن يؤمن من قومك بعد اليوم إلا من قد آمن، فلا تغتمّ ولا تحزن بما كانوا يفعلون من الشر والفساد والكفر، فإني منجيك ومن معك من المؤمنين ومهلكهم بالغرق. واصنع السفينة تحت بصرنا وبتوجيهنا وتعليمنا، إذ لم يكن يعرف السفن ولا كيفية صنعها، ولا تسألني لهم صرف العذاب ولا تشفع لهم، إنهم مغرقون. ويصنع الفلك بقطع الخشب ونجره وتركيبه، وكلما مرّ عليه أشراف قومه سخروا منه: يا نوح أصبحت نجاراً؟ أتنقل البحر إليها أم تنقلها إلى البحر؟ فيردّ عليهم: إن تسخروا منا فإنا نسخر منكم كما تسخرون، فسوف تعلمون من يأتيه عذاب يذلّه ويكسر أنف كبريائه، ويحلّ عليه عذاب النار الدائم يوم القيامة.", "h": ["كراهية الحزن والأسى والأسف على ما يقوم به أهل الباطل والشر والفساد.", "بيان تاريخ صنع السفن، وأنها بتعليم الله لنوح ﵇.", "بيان سنة البشر في الاستهزاء والسخرية بأهل الحق ودعاته، لظلمة نفوسهم بالكفر.", "بيان صدق وعد الله رسله."], "k": "«إن تسخروا منا فإنا نسخر منكم»… سخرية الناس من طاعتي لا تضرّني؛ فهل أثبت كما ثبت نوح؟"}, {"lbl": "الآيات ٤٠ – ٤٤", "q": "حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ ﴿٤٠﴾ ۞وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ ﴿٤١﴾ وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ ﴿٤٢﴾ قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ ﴿٤٣﴾ وَقِيلَ يَـٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤٤﴾", "w": [["فار التنور", "خرج الماء وارتفع من التنور، وهو مكان طبخ الخبز."], ["زوجين اثنين", "من كل ذكر وأنثى من سائر أنواع المخلوقات اثنين."], ["وأهلك", "زوجتك وأولادك."], ["مجراها ومرساها", "إجراؤها وإرساؤها."], ["في موج كالجبال", "الموج ارتفاع ماء البحر، وكونه كالجبال أي في الارتفاع."], ["يعصمني من الماء", "يمنعني من الماء أن يغرقني."]], "m": "واصل نوح صنع السفينة حتى إذا جاء أمرنا بإهلاك المشركين وفار التنور، أي خرج الماء من داخله وتلك علامة بداية الطوفان، قلنا: احمل فيها من كل نوع من الحيوانات زوجين ذكراً وأنثى، واحمل أهلك من زوجة وولد: سام وحام ويافث، إلا من سبق عليه القول بالإهلاك كامرأته واعلة وولده كنعان، واحمل من آمن من سائر الناس، وما آمن معه إلا قليل. وقال نوح للمؤمنين: اركبوا فيها، باسم الله تجري وباسم الله ترسو، إن ربي لغفور رحيم، فلا يهلكنا بما قد يكون لنا من ذنب. وهي تجري بهم في موج كالجبال في ارتفاعه، ونادى نوح ابنه كنعان وهو في معزل عن السفينة، رفض الركوب لعقوقه وكفره: يا بنيّ اركب معنا ولا تكن مع الكافرين. قال: سآوي إلى جبل يمنعني من الماء. قال: لا عاصم اليوم من أمر الله إلا من رحمه الله، وحال بينهما الموج فكان من المغرقين. وقيل: يا أرض ابلعي ماءك، ويا سماء أقلعي عن الإمطار، والآمر هو الله، ونقص الماء ونضب، وقُضي الأمر، ورست السفينة على الجودي، جبل بالجزيرة قرب الموصل، وقيل: هلاكاً للقوم الظالمين، فلم يبق منهم أحد.", "h": ["الإيمان ينجي، والكفر يهلك ويردي.", "مشروعية التسمية عند الركوب في سفينة أو غيرها.", "عقوق الوالدين كثيراً ما يسبب الهلاك في الدنيا، أما عذاب الآخرة فهو لازم له.", "مظهر من مظاهر رحمة الوالد بولده.", "مظاهر عظمة الرب تعالى، وإطاعة الخلق أمره حتى الأرض والسماء."], "k": "«لا عاصم اليوم من أمر الله إلا من رحم»… على أي «جبل» أعتمد غير الله؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ ﴿٤٥﴾ قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ ﴿٤٦﴾ قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ ﴿٤٧﴾ قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ ﴿٤٨﴾ تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ ﴿٤٩﴾", "w": [["من أهلي", "من جملة أهلي من أزواج وأولاد."], ["وإن وعدك الحق", "الثابت الذي لا يُخلف."], ["إنه عمل غير صالح", "إن سؤالك هذا إياي عمل غير صالح."], ["أعظك", "أنهاك وأخوّفك من أن تكون من الجاهلين."], ["من الجاهلين", "من الذين لا يعرفون جلالي وصدق وعدي ووفائي."], ["سنمتعهم", "بالأرزاق والمتع إلى نهاية آجالهم، ثم يحلّ بهم عذابي."], ["للمتقين", "الذين يتقون الله فيعبدونه ولا يشركون به شيئاً."]], "m": "ونادى نوح ربه حال الإركاب وامتناع ولده: رب إن ابني من أهلي، وقد وعدتني أن تنجيني وأهلي، وإن وعدك الحق الذي لا خُلف فيه، وأنت أحكم الحاكمين، وهذا ابني سيهلك إن لم ترحمه. فأجابه الرب: إنه ليس من أهلك الذين وعدتك بإنجائهم، لأنه على غير دينك، إن سؤالك إنجاء ولدك وهو كافر، وقد أعلمتك أني مغرق الكافرين، عمل غير صالح، فلا تسألني ما ليس لك به علم، إني أعظك أن تكون من الجاهلين. قال نوح: رب إني أعوذ بك أن أسألك ما ليس لي به علم، وإلا تغفر لي وترحمني أكن من الخاسرين. قيل: يا نوح اهبط من السفينة بسلام منا وبركات عليك وعلى أمم من ذرية من معك، وأمم من ذريتهم سنمتعهم في الدنيا بالأرزاق ثم يمسهم منا عذاب أليم لأنهم ينحرفون عن الإسلام، وهذا من الغيب فكان كما أخبر. تلك القصة من أنباء الغيب نوحيها إليك، ما كنت تعلمها أنت ولا قومك من قبل هذا القرآن، فاصبر على أذى قومك مبلّغاً، إن العاقبة الحميدة للمتقين.", "h": ["رابطة الإيمان والتقوى أعظم من رابطة النسب.", "حرمة العمل بغير علم، فلا يحل الإقدام على أمر حتى يُعلم حكم الله فيه.", "ذم الجهل وأهله.", "شرف نوح ﵇، وأنه أحد أولي العزم من الرسل.", "بيان العبرة من القصص القرآني، وهي تسلية الرسول ﷺ والمؤمنين.", "تقرير نبوة الرسول ﷺ وإثباتها ببرهان عقلي، وهو الإخبار بالغيب الذي لا يُعلم إلا من طريق الوحي.", "بيان فضل الصبر، وأن العاقبة الحميدة للمتقين، وهم أهل التوحيد والعمل الصالح."], "k": "«رب إني أعوذ بك أن أسألك ما ليس لي به علم»… هل أسأل ربي وأنا راضٍ بما يختاره لي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (146, 11, 50, 60, 'سورة هود ٥٠ – ٦٠', 'هود ﵇ وقومه عاد: «استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدراراً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 146) = $j$[{"lbl": "الآيات ٥٠ – ٥٢", "q": "وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ ﴿٥٠﴾ يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ ﴿٥١﴾ وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ ﴿٥٢﴾", "w": [["وإلى عاد أخاهم هوداً", "وأرسلنا إلى قبيلة عاد أخاهم في النسب لا في الدين هوداً، وهود من قبيلة عاد، وعاد من ولد سام بن نوح."], ["اعبدوا الله", "اعبدوه وحده ولا تعبدوا معه غيره."], ["ما لكم من إله غيره", "ليس لكم معبود بحق يستحق عبادتكم غيره."], ["إن أنتم إلا مفترون", "ما أنتم في تأليه غير الله من الأوثان إلا كاذبون."], ["لا أسألكم عليه أجراً", "لا أطلب منكم أجراً على إبلاغي دعوة التوحيد."], ["مدراراً", "كثيرة الدرور للمطر النازل منها."], ["ولا تتولوا مجرمين", "ولا تعرضوا عن دعوة التوحيد مجرمين على أنفسكم."]], "m": "وأرسلنا إلى قبيلة عاد أخاهم في النسب هوداً، وهو أحد أربعة أنبياء من العرب: هود وصالح وشعيب ومحمد ﷺ. قال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، ما أنتم في عبادة الأصنام والأوثان إلا كاذبون على الله، إذ لم يأمركم بعبادتها. يا قوم لا أسألكم على دعوتي أجراً، إن أجري إلا على الله الذي خلقني، أفلا تعقلون؟ لو كنت أبتغي أجراً لطلبته منكم. ويا قوم استغفروا ربكم، آمنوا به واطلبوا منه المغفرة لذنوبكم، ثم توبوا إليه بعبادته وحده واتركوا عبادة غيره، يكافئكم بأن يرسل السماء عليكم بالأمطار المتتالية بعد الذي أصابكم من الجفاف والقحط، ويزدكم قوة روحية إلى قوتكم المادية، ولا تعرضوا عن نصيحتي فترجعوا إلى عبادة الأوثان مجرمين على أنفسكم بإفسادها بأوضار الشرك والعصيان.", "h": ["دعوة الرسل من نوح إلى محمد ﷺ واحدة، وهي أن يُعبد الله وحده.", "تقرير مبدأ لا إله إلا الله.", "المشركون والمبتدعون الكل مفترون على الله كاذبون، حيث عبدوه بما لم يشرع لهم.", "وجوب الإخلاص في الدعوة.", "فضل الاستغفار ووجوب التوبة.", "تقديم الاستغفار على التوبة مُشعر بأن العبد إذا لم يعترف أولاً بذنبه لا يمكنه أن يتوب منه."], "k": "«استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدراراً»… ضيق في رزقي أو حالي؛ هل جرّبت دواء الاستغفار؟"}, {"lbl": "الآيات ٥٣ – ٥٧", "q": "قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ ﴿٥٣﴾ إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿٥٤﴾ مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ ﴿٥٥﴾ إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٦﴾ فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ﴿٥٧﴾", "w": [["ببينة", "بحجة وبرهان على صحة ما تدعونا إليه من عبادة الله."], ["وما نحن بتاركي آلهتنا", "عبادة آلهتنا لأجل قولك إنها لا تستحق أن تُعبد."], ["إلا اعتراك", "أصابك."], ["بسوء", "بخبل، فأنت تهذي وتقول ما لا يُقبل ولا يُعقل."], ["ثم لا تنظرون", "لا تمهلون."], ["آخذ بناصيتها", "مالكها وقاهرها والمتصرف فيها، فلا تملك نفعاً ولا ضراً إلا بإذنه."], ["إن ربي على صراط مستقيم", "على طريق الحق والعدل."], ["فإن تولوا", "أصلها: تتولّوا، ومعناه: تُدبروا عن الحق وتعرضوا عنه."], ["على كل شيء حفيظ", "رقيب، ولا بد أنه يجزي كل نفس بما كسبت."]], "m": "قال قوم هود: يا هود ما جئتنا بحجة على صحة ما تدعونا إليه، وما نحن بتاركي عبادة آلهتنا من أجل قولك، وما نحن لك بمصدّقين، ما نقول فيك إلا أن بعض آلهتنا التي تسبّها أصابتك بخبل وجنون فأنت تهذي. فأجابهم: إني أُشهد الله واشهدوا أني بريء مما تشركون من دونه، فأعلن براءته من آلهتهم وأنه لا يخافها إبطالاً لدعواهم، ثم تحدّاهم مستخفّاً بهم وبآلهتهم: فكيدوني جميعاً ثم لا تمهلوني، إني توكلت على الله ربي وربكم، ما من دابة إلا هو آخذ بناصيتها، قاهر لها يقودها حيث شاء، إن ربي على طريق العدل والحق فلا يسلّط أعداءه على أوليائه، فلست بخائف. فإن تعرضوا فلا يضرّني، فقد أبلغتكم ما أُرسلت به، وسيهلككم ربي ويستخلف قوماً غيركم، ولا تضرّونه شيئاً، إن ربي على كل شيء رقيب، وسيجزي كلاً بما كسب بعدله ورحمته.", "h": ["بيان مدى مجاحدة ومكابرة المشركين في كل زمان ومكان.", "تشابه الفكر الشركي وأحوال المشركين، إذ قول قوم هود: «إن نقول إلا اعتراك…» يردّده جهلة المسلمين وهو: فلان ضربه الولي الفلاني.", "مواقف أهل الإيمان واحدة، فما قال نوح لقومه متحدّياً لهم قاله هود لقومه.", "تقرير مبدأ أن كل شيء في الكون خاضع لتدبير الله، لا يخرج عما أراده له أو به."], "k": "«ما من دابة إلا هو آخذ بناصيتها»… كل من أخافه ناصيته بيد ربي؛ فممّن أخاف إذن؟"}, {"lbl": "الآيات ٥٨ – ٦٠", "q": "وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ ﴿٥٨﴾ وَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ ﴿٥٩﴾ وَأُتۡبِعُواْ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ ﴿٦٠﴾", "w": [["ولما جاء أمرنا", "أي بعذابهم، وهو الريح الصرصر."], ["برحمة منا", "بفضل منا ونعمة."], ["جبار عنيد", "مستكبر عن الحق لا يذعن له ولا يقبله."], ["ويوم القيامة", "ولعنة في يوم القيامة."], ["ألا بعداً لعاد", "هلاكاً لعاد، وإبعاداً لهم من كل رحمة."]], "m": "ولما جاء عذابنا نجّينا هوداً والذين آمنوا معه بلطف منا وفضل ونعمة، ونجّيناهم من عذاب غليظ هو عذاب يوم القيامة، فهما نجاتان: نجاة في الدنيا من الريح العقيم الصرصر التي دمّرت كل شيء بأمر ربها، ونجاة من عذاب النار يوم القيامة وهي أعظم. وتلك عاد جحدوا بآيات ربهم فلم يؤمنوا، وعصوا رسله، وجُمع لأن من كذّب برسول فكأنما كذّب بكل الرسل، واتبعوا أمر كل جبار عنيد من دعاة الضلالة وأهل الكبر، فقادوهم إلى سخط الله، وأُتبعوا في هذه الدنيا لعنة، ويوم القيامة كذلك وأشد. ألا إن عاداً كفروا ربهم فلم يعترفوا بألوهيته وعبادته، ألا بُعداً لعاد قوم هود. فهل يعتبر مشركو قريش بهذه القصة فيؤمنوا وينجوا؟", "h": ["تقرير التوحيد، إذ القصة كلها مسوقة لذلك.", "بيان سنة الله في الأولين، وهي أنه يبعث الرسل مبشّرين ومنذرين، فإن استجاب المرسل إليهم سعدوا، وإن لم يستجيبوا يمهلهم حتى تقوم الحجة عليهم ثم يهلكهم.", "التنديد بالكبر والعناد، إذ هما من شر الصفات الخلقية في الإنسان.", "اتباع الطغاة والظلمة والكفر والفساد لا يقود إلا إلى الدمار والخسار."], "k": "«واتبعوا أمر كل جبار عنيد»… مَن أتبع في رأيي وسلوكي؟ وإلى أين يقودني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 146;
insert into public.tdb_cards(topic, i, body) select 146, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٠ – ٥٢", "q": "وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ ﴿٥٠﴾ يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ ﴿٥١﴾ وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ ﴿٥٢﴾", "w": [["وإلى عاد أخاهم هوداً", "وأرسلنا إلى قبيلة عاد أخاهم في النسب لا في الدين هوداً، وهود من قبيلة عاد، وعاد من ولد سام بن نوح."], ["اعبدوا الله", "اعبدوه وحده ولا تعبدوا معه غيره."], ["ما لكم من إله غيره", "ليس لكم معبود بحق يستحق عبادتكم غيره."], ["إن أنتم إلا مفترون", "ما أنتم في تأليه غير الله من الأوثان إلا كاذبون."], ["لا أسألكم عليه أجراً", "لا أطلب منكم أجراً على إبلاغي دعوة التوحيد."], ["مدراراً", "كثيرة الدرور للمطر النازل منها."], ["ولا تتولوا مجرمين", "ولا تعرضوا عن دعوة التوحيد مجرمين على أنفسكم."]], "m": "وأرسلنا إلى قبيلة عاد أخاهم في النسب هوداً، وهو أحد أربعة أنبياء من العرب: هود وصالح وشعيب ومحمد ﷺ. قال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، ما أنتم في عبادة الأصنام والأوثان إلا كاذبون على الله، إذ لم يأمركم بعبادتها. يا قوم لا أسألكم على دعوتي أجراً، إن أجري إلا على الله الذي خلقني، أفلا تعقلون؟ لو كنت أبتغي أجراً لطلبته منكم. ويا قوم استغفروا ربكم، آمنوا به واطلبوا منه المغفرة لذنوبكم، ثم توبوا إليه بعبادته وحده واتركوا عبادة غيره، يكافئكم بأن يرسل السماء عليكم بالأمطار المتتالية بعد الذي أصابكم من الجفاف والقحط، ويزدكم قوة روحية إلى قوتكم المادية، ولا تعرضوا عن نصيحتي فترجعوا إلى عبادة الأوثان مجرمين على أنفسكم بإفسادها بأوضار الشرك والعصيان.", "h": ["دعوة الرسل من نوح إلى محمد ﷺ واحدة، وهي أن يُعبد الله وحده.", "تقرير مبدأ لا إله إلا الله.", "المشركون والمبتدعون الكل مفترون على الله كاذبون، حيث عبدوه بما لم يشرع لهم.", "وجوب الإخلاص في الدعوة.", "فضل الاستغفار ووجوب التوبة.", "تقديم الاستغفار على التوبة مُشعر بأن العبد إذا لم يعترف أولاً بذنبه لا يمكنه أن يتوب منه."], "k": "«استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدراراً»… ضيق في رزقي أو حالي؛ هل جرّبت دواء الاستغفار؟"}, {"lbl": "الآيات ٥٣ – ٥٧", "q": "قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ ﴿٥٣﴾ إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿٥٤﴾ مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ ﴿٥٥﴾ إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٦﴾ فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ﴿٥٧﴾", "w": [["ببينة", "بحجة وبرهان على صحة ما تدعونا إليه من عبادة الله."], ["وما نحن بتاركي آلهتنا", "عبادة آلهتنا لأجل قولك إنها لا تستحق أن تُعبد."], ["إلا اعتراك", "أصابك."], ["بسوء", "بخبل، فأنت تهذي وتقول ما لا يُقبل ولا يُعقل."], ["ثم لا تنظرون", "لا تمهلون."], ["آخذ بناصيتها", "مالكها وقاهرها والمتصرف فيها، فلا تملك نفعاً ولا ضراً إلا بإذنه."], ["إن ربي على صراط مستقيم", "على طريق الحق والعدل."], ["فإن تولوا", "أصلها: تتولّوا، ومعناه: تُدبروا عن الحق وتعرضوا عنه."], ["على كل شيء حفيظ", "رقيب، ولا بد أنه يجزي كل نفس بما كسبت."]], "m": "قال قوم هود: يا هود ما جئتنا بحجة على صحة ما تدعونا إليه، وما نحن بتاركي عبادة آلهتنا من أجل قولك، وما نحن لك بمصدّقين، ما نقول فيك إلا أن بعض آلهتنا التي تسبّها أصابتك بخبل وجنون فأنت تهذي. فأجابهم: إني أُشهد الله واشهدوا أني بريء مما تشركون من دونه، فأعلن براءته من آلهتهم وأنه لا يخافها إبطالاً لدعواهم، ثم تحدّاهم مستخفّاً بهم وبآلهتهم: فكيدوني جميعاً ثم لا تمهلوني، إني توكلت على الله ربي وربكم، ما من دابة إلا هو آخذ بناصيتها، قاهر لها يقودها حيث شاء، إن ربي على طريق العدل والحق فلا يسلّط أعداءه على أوليائه، فلست بخائف. فإن تعرضوا فلا يضرّني، فقد أبلغتكم ما أُرسلت به، وسيهلككم ربي ويستخلف قوماً غيركم، ولا تضرّونه شيئاً، إن ربي على كل شيء رقيب، وسيجزي كلاً بما كسب بعدله ورحمته.", "h": ["بيان مدى مجاحدة ومكابرة المشركين في كل زمان ومكان.", "تشابه الفكر الشركي وأحوال المشركين، إذ قول قوم هود: «إن نقول إلا اعتراك…» يردّده جهلة المسلمين وهو: فلان ضربه الولي الفلاني.", "مواقف أهل الإيمان واحدة، فما قال نوح لقومه متحدّياً لهم قاله هود لقومه.", "تقرير مبدأ أن كل شيء في الكون خاضع لتدبير الله، لا يخرج عما أراده له أو به."], "k": "«ما من دابة إلا هو آخذ بناصيتها»… كل من أخافه ناصيته بيد ربي؛ فممّن أخاف إذن؟"}, {"lbl": "الآيات ٥٨ – ٦٠", "q": "وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ ﴿٥٨﴾ وَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ ﴿٥٩﴾ وَأُتۡبِعُواْ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ ﴿٦٠﴾", "w": [["ولما جاء أمرنا", "أي بعذابهم، وهو الريح الصرصر."], ["برحمة منا", "بفضل منا ونعمة."], ["جبار عنيد", "مستكبر عن الحق لا يذعن له ولا يقبله."], ["ويوم القيامة", "ولعنة في يوم القيامة."], ["ألا بعداً لعاد", "هلاكاً لعاد، وإبعاداً لهم من كل رحمة."]], "m": "ولما جاء عذابنا نجّينا هوداً والذين آمنوا معه بلطف منا وفضل ونعمة، ونجّيناهم من عذاب غليظ هو عذاب يوم القيامة، فهما نجاتان: نجاة في الدنيا من الريح العقيم الصرصر التي دمّرت كل شيء بأمر ربها، ونجاة من عذاب النار يوم القيامة وهي أعظم. وتلك عاد جحدوا بآيات ربهم فلم يؤمنوا، وعصوا رسله، وجُمع لأن من كذّب برسول فكأنما كذّب بكل الرسل، واتبعوا أمر كل جبار عنيد من دعاة الضلالة وأهل الكبر، فقادوهم إلى سخط الله، وأُتبعوا في هذه الدنيا لعنة، ويوم القيامة كذلك وأشد. ألا إن عاداً كفروا ربهم فلم يعترفوا بألوهيته وعبادته، ألا بُعداً لعاد قوم هود. فهل يعتبر مشركو قريش بهذه القصة فيؤمنوا وينجوا؟", "h": ["تقرير التوحيد، إذ القصة كلها مسوقة لذلك.", "بيان سنة الله في الأولين، وهي أنه يبعث الرسل مبشّرين ومنذرين، فإن استجاب المرسل إليهم سعدوا، وإن لم يستجيبوا يمهلهم حتى تقوم الحجة عليهم ثم يهلكهم.", "التنديد بالكبر والعناد، إذ هما من شر الصفات الخلقية في الإنسان.", "اتباع الطغاة والظلمة والكفر والفساد لا يقود إلا إلى الدمار والخسار."], "k": "«واتبعوا أمر كل جبار عنيد»… مَن أتبع في رأيي وسلوكي؟ وإلى أين يقودني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (147, 11, 61, 68, 'سورة هود ٦١ – ٦٨', 'صالح ﵇ وقومه ثمود: «هو أنشأكم من الأرض واستعمركم فيها»، والناقة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 147) = $j$[{"lbl": "الآيات ٦١ – ٦٣", "q": "۞وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ ﴿٦١﴾ قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ ﴿٦٢﴾ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ ﴿٦٣﴾", "w": [["وإلى ثمود", "وأرسلنا إلى قبيلة ثمود."], ["أخاهم صالحاً", "أي في النسب، لأنه من قبيلة ثمود، بينه وبين ثمود أبي القبيلة خمسة أجداد."], ["واستعمركم", "جعلكم عُمّاراً فيها تعمرونها بالسكن والإقامة فيها."], ["قريب مجيب", "قريب من خلقه، إذ العوالم كلها بين يديه، ومجيب لمن سأله."], ["مرجواً قبل هذا", "قبل أن تقول ما قلت كنا نرجو أن تكون سيداً فينا."], ["أرأيتم", "أخبروني."], ["على بينة من ربي", "على علم بربي علّمنيه سبحانه، فهل يليق بي أن أعبد غيره؟"], ["غير تخسير", "خسار وهلاك."]], "m": "هذه بداية قصة صالح ﵇: وأرسلنا إلى قبيلة ثمود بالحِجر بين الحجاز والشام أخاهم في القبيلة لا في الدين صالحاً، فناداهم بعنوان القومية جمعاً لقلوبهم: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، هو خالقكم ورازقكم، أنشأكم من الأرض بخلق أبيكم آدم منها، وجعلكم تعمرونها بالسكن والعيش عليها، فاستغفروه بالاعتراف بألوهيته، ثم توبوا إليه فاعبدوه وحده، إن ربي قريب من عباده مجيب لسائليه، ترغيباً لهم في الإيمان. قالوا: يا صالح قد كنت فينا مرجوّاً قبل هذا، نأمل فيك الخير ونرجو أن تكون سيداً فينا، حتى فاجأتنا بما تدعونا إليه، أتنهانا أن نعبد ما يعبد آباؤنا؟ وإننا لفي شك مما تدعونا إليه موقع في الريب، وهو اضطراب النفس وعدم سكونها. قال: يا قوم أخبروني إن كنت على علم يقيني بربي ووجوب عبادته وتوحيده، وآتاني منه رحمة هي النبوة، فمن ينصرني من الله إن عصيته؟ لا أحد أبداً، فما تزيدونني إن أطعتكم في ترك عبادة ربي إلا خساراً وضلالاً في الدنيا والآخرة.", "h": ["وحدة الوسيلة والغاية عند كافة الرسل، فالوسيلة عبادة الله وحده، والغاية رضا الله والجنة.", "تقديم الاستغفار على التوبة في الآية سرّه أن المرء لا يقلع عن ذنبه حتى يعترف به.", "بيان سنة في الناس، وهي أن المرء الصالح يُرجى في أهله، حتى إذا دعاهم إلى الحق وإلى ترك الباطل كرهوه، وقد يصارحونه بما صارح به قوم صالح نبيّهم إذ قالوا: «قد كنت فينا مرجواً قبل هذا».", "حرمة الاستجابة لأهل الباطل بأي نوع من الاستجابة، إذ الاستجابة لا تزيد العبد إلا خساراً."], "k": "«إن ربي قريب مجيب»… ربي أقرب إليّ مما أظن؛ فما الحاجة التي أؤخّر سؤاله إياها؟"}, {"lbl": "الآيات ٦٤ – ٦٨", "q": "وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ ﴿٦٤﴾ فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ ﴿٦٥﴾ فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ﴿٦٦﴾ وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ﴿٦٧﴾ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ ﴿٦٨﴾", "w": [["آية", "علامة على صدقي فيما جئتكم به من أنه لا إله إلا الله."], ["فذروها تأكل في أرض الله", "اتركوها ترعى في المراعي غير المحمية لأحد."], ["بسوء", "كضربها أو قتلها، أو منعها من الماء الذي تشرب."], ["فعقروها", "قتلوها بالعقر، الذي هو قطع قوائمها بالسيف."], ["تمتعوا في داركم", "ابقوا في دياركم تأكلون وتشربون وتتمتعون في الحياة."], ["وعد غير مكذوب", "صادق، لم أكذبكم فيه، ولم يكذبني ربي الذي وعدكم."], ["في ديارهم جاثمين", "ساقطين على رُكَبهم ووجوههم."], ["كأن لم يغنوا فيها", "كأن لم يكونوا بها أمس، ولم تُعمر بهم يوماً."]], "m": "لما دعاهم صالح إلى التوحيد كذّبوه وطالبوه بما يدل على صدقه، وسألوا أن يُخرج لهم ناقة من جبل أشاروا إليه، فدعا صالح ربه فاستجاب له، وتمخّض الجبل عن ناقة عشراء عجيبة في خلقتها وكمالها، فقال: يا قوم هذه ناقة الله، أضافها إلى الله لأنها كانت بقدرته، لكم آية على صدق ما دعوتكم إليه، فاتركوها تأكل من المراعي العامة، ولا تمسّوها بسوء كعقرها أو ذبحها فيأخذكم عذاب قريب. فكذّبوه فعقروها، فقال لهم بأمر الله: تمتعوا في داركم ثلاثة أيام، ذلك وعد صادق غير مكذوب. فلما جاء أمرنا بعذابهم نجّينا صالحاً والذين آمنوا معه برحمة منا، ومن ذلّ ذلك اليوم وعذابه، إن ربك هو القوي إذا بطش، العزيز الغالب الذي لا يُغلب. وأخذ الذين ظلموا الصيحة فانخلعت لها قلوبهم، فأصبحوا في ديارهم جاثمين على رُكَبهم، كأن لم يعمروها، ألا إن ثمود كفروا ربهم، ألا بُعداً لثمود.", "h": ["إعطاء الله تعالى الآيات للمطالبين بها لا يستلزم الإيمان بها.", "آية صالح ﵇ من أعظم الآيات، ولم يؤمن عليها قومه.", "إقامة ثلاثة أيام لا يُعدّ صاحبها مقيماً، وعليه أن يقصر الصلاة.", "شؤم الظلم وسوء عاقبة أهله."], "k": "«هذه ناقة الله لكم آية»… رأوا الآية بأعينهم ولم يؤمنوا؛ فهل تكفيني آيات ربي حولي لأزداد إيماناً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 147;
insert into public.tdb_cards(topic, i, body) select 147, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦١ – ٦٣", "q": "۞وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ ﴿٦١﴾ قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ ﴿٦٢﴾ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ ﴿٦٣﴾", "w": [["وإلى ثمود", "وأرسلنا إلى قبيلة ثمود."], ["أخاهم صالحاً", "أي في النسب، لأنه من قبيلة ثمود، بينه وبين ثمود أبي القبيلة خمسة أجداد."], ["واستعمركم", "جعلكم عُمّاراً فيها تعمرونها بالسكن والإقامة فيها."], ["قريب مجيب", "قريب من خلقه، إذ العوالم كلها بين يديه، ومجيب لمن سأله."], ["مرجواً قبل هذا", "قبل أن تقول ما قلت كنا نرجو أن تكون سيداً فينا."], ["أرأيتم", "أخبروني."], ["على بينة من ربي", "على علم بربي علّمنيه سبحانه، فهل يليق بي أن أعبد غيره؟"], ["غير تخسير", "خسار وهلاك."]], "m": "هذه بداية قصة صالح ﵇: وأرسلنا إلى قبيلة ثمود بالحِجر بين الحجاز والشام أخاهم في القبيلة لا في الدين صالحاً، فناداهم بعنوان القومية جمعاً لقلوبهم: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، هو خالقكم ورازقكم، أنشأكم من الأرض بخلق أبيكم آدم منها، وجعلكم تعمرونها بالسكن والعيش عليها، فاستغفروه بالاعتراف بألوهيته، ثم توبوا إليه فاعبدوه وحده، إن ربي قريب من عباده مجيب لسائليه، ترغيباً لهم في الإيمان. قالوا: يا صالح قد كنت فينا مرجوّاً قبل هذا، نأمل فيك الخير ونرجو أن تكون سيداً فينا، حتى فاجأتنا بما تدعونا إليه، أتنهانا أن نعبد ما يعبد آباؤنا؟ وإننا لفي شك مما تدعونا إليه موقع في الريب، وهو اضطراب النفس وعدم سكونها. قال: يا قوم أخبروني إن كنت على علم يقيني بربي ووجوب عبادته وتوحيده، وآتاني منه رحمة هي النبوة، فمن ينصرني من الله إن عصيته؟ لا أحد أبداً، فما تزيدونني إن أطعتكم في ترك عبادة ربي إلا خساراً وضلالاً في الدنيا والآخرة.", "h": ["وحدة الوسيلة والغاية عند كافة الرسل، فالوسيلة عبادة الله وحده، والغاية رضا الله والجنة.", "تقديم الاستغفار على التوبة في الآية سرّه أن المرء لا يقلع عن ذنبه حتى يعترف به.", "بيان سنة في الناس، وهي أن المرء الصالح يُرجى في أهله، حتى إذا دعاهم إلى الحق وإلى ترك الباطل كرهوه، وقد يصارحونه بما صارح به قوم صالح نبيّهم إذ قالوا: «قد كنت فينا مرجواً قبل هذا».", "حرمة الاستجابة لأهل الباطل بأي نوع من الاستجابة، إذ الاستجابة لا تزيد العبد إلا خساراً."], "k": "«إن ربي قريب مجيب»… ربي أقرب إليّ مما أظن؛ فما الحاجة التي أؤخّر سؤاله إياها؟"}, {"lbl": "الآيات ٦٤ – ٦٨", "q": "وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ ﴿٦٤﴾ فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ ﴿٦٥﴾ فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ﴿٦٦﴾ وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ﴿٦٧﴾ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ ﴿٦٨﴾", "w": [["آية", "علامة على صدقي فيما جئتكم به من أنه لا إله إلا الله."], ["فذروها تأكل في أرض الله", "اتركوها ترعى في المراعي غير المحمية لأحد."], ["بسوء", "كضربها أو قتلها، أو منعها من الماء الذي تشرب."], ["فعقروها", "قتلوها بالعقر، الذي هو قطع قوائمها بالسيف."], ["تمتعوا في داركم", "ابقوا في دياركم تأكلون وتشربون وتتمتعون في الحياة."], ["وعد غير مكذوب", "صادق، لم أكذبكم فيه، ولم يكذبني ربي الذي وعدكم."], ["في ديارهم جاثمين", "ساقطين على رُكَبهم ووجوههم."], ["كأن لم يغنوا فيها", "كأن لم يكونوا بها أمس، ولم تُعمر بهم يوماً."]], "m": "لما دعاهم صالح إلى التوحيد كذّبوه وطالبوه بما يدل على صدقه، وسألوا أن يُخرج لهم ناقة من جبل أشاروا إليه، فدعا صالح ربه فاستجاب له، وتمخّض الجبل عن ناقة عشراء عجيبة في خلقتها وكمالها، فقال: يا قوم هذه ناقة الله، أضافها إلى الله لأنها كانت بقدرته، لكم آية على صدق ما دعوتكم إليه، فاتركوها تأكل من المراعي العامة، ولا تمسّوها بسوء كعقرها أو ذبحها فيأخذكم عذاب قريب. فكذّبوه فعقروها، فقال لهم بأمر الله: تمتعوا في داركم ثلاثة أيام، ذلك وعد صادق غير مكذوب. فلما جاء أمرنا بعذابهم نجّينا صالحاً والذين آمنوا معه برحمة منا، ومن ذلّ ذلك اليوم وعذابه، إن ربك هو القوي إذا بطش، العزيز الغالب الذي لا يُغلب. وأخذ الذين ظلموا الصيحة فانخلعت لها قلوبهم، فأصبحوا في ديارهم جاثمين على رُكَبهم، كأن لم يعمروها، ألا إن ثمود كفروا ربهم، ألا بُعداً لثمود.", "h": ["إعطاء الله تعالى الآيات للمطالبين بها لا يستلزم الإيمان بها.", "آية صالح ﵇ من أعظم الآيات، ولم يؤمن عليها قومه.", "إقامة ثلاثة أيام لا يُعدّ صاحبها مقيماً، وعليه أن يقصر الصلاة.", "شؤم الظلم وسوء عاقبة أهله."], "k": "«هذه ناقة الله لكم آية»… رأوا الآية بأعينهم ولم يؤمنوا؛ فهل تكفيني آيات ربي حولي لأزداد إيماناً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (148, 11, 69, 83, 'سورة هود ٦٩ – ٨٣', 'ضيف إبراهيم ﵇ والبشرى، ولوط ﵇ وقومه: «أليس منكم رجل رشيد؟»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 148) = $j$[{"lbl": "الآيات ٦٩ – ٧٣", "q": "وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ ﴿٦٩﴾ فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ ﴿٧٠﴾ وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ ﴿٧١﴾ قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ ﴿٧٢﴾ قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ ﴿٧٣﴾", "w": [["بالبشرى", "بإسحاق، ومن وراء إسحاق يعقوب."], ["فما لبث", "ما أبطأ."], ["بعجل حنيذ", "مشويّ على الحجارة."], ["لا تصل إليه", "لم يتناولوه فيأكلوا منه."], ["نكرهم", "لم يعرفهم."], ["وأوجس", "أحسّ بالخوف وشعر به."], ["لوط", "هو ابن هاران أخي إبراهيم ﵇."], ["يا ويلتا", "يا ويلتي احضري، هذا أوان حضورك."], ["وهذا بعلي شيخاً", "إشارة إلى إبراهيم، إذ هو بعلها أي زوجها."], ["إن هذا لشيء عجيب", "أمر يُتعجّب منه استبعاداً له واستغراباً."]], "m": "هذه بشارة إبراهيم ﵇: ولقد جاءت رسلنا، وهم جبريل وميكائيل وإسرافيل، إبراهيم بالبشرى، دخلوا عليه داره فسلّموا فردّ عليهم السلام، فما أبطأ أن جاء بعجل مشويّ على الحجارة فقرّبه إليهم وعرض عليهم الأكل، فلما رأى أيديهم لا تتناوله أنكرهم وأحسّ منهم خيفة، لأن العادة أن الضيف إذا قُدّم إليه طعام فلم يأكل عُرف أنه ينوي شراً. قالوا: لا تخف، إنا أُرسلنا إلى قوم لوط لإهلاكهم بسبب إجرامهم. وكانت امرأته سارة قائمة وراء الستار تخدمهم، فلما سمعت بنبأ هلاك قوم لوط ضحكت فرحاً بهلاك أهل الخبث، فبشّرها الله على لسان الملائكة بإسحاق ومن بعده يعقوب، ولد وولد ولد، فصكّت وجهها تعجباً على عادة النساء وقالت: يا ويلتا أألد وأنا عجوز، فوق التسعين، وهذا بعلي شيخاً، ابن مائة سنة؟ إن هذا لشيء عجيب. قالوا: أتعجبين من أمر الله؟ رحمة الله وبركاته عليكم أهل بيت إبراهيم، إنه حميد محمود بإفضاله وإنعامه عليكم، مجيد ذو مجد وثناء وكرم.", "h": ["استحباب تبشير المؤمن بما هو خير له ولو بالرؤيا الصالحة.", "مشروعية السلام لمن دخل على غيره أو وقف عليه أو مرّ به، ووجوب ردّ السلام.", "مشروعية خدمة أهل البيت لضيوفهم، ووجوب إكرام الضيف، وفي الحديث الصحيح: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه».", "شرف أهل بيت إبراهيم ﵇."], "k": "«فما لبث أن جاء بعجل حنيذ»… أسرع إلى إكرام ضيف لا يعرفه؛ فكيف أستقبل ضيوفي؟"}, {"lbl": "الآيات ٧٤ – ٧٦", "q": "فَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ ﴿٧٤﴾ إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّـٰهٞ مُّنِيبٞ ﴿٧٥﴾ يَـٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودٖ ﴿٧٦﴾", "w": [["الروع", "الفزع والخوف."], ["البشرى", "الخبر السارّ المفرح للقلب."], ["يجادلنا", "يخاصمنا."], ["في قوم لوط", "في شأن هلاك قوم لوط، ولوط هو رسول الله لوط بن هاران بن عم إبراهيم."], ["حليم أواه", "الحليم الذي لا يعامل بالعقوبة، والأوّاه كثير التأوّه مما يسوء."], ["أعرض عن هذا", "اترك الجدال في قوم لوط."], ["غير مردود", "لا يستطيع أحد ردّه، لأن الله تعالى قد قضى به فهو واقع لا محالة."]], "m": "فلما ذهب عن إبراهيم الفزع من الملائكة قبل أن يعرفهم، وجاءته البشرى بالولد وبهلاك قوم لوط، أخذ يجادل الملائكة في شأن هلاكهم لأجل ما بينهم من المؤمنين، فقال: إن فيها لوطاً، فأجابوه: نحن أعلم بمن فيها، لننجّينّه وأهله إلا امرأته كانت من الغابرين. إن إبراهيم لحليم، رقيق القلب لا يعامل بالعقوبة، فأراد تأخير العذاب عنهم لعلهم يتوبون، أوّاه ضارع قانت يُكثر من قول «آه» إذا رأى أو سمع ما يسوء، منيب تواب رجّاع إلى ربه في كل وقت. ولما ألحّ قالوا: يا إبراهيم أعرض عن هذا الجدال، إنه قد جاء أمر ربك بهلاكهم، وإنهم آتيهم عذاب غير مدفوع من أحد.", "h": ["مشروعية الجدال عمّن يُرجى له الخير من الناس، وذلك في غير الحدود الشرعية إذا رُفعت إلى الحاكم.", "فضيلة خلق الحلم.", "فضل الإنابة إلى الله تعالى.", "قضاء الله لا يُردّ، أي ما حكم الله به لا بد واقع."], "k": "«إن إبراهيم لحليم أواه منيب»… ثلاث صفات؛ أيّها أحتاج أن أربّي عليه نفسي؟"}, {"lbl": "الآيات ٧٧ – ٨٠", "q": "وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ ﴿٧٧﴾ وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَـٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ ﴿٧٨﴾ قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ ﴿٧٩﴾ قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ ﴿٨٠﴾", "w": [["سيء بهم", "حصل له غمّ وهمّ بمجيئهم إليه."], ["وضاق بهم ذرعاً", "عجزت طاقته عن تحمّل الأمر."], ["يوم عصيب", "شديد لا يُحتمل."], ["يهرعون إليه", "مدفوعين بدافع الشهوة، يمشون مسرعين."], ["السيئات", "كبائر الذنوب بإتيان الذكور."], ["ولا تخزون في ضيفي", "لا تذلّوني ولا تهينوني بالتعرض لضيفي."], ["رجل رشيد", "ذو رشد وعقل ومعرفة بالأمور وعواقبها."], ["أو آوي إلى ركن شديد", "إلى عشيرة قوية تمنعني منكم، ولم تكن له عشيرة لأنه من غير ديارهم."]], "m": "هذه فاتحة حديث لوط ﵇: ولما جاءت رسلنا، ضيفُ إبراهيم، لوطاً، تضايق وحصل له همّ وغمّ خوفاً عليهم من مجرمي قومه، وعجزت طاقته عن تحمّل الأمر، وقال: هذا يوم شديد لما قد يحدث فيه من تعرّض ضيفه للمذلّة. وجاءه قومه يُسرعون مدفوعين بدافع الشهوة البهيمية، ومن قبلُ كانوا يأتون الرجال في أدبارهم، فأراد أن يصرفهم عن الضيف فقال: يا قوم هؤلاء بناتي، نساء الأمة، هن أطهر لكم فتزوّجوهن، واتقوا الله ولا تهينوني في ضيفي، أليس منكم رجل رشيد يأمر بالمعروف وينهى عن المنكر؟ فأجابوه، لعنهم الله: لقد علمت ما لنا في بناتك من رغبة وحاجة، وإنك لتعلم ما نريد من إتيان الفاحشة في الرجال. قال: لو أن لي بكم قوة من أنصار وأعوان لحُلت بينكم وبين ما تشتهون، أو آوي إلى عشيرة قوية تحميني وضيفي من قومي المجرمين.", "h": ["فضيلة إكرام الضيف وحمايته من كل ما يسوءه.", "فظاعة العادات السيئة وما تُحدثه من تغيّر في الإنسان.", "بذل ما يمكن لدفع الشر، لوقاية لوط ضيفه ببناته.", "أسوأ الحياة أن لا يكون فيها من يأمر بالمعروف وينهى عن المنكر.", "إظهار الرغبة في القوة لدفع الشر وإبعاد المكروه ممدوح."], "k": "«أليس منكم رجل رشيد؟»… حين يُرتكب المنكر أمامي، هل أكون أنا ذلك الرشيد؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ ﴿٨١﴾ فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ ﴿٨٢﴾ مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّـٰلِمِينَ بِبَعِيدٖ ﴿٨٣﴾", "w": [["بقطع من الليل", "بجزء وطائفة من الليل."], ["الصبح", "هو من طلوع الفجر إلى طلوع الشمس."], ["جعلنا عاليها سافلها", "عالي القرية سافلها."], ["من سجيل", "من طين متحجّر."], ["منضود", "منظّم واحدة فوق أخرى بانتظام."], ["مسوّمة", "معلّمة بعلامة خاصة."], ["عند ربك", "معلّمة من عند الله تعالى."]], "m": "بعد أن اشتدّ بلوط الخوف وتأسّف من عدم القدرة على حماية ضيفه، قالت له الملائكة: يا لوط إنا رسل ربك، لن يصلوا إليك بأدنى أذى، فاخرج بأهلك بطائفة من الليل، ولا يلتفت منكم أحد كراهة أن يرى ما ينزل بالقوم فيصيبه كرب من ذلك، إلا امرأتك عجوز السوء، فإنها مصيبها ما أصابهم. وسأل لوط عن موعد العذاب، وكان قد استبطأ الوقت، فقالوا: إن موعدهم الصبح، أليس الصبح بقريب؟ فلما جاء أمر الله أمر جبريل ﵇ فقلبها على أهلها، فجعل عالي القرية سافلها، وأمطر عليهم حجارة من طين متحجّر، فمن كان خارج القرية أصابه حجر فأهلكه، مركّب بعضها فوق بعض، معلّمة من عند ربك كل حجر عليه اسم من يُرمى به، وما تلك القرية الهالكة من الظالمين، مشركي العرب، ببعيد، أو وما تلك الحجارة ببعيد نزولها بالظالمين.", "h": ["استحباب السير في الليل لما فيه من البركة بقطع المسافات البعيدة بدون تعب.", "كراهة التأسّف لهلاك الظالمين.", "مظاهر قدرة الله تعالى في قلب أربع مدن في ساعة، فكان الأعلى أسفل والأسفل أعلى.", "وعيد الظالمين في كل زمان ومكان بأشد العقوبات وأفظعها."], "k": "«وما هي من الظالمين ببعيد»… العقوبة ليست حكاية بعيدة؛ فهل أخاف من ذنب أستهين به؟"}]$j$::jsonb then 0 else 1 end;
