insert into public.tdb_cards(topic, i, body) select 148, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٩ – ٧٣", "q": "وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ ﴿٦٩﴾ فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ ﴿٧٠﴾ وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ ﴿٧١﴾ قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ ﴿٧٢﴾ قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ ﴿٧٣﴾", "w": [["بالبشرى", "بإسحاق، ومن وراء إسحاق يعقوب."], ["فما لبث", "ما أبطأ."], ["بعجل حنيذ", "مشويّ على الحجارة."], ["لا تصل إليه", "لم يتناولوه فيأكلوا منه."], ["نكرهم", "لم يعرفهم."], ["وأوجس", "أحسّ بالخوف وشعر به."], ["لوط", "هو ابن هاران أخي إبراهيم ﵇."], ["يا ويلتا", "يا ويلتي احضري، هذا أوان حضورك."], ["وهذا بعلي شيخاً", "إشارة إلى إبراهيم، إذ هو بعلها أي زوجها."], ["إن هذا لشيء عجيب", "أمر يُتعجّب منه استبعاداً له واستغراباً."]], "m": "هذه بشارة إبراهيم ﵇: ولقد جاءت رسلنا، وهم جبريل وميكائيل وإسرافيل، إبراهيم بالبشرى، دخلوا عليه داره فسلّموا فردّ عليهم السلام، فما أبطأ أن جاء بعجل مشويّ على الحجارة فقرّبه إليهم وعرض عليهم الأكل، فلما رأى أيديهم لا تتناوله أنكرهم وأحسّ منهم خيفة، لأن العادة أن الضيف إذا قُدّم إليه طعام فلم يأكل عُرف أنه ينوي شراً. قالوا: لا تخف، إنا أُرسلنا إلى قوم لوط لإهلاكهم بسبب إجرامهم. وكانت امرأته سارة قائمة وراء الستار تخدمهم، فلما سمعت بنبأ هلاك قوم لوط ضحكت فرحاً بهلاك أهل الخبث، فبشّرها الله على لسان الملائكة بإسحاق ومن بعده يعقوب، ولد وولد ولد، فصكّت وجهها تعجباً على عادة النساء وقالت: يا ويلتا أألد وأنا عجوز، فوق التسعين، وهذا بعلي شيخاً، ابن مائة سنة؟ إن هذا لشيء عجيب. قالوا: أتعجبين من أمر الله؟ رحمة الله وبركاته عليكم أهل بيت إبراهيم، إنه حميد محمود بإفضاله وإنعامه عليكم، مجيد ذو مجد وثناء وكرم.", "h": ["استحباب تبشير المؤمن بما هو خير له ولو بالرؤيا الصالحة.", "مشروعية السلام لمن دخل على غيره أو وقف عليه أو مرّ به، ووجوب ردّ السلام.", "مشروعية خدمة أهل البيت لضيوفهم، ووجوب إكرام الضيف، وفي الحديث الصحيح: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه».", "شرف أهل بيت إبراهيم ﵇."], "k": "«فما لبث أن جاء بعجل حنيذ»… أسرع إلى إكرام ضيف لا يعرفه؛ فكيف أستقبل ضيوفي؟"}, {"lbl": "الآيات ٧٤ – ٧٦", "q": "فَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ ﴿٧٤﴾ إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّـٰهٞ مُّنِيبٞ ﴿٧٥﴾ يَـٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودٖ ﴿٧٦﴾", "w": [["الروع", "الفزع والخوف."], ["البشرى", "الخبر السارّ المفرح للقلب."], ["يجادلنا", "يخاصمنا."], ["في قوم لوط", "في شأن هلاك قوم لوط، ولوط هو رسول الله لوط بن هاران بن عم إبراهيم."], ["حليم أواه", "الحليم الذي لا يعامل بالعقوبة، والأوّاه كثير التأوّه مما يسوء."], ["أعرض عن هذا", "اترك الجدال في قوم لوط."], ["غير مردود", "لا يستطيع أحد ردّه، لأن الله تعالى قد قضى به فهو واقع لا محالة."]], "m": "فلما ذهب عن إبراهيم الفزع من الملائكة قبل أن يعرفهم، وجاءته البشرى بالولد وبهلاك قوم لوط، أخذ يجادل الملائكة في شأن هلاكهم لأجل ما بينهم من المؤمنين، فقال: إن فيها لوطاً، فأجابوه: نحن أعلم بمن فيها، لننجّينّه وأهله إلا امرأته كانت من الغابرين. إن إبراهيم لحليم، رقيق القلب لا يعامل بالعقوبة، فأراد تأخير العذاب عنهم لعلهم يتوبون، أوّاه ضارع قانت يُكثر من قول «آه» إذا رأى أو سمع ما يسوء، منيب تواب رجّاع إلى ربه في كل وقت. ولما ألحّ قالوا: يا إبراهيم أعرض عن هذا الجدال، إنه قد جاء أمر ربك بهلاكهم، وإنهم آتيهم عذاب غير مدفوع من أحد.", "h": ["مشروعية الجدال عمّن يُرجى له الخير من الناس، وذلك في غير الحدود الشرعية إذا رُفعت إلى الحاكم.", "فضيلة خلق الحلم.", "فضل الإنابة إلى الله تعالى.", "قضاء الله لا يُردّ، أي ما حكم الله به لا بد واقع."], "k": "«إن إبراهيم لحليم أواه منيب»… ثلاث صفات؛ أيّها أحتاج أن أربّي عليه نفسي؟"}, {"lbl": "الآيات ٧٧ – ٨٠", "q": "وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ ﴿٧٧﴾ وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَـٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ ﴿٧٨﴾ قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ ﴿٧٩﴾ قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ ﴿٨٠﴾", "w": [["سيء بهم", "حصل له غمّ وهمّ بمجيئهم إليه."], ["وضاق بهم ذرعاً", "عجزت طاقته عن تحمّل الأمر."], ["يوم عصيب", "شديد لا يُحتمل."], ["يهرعون إليه", "مدفوعين بدافع الشهوة، يمشون مسرعين."], ["السيئات", "كبائر الذنوب بإتيان الذكور."], ["ولا تخزون في ضيفي", "لا تذلّوني ولا تهينوني بالتعرض لضيفي."], ["رجل رشيد", "ذو رشد وعقل ومعرفة بالأمور وعواقبها."], ["أو آوي إلى ركن شديد", "إلى عشيرة قوية تمنعني منكم، ولم تكن له عشيرة لأنه من غير ديارهم."]], "m": "هذه فاتحة حديث لوط ﵇: ولما جاءت رسلنا، ضيفُ إبراهيم، لوطاً، تضايق وحصل له همّ وغمّ خوفاً عليهم من مجرمي قومه، وعجزت طاقته عن تحمّل الأمر، وقال: هذا يوم شديد لما قد يحدث فيه من تعرّض ضيفه للمذلّة. وجاءه قومه يُسرعون مدفوعين بدافع الشهوة البهيمية، ومن قبلُ كانوا يأتون الرجال في أدبارهم، فأراد أن يصرفهم عن الضيف فقال: يا قوم هؤلاء بناتي، نساء الأمة، هن أطهر لكم فتزوّجوهن، واتقوا الله ولا تهينوني في ضيفي، أليس منكم رجل رشيد يأمر بالمعروف وينهى عن المنكر؟ فأجابوه، لعنهم الله: لقد علمت ما لنا في بناتك من رغبة وحاجة، وإنك لتعلم ما نريد من إتيان الفاحشة في الرجال. قال: لو أن لي بكم قوة من أنصار وأعوان لحُلت بينكم وبين ما تشتهون، أو آوي إلى عشيرة قوية تحميني وضيفي من قومي المجرمين.", "h": ["فضيلة إكرام الضيف وحمايته من كل ما يسوءه.", "فظاعة العادات السيئة وما تُحدثه من تغيّر في الإنسان.", "بذل ما يمكن لدفع الشر، لوقاية لوط ضيفه ببناته.", "أسوأ الحياة أن لا يكون فيها من يأمر بالمعروف وينهى عن المنكر.", "إظهار الرغبة في القوة لدفع الشر وإبعاد المكروه ممدوح."], "k": "«أليس منكم رجل رشيد؟»… حين يُرتكب المنكر أمامي، هل أكون أنا ذلك الرشيد؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ ﴿٨١﴾ فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ ﴿٨٢﴾ مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّـٰلِمِينَ بِبَعِيدٖ ﴿٨٣﴾", "w": [["بقطع من الليل", "بجزء وطائفة من الليل."], ["الصبح", "هو من طلوع الفجر إلى طلوع الشمس."], ["جعلنا عاليها سافلها", "عالي القرية سافلها."], ["من سجيل", "من طين متحجّر."], ["منضود", "منظّم واحدة فوق أخرى بانتظام."], ["مسوّمة", "معلّمة بعلامة خاصة."], ["عند ربك", "معلّمة من عند الله تعالى."]], "m": "بعد أن اشتدّ بلوط الخوف وتأسّف من عدم القدرة على حماية ضيفه، قالت له الملائكة: يا لوط إنا رسل ربك، لن يصلوا إليك بأدنى أذى، فاخرج بأهلك بطائفة من الليل، ولا يلتفت منكم أحد كراهة أن يرى ما ينزل بالقوم فيصيبه كرب من ذلك، إلا امرأتك عجوز السوء، فإنها مصيبها ما أصابهم. وسأل لوط عن موعد العذاب، وكان قد استبطأ الوقت، فقالوا: إن موعدهم الصبح، أليس الصبح بقريب؟ فلما جاء أمر الله أمر جبريل ﵇ فقلبها على أهلها، فجعل عالي القرية سافلها، وأمطر عليهم حجارة من طين متحجّر، فمن كان خارج القرية أصابه حجر فأهلكه، مركّب بعضها فوق بعض، معلّمة من عند ربك كل حجر عليه اسم من يُرمى به، وما تلك القرية الهالكة من الظالمين، مشركي العرب، ببعيد، أو وما تلك الحجارة ببعيد نزولها بالظالمين.", "h": ["استحباب السير في الليل لما فيه من البركة بقطع المسافات البعيدة بدون تعب.", "كراهة التأسّف لهلاك الظالمين.", "مظاهر قدرة الله تعالى في قلب أربع مدن في ساعة، فكان الأعلى أسفل والأسفل أعلى.", "وعيد الظالمين في كل زمان ومكان بأشد العقوبات وأفظعها."], "k": "«وما هي من الظالمين ببعيد»… العقوبة ليست حكاية بعيدة؛ فهل أخاف من ذنب أستهين به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (149, 11, 84, 95, 'سورة هود ٨٤ – ٩٥', 'شعيب ﵇ وأهل مدين: «بقية الله خير لكم»، «إن أريد إلا الإصلاح ما استطعت»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 149) = $j$[{"lbl": "الآيات ٨٤ – ٨٦", "q": "۞وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ ﴿٨٤﴾ وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٨٥﴾ بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ﴿٨٦﴾", "w": [["وإلى مدين", "أرسلنا إلى أهل مدين."], ["المكيال والميزان", "إذا بعتم لأحد فلا تنقصوا المكيال والميزان."], ["بالقسط", "بالعدل، أي بالمساواة والتساوي في البيع والشراء."], ["ولا تبخسوا", "لا تنقصوهم حقوقهم التي هي لهم عليكم في الكيل والوزن وفي غير ذلك."], ["ولا تعثوا في الأرض", "ولا تسعوا في الأرض بالفساد."], ["بقية الله خير لكم", "ما يبقى لكم بعد توفية المكيال والميزان خير لكم من الحرام الذي حرّم الله عليكم."], ["وما أنا عليكم بحفيظ", "رقيب أراقب وزنكم وكيلكم، وإنما أنا واعظ لكم."]], "m": "هذه بداية قصة شعيب ﵇ مع أهل مدين: وأرسلنا إلى قبيلة مدين أخاهم في النسب شعيباً، قال: يا قوم اعبدوا الله، ليس لكم إله يُعبد بحق إلا هو، ربكم الذي خلقكم ورزقكم، ولا تنقصوا المكيال والميزان إذا كلتم أو وزنتم لغيركم، إني أراكم بخير في رخاء وسعة من الرزق، وإني أخاف عليكم إن أصررتم على الشرك والنقص والبخس عذاب يوم يحيط بكم فلا يفلت منكم أحد. ويا قوم أوفوا المكيال والميزان بالعدل، تأكيداً لما نهاهم عنه، ولا تنقصوا الناس حقوقهم من سائر الحقوق، ولا تسعوا في الأرض بالفساد، وهو شامل لكل المعاصي. ما يبقى لكم بعد توفية الناس حقوقهم خير لكم مما تأخذونه بالنقص والبخس، لما في الأول من البركة وفي الثاني من المحق، إن كنتم مؤمنين، وما أنا عليكم بمراقب حين تبيعون وتشترون، ولا محاسب لكم، إنما أنا واعظ ناصح.", "h": ["وحدة دعوة الرسل، وهي البداية بتوحيد الله تعالى أولاً، ثم الأمر والنهي لإكمال الإنسان وإسعاده بعد نجاته من الخسران.", "حرمة نقص الكيل والوزن.", "وجوب الرضا بالحلال وإن قلّ، وسخط الحرام وإن كثر.", "حرمة بخس الناس حقوقهم، كأجور العمال وأسعار البضائع ونحو ذلك.", "حرمة السعي بالفساد في الأرض بأي نوع من الفساد، وأعظمه تعطيل شرائع الله تعالى."], "k": "«بقية الله خير لكم»… القليل الحلال المبارك خير من الكثير الممحوق؛ فهل أوفي الناس حقوقهم كاملة؟"}, {"lbl": "الآيات ٨٧ – ٩٠", "q": "قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَـٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ ﴿٨٧﴾ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴿٨٨﴾ وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ ﴿٨٩﴾ وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ ﴿٩٠﴾", "w": [["أصلاتك", "كثرة الصلاة التي تصلّيها هي التي أثّرت على عقلك، فأصبحت تأمرنا بما لا ينبغي من ترك عبادة آلهتنا والتصرف في أموالنا."], ["الحليم الرشيد", "ذو الحلم والرشد، والحلم ضد الطيش، والرشد ضد السفه، ولم يكن قولهم هذا مدحاً له وإنما هو استهزاء به."], ["أن أخالفكم", "لا أريد أن أنهاكم عن الشيء لتتركوه ثم أفعله."], ["إن أريد إلا الإصلاح", "ما أريد إلا الإصلاح لكم."], ["وما توفيقي إلا بالله", "وما توفيقي للعمل الإصلاحي والقيام به إلا بفضل الله."], ["وإليه أنيب", "أرجع في أمري كله."], ["لا يجرمنّكم شقاقي", "لا تكسبنّكم مخالفتي أن يحلّ بكم من العذاب ما حلّ بقوم نوح والأقوام من بعدهم."], ["وما قوم لوط منكم ببعيد", "في الزمن والمكان، إذ بحيرة لوط قريبة من بلاد مدين."], ["رحيم ودود", "رحيم بالمؤمنين، ودود محب للمتقين."]], "m": "لما أمرهم شعيب بالتوحيد، ونهاهم عن نقص الكيل والوزن وبخس الناس والسعي بالفساد، إذ كانوا يكسرون الدراهم ويقطعون الطريق، قالوا: يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا، أو أن نفعل في أموالنا ما نشاء؟ فنسبوا ذلك إلى كثرة صلاته التي أصابته في نظرهم بضعف العقل، وقولهم: إنك لأنت الحليم الرشيد تهكّم واستهزاء، وإن كان في الواقع كذلك. فقال: يا قوم أخبروني إن كنت على برهان يقيني من ربي، ورزقني منه رزقاً حلالاً طيباً، فهل يليق بي أن أتنكّر لهذا الحق وأجاريكم على باطلكم؟ وما أريد أن أخالفكم إلى ما أنهاكم عنه، فآمركم بتوفية الكيل وأُنقصه، فأكون كمن يأمر بالشيء ولا يفعله فيستحق اللوم ونزع الثقة منه، إن أريد إلا الإصلاح ما استطعت، وما توفيقي إلا بالله، عليه توكلت وإليه أنيب بالطاعة والتوبة. ويا قوم لا يحملنّكم خلافي على الاستمرار في الكفر فيصيبكم مثل ما أصاب قوم نوح بالغرق، أو قوم هود بالريح، أو قوم صالح بالصيحة، وما قوم لوط منكم ببعيد في الزمن والمكان. واستغفروا ربكم ثم توبوا إليه، إن ربي رحيم لا يعذّب من تاب إليه، ودود يحب من أناب إليه.", "h": ["التعريض القريب يعطي حكم القذف الصريح.", "كراهية إتيان الشيء بعد النهي عنه، وترك الشيء بعد الأمر به والحث عليه.", "وجوب الاستغفار والتوبة من الذنوب.", "وصف الرب تعالى بالرحمة والمودة."], "k": "«وما أريد أن أخالفكم إلى ما أنهاكم عنه»… ما أنصح به غيري، هل أنا أول العاملين به؟"}, {"lbl": "الآيات ٩١ – ٩٥", "q": "قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ ﴿٩١﴾ قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ ﴿٩٢﴾ وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ ﴿٩٣﴾ وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ﴿٩٤﴾ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ ﴿٩٥﴾", "w": [["ما نفقه", "ما نفهم بدقة كثيراً من كلامك."], ["ولولا رهطك", "أفراد عشيرتك."], ["وما أنت علينا بعزيز", "بقوي ممتنع."], ["ظهرياً", "لم تأبهوا به ولم تلتفتوا إليه، كالشيء الملقى وراء الظهر."], ["على مكانتكم", "على ما أنتم عليه من حال التمكن والقدرة."], ["الصيحة", "صيحة العذاب التي أخذتهم."], ["جاثمين", "على ركبهم."], ["كأن لم يغنوا فيها", "كأن لم يقيموا بها يوماً."]], "m": "لما قامت الحجة على قوم شعيب لجؤوا إلى القوة والتهديد والشتم، وكان ذلك إيذاناً بقرب هلاكهم، فقالوا: يا شعيب ما نفقه كثيراً مما تقول، مع أنه يخاطبهم بلغتهم، ولكنه الصلف والكبرياء، وإنا لنراك فينا ضعيفاً، احتقاراً له، ولولا جماعة من عشيرتك نحترمهم لقتلناك رمياً بالحجارة، وما أنت علينا بممتنع. قال: يا قوم أرهطي أعزّ عليكم من الله، واتخذتموه وراءكم ظهرياً لا تبالون بأمره ولا نهيه؟ إن ربي بما تعملون محيط علمه وسيجزيكم. ويا قوم اعملوا على تمكّنكم إني عامل على تمكّني، سوف تعلمون من يأتيه عذاب يخزيه ومن هو كاذب، وارتقبوا إني معكم رقيب منتظر. ولما جاء أمرنا نجّينا شعيباً والذين آمنوا معه برحمة منا، وأخذت الذين ظلموا الصيحة التي ارتجفت لها قلوبهم فبركوا على ركبهم هلكى، كأن لم يقيموا في تلك الديار، ألا بُعداً لمدين من الرحمة كما بعدت قبلها ثمود.", "h": ["بيان ما أوتي نبي الله شعيب العربي من فصاحة وبيان، حتى قيل فيه: خطيب الأنبياء.", "اشتداد الأزمات مؤذن بقرب انفراجها.", "بيان فساد عقل من يهتم بتنفيذ أوامر الناس ويهمل أوامر الله تعالى ولا يلتفت إليها.", "فضل انتظار الفرج من الله تعالى، وهو الرجاء المأمور به.", "صدق وعد الله رسله، وعدم تخلّفه أبداً."], "k": "«أرهطي أعز عليكم من الله»… هل أخشى كلام الناس ومكانتهم أكثر مما أخشى ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 149;
insert into public.tdb_cards(topic, i, body) select 149, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٤ – ٨٦", "q": "۞وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ ﴿٨٤﴾ وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٨٥﴾ بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ﴿٨٦﴾", "w": [["وإلى مدين", "أرسلنا إلى أهل مدين."], ["المكيال والميزان", "إذا بعتم لأحد فلا تنقصوا المكيال والميزان."], ["بالقسط", "بالعدل، أي بالمساواة والتساوي في البيع والشراء."], ["ولا تبخسوا", "لا تنقصوهم حقوقهم التي هي لهم عليكم في الكيل والوزن وفي غير ذلك."], ["ولا تعثوا في الأرض", "ولا تسعوا في الأرض بالفساد."], ["بقية الله خير لكم", "ما يبقى لكم بعد توفية المكيال والميزان خير لكم من الحرام الذي حرّم الله عليكم."], ["وما أنا عليكم بحفيظ", "رقيب أراقب وزنكم وكيلكم، وإنما أنا واعظ لكم."]], "m": "هذه بداية قصة شعيب ﵇ مع أهل مدين: وأرسلنا إلى قبيلة مدين أخاهم في النسب شعيباً، قال: يا قوم اعبدوا الله، ليس لكم إله يُعبد بحق إلا هو، ربكم الذي خلقكم ورزقكم، ولا تنقصوا المكيال والميزان إذا كلتم أو وزنتم لغيركم، إني أراكم بخير في رخاء وسعة من الرزق، وإني أخاف عليكم إن أصررتم على الشرك والنقص والبخس عذاب يوم يحيط بكم فلا يفلت منكم أحد. ويا قوم أوفوا المكيال والميزان بالعدل، تأكيداً لما نهاهم عنه، ولا تنقصوا الناس حقوقهم من سائر الحقوق، ولا تسعوا في الأرض بالفساد، وهو شامل لكل المعاصي. ما يبقى لكم بعد توفية الناس حقوقهم خير لكم مما تأخذونه بالنقص والبخس، لما في الأول من البركة وفي الثاني من المحق، إن كنتم مؤمنين، وما أنا عليكم بمراقب حين تبيعون وتشترون، ولا محاسب لكم، إنما أنا واعظ ناصح.", "h": ["وحدة دعوة الرسل، وهي البداية بتوحيد الله تعالى أولاً، ثم الأمر والنهي لإكمال الإنسان وإسعاده بعد نجاته من الخسران.", "حرمة نقص الكيل والوزن.", "وجوب الرضا بالحلال وإن قلّ، وسخط الحرام وإن كثر.", "حرمة بخس الناس حقوقهم، كأجور العمال وأسعار البضائع ونحو ذلك.", "حرمة السعي بالفساد في الأرض بأي نوع من الفساد، وأعظمه تعطيل شرائع الله تعالى."], "k": "«بقية الله خير لكم»… القليل الحلال المبارك خير من الكثير الممحوق؛ فهل أوفي الناس حقوقهم كاملة؟"}, {"lbl": "الآيات ٨٧ – ٩٠", "q": "قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَـٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ ﴿٨٧﴾ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴿٨٨﴾ وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ ﴿٨٩﴾ وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ ﴿٩٠﴾", "w": [["أصلاتك", "كثرة الصلاة التي تصلّيها هي التي أثّرت على عقلك، فأصبحت تأمرنا بما لا ينبغي من ترك عبادة آلهتنا والتصرف في أموالنا."], ["الحليم الرشيد", "ذو الحلم والرشد، والحلم ضد الطيش، والرشد ضد السفه، ولم يكن قولهم هذا مدحاً له وإنما هو استهزاء به."], ["أن أخالفكم", "لا أريد أن أنهاكم عن الشيء لتتركوه ثم أفعله."], ["إن أريد إلا الإصلاح", "ما أريد إلا الإصلاح لكم."], ["وما توفيقي إلا بالله", "وما توفيقي للعمل الإصلاحي والقيام به إلا بفضل الله."], ["وإليه أنيب", "أرجع في أمري كله."], ["لا يجرمنّكم شقاقي", "لا تكسبنّكم مخالفتي أن يحلّ بكم من العذاب ما حلّ بقوم نوح والأقوام من بعدهم."], ["وما قوم لوط منكم ببعيد", "في الزمن والمكان، إذ بحيرة لوط قريبة من بلاد مدين."], ["رحيم ودود", "رحيم بالمؤمنين، ودود محب للمتقين."]], "m": "لما أمرهم شعيب بالتوحيد، ونهاهم عن نقص الكيل والوزن وبخس الناس والسعي بالفساد، إذ كانوا يكسرون الدراهم ويقطعون الطريق، قالوا: يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا، أو أن نفعل في أموالنا ما نشاء؟ فنسبوا ذلك إلى كثرة صلاته التي أصابته في نظرهم بضعف العقل، وقولهم: إنك لأنت الحليم الرشيد تهكّم واستهزاء، وإن كان في الواقع كذلك. فقال: يا قوم أخبروني إن كنت على برهان يقيني من ربي، ورزقني منه رزقاً حلالاً طيباً، فهل يليق بي أن أتنكّر لهذا الحق وأجاريكم على باطلكم؟ وما أريد أن أخالفكم إلى ما أنهاكم عنه، فآمركم بتوفية الكيل وأُنقصه، فأكون كمن يأمر بالشيء ولا يفعله فيستحق اللوم ونزع الثقة منه، إن أريد إلا الإصلاح ما استطعت، وما توفيقي إلا بالله، عليه توكلت وإليه أنيب بالطاعة والتوبة. ويا قوم لا يحملنّكم خلافي على الاستمرار في الكفر فيصيبكم مثل ما أصاب قوم نوح بالغرق، أو قوم هود بالريح، أو قوم صالح بالصيحة، وما قوم لوط منكم ببعيد في الزمن والمكان. واستغفروا ربكم ثم توبوا إليه، إن ربي رحيم لا يعذّب من تاب إليه، ودود يحب من أناب إليه.", "h": ["التعريض القريب يعطي حكم القذف الصريح.", "كراهية إتيان الشيء بعد النهي عنه، وترك الشيء بعد الأمر به والحث عليه.", "وجوب الاستغفار والتوبة من الذنوب.", "وصف الرب تعالى بالرحمة والمودة."], "k": "«وما أريد أن أخالفكم إلى ما أنهاكم عنه»… ما أنصح به غيري، هل أنا أول العاملين به؟"}, {"lbl": "الآيات ٩١ – ٩٥", "q": "قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ ﴿٩١﴾ قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ ﴿٩٢﴾ وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ ﴿٩٣﴾ وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ﴿٩٤﴾ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ ﴿٩٥﴾", "w": [["ما نفقه", "ما نفهم بدقة كثيراً من كلامك."], ["ولولا رهطك", "أفراد عشيرتك."], ["وما أنت علينا بعزيز", "بقوي ممتنع."], ["ظهرياً", "لم تأبهوا به ولم تلتفتوا إليه، كالشيء الملقى وراء الظهر."], ["على مكانتكم", "على ما أنتم عليه من حال التمكن والقدرة."], ["الصيحة", "صيحة العذاب التي أخذتهم."], ["جاثمين", "على ركبهم."], ["كأن لم يغنوا فيها", "كأن لم يقيموا بها يوماً."]], "m": "لما قامت الحجة على قوم شعيب لجؤوا إلى القوة والتهديد والشتم، وكان ذلك إيذاناً بقرب هلاكهم، فقالوا: يا شعيب ما نفقه كثيراً مما تقول، مع أنه يخاطبهم بلغتهم، ولكنه الصلف والكبرياء، وإنا لنراك فينا ضعيفاً، احتقاراً له، ولولا جماعة من عشيرتك نحترمهم لقتلناك رمياً بالحجارة، وما أنت علينا بممتنع. قال: يا قوم أرهطي أعزّ عليكم من الله، واتخذتموه وراءكم ظهرياً لا تبالون بأمره ولا نهيه؟ إن ربي بما تعملون محيط علمه وسيجزيكم. ويا قوم اعملوا على تمكّنكم إني عامل على تمكّني، سوف تعلمون من يأتيه عذاب يخزيه ومن هو كاذب، وارتقبوا إني معكم رقيب منتظر. ولما جاء أمرنا نجّينا شعيباً والذين آمنوا معه برحمة منا، وأخذت الذين ظلموا الصيحة التي ارتجفت لها قلوبهم فبركوا على ركبهم هلكى، كأن لم يقيموا في تلك الديار، ألا بُعداً لمدين من الرحمة كما بعدت قبلها ثمود.", "h": ["بيان ما أوتي نبي الله شعيب العربي من فصاحة وبيان، حتى قيل فيه: خطيب الأنبياء.", "اشتداد الأزمات مؤذن بقرب انفراجها.", "بيان فساد عقل من يهتم بتنفيذ أوامر الناس ويهمل أوامر الله تعالى ولا يلتفت إليها.", "فضل انتظار الفرج من الله تعالى، وهو الرجاء المأمور به.", "صدق وعد الله رسله، وعدم تخلّفه أبداً."], "k": "«أرهطي أعز عليكم من الله»… هل أخشى كلام الناس ومكانتهم أكثر مما أخشى ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (150, 11, 96, 109, 'سورة هود ٩٦ – ١٠٩', '«وما ظلمناهم ولكن ظلموا أنفسهم»، و«فمنهم شقي وسعيد»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 150) = $j$[{"lbl": "الآيات ٩٦ – ٩٩", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٩٦﴾ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدٖ ﴿٩٧﴾ يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ ﴿٩٨﴾ وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ ﴿٩٩﴾", "w": [["موسى", "هو موسى بن عمران، كليم الله ورسوله إلى بني إسرائيل."], ["بآياتنا", "هي الآيات التسع التي ذُكر أكثرها في آية الأعراف."], ["وسلطان مبين", "حجة قوية على عدو الله فرعون فهزمه بها."], ["وملئه", "أشراف رجال دولة فرعون."], ["وما أمر فرعون برشيد", "بذي رشد، بل هو السفه كله."], ["يقدم قومه", "يتقدّمهم إلى النار فأوردهم النار."], ["بئس الرفد المرفود", "قبُح الرفد الذي هو العطاء المرفود به، أي المعطى لهم، والمراد لعنة الدنيا ولعنة الآخرة."]], "m": "هذه لمحة خاطفة لقصة موسى ﵇ في أربع آيات: ولقد أرسلنا موسى بعد شعيب، مصحوباً بآياتنا الدالة على رسالته، وحجة قوية ظاهرة على وجوب توحيد الله وبطلان ألوهية من عداه كفرعون الذي قال: ما علمت لكم من إله غيري، أرسلناه إلى فرعون وأشراف جنده وزعماء دولته، فأمرهم باتباع الحق فأبوا واتبعوا أمر فرعون فأضلّهم، وما أمر فرعون برشيد يهدي إلى الفلاح. يتقدّم قومه يوم القيامة إلى النار فيوردهم حياضها، وبئس الورد المورود نار جهنم. وأُتبعوا في هذه الدنيا لعنة، ويوم القيامة يُلعنون أيضاً، بئس العطاء المعطى لهم: لعنة الدنيا ولعنة الآخرة.", "h": ["من كتب الله شقاءه لا يؤمن بالآيات، بل يردّها ويكذّب بها حتى يهلك.", "قوة الحجج وكثرة البراهين لا تستلزم إذعان الناس وإيمانهم.", "التحذير من اتباع رؤساء الشر وأئمة الفساد والضلال.", "ذم موارد الباطل والشر والفساد.", "شر المعذّبين من جُمع له بين عذاب الدنيا وعذاب الآخرة."], "k": "«يقدم قومه يوم القيامة»… من أتّبعه اليوم سيتقدّمني غداً؛ فإلى أين يقودني؟"}, {"lbl": "الآيات ١٠٠ – ١٠٢", "q": "ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ مِنۡهَا قَآئِمٞ وَحَصِيدٞ ﴿١٠٠﴾ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبٖ ﴿١٠١﴾ وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ ﴿١٠٢﴾", "w": [["ذلك", "الإشارة إلى قصص الأنبياء الذي تقدّم في السورة."], ["من أنباء القرى", "أخبار أهل القرى: قوم نوح، وعاد، وثمود، وقوم لوط، وأصحاب مدين، وفرعون."], ["منها قائم وحصيد", "منها مدن بقيت آثارها كمدائن صالح، ومنها مدن لم يبق منها شيء كديار عاد."], ["التي يدعون", "يعبدونها بالدعاء وغيره، كالذبح لها والنذور والحلف."], ["غير تتبيب", "تخسير وهلاك."], ["إذا أخذ القرى", "عاقبها بذنوبها."]], "m": "لما قصّ تعالى على رسوله ﷺ أخبار الأمم السابقة قال: ذلك من أنباء أهل القرى نقصّه عليك تقريراً لنبوتك وتثبيتاً لفؤادك وتسلية لك، منها آثار قائمة من جدران وأطلال، ومنها ما هو كالزرع المحصود ليس فيه قائم ولا شاخص. وما ظلمناهم بإهلاكهم، ولكن ظلموا أنفسهم بالشرك والمعاصي والمجاحدة لآياتنا والمكابرة لرسلنا، فما أغنت عنهم آلهتهم التي عبدوها بالدعاء والنذر والذبح والتعظيم من شيء لما جاء أمر ربك بعذابهم، وما زادوهم غير تخسير ودمار. وكذلك أخذ ربك إذا أخذ القرى، العواصم والحواضر بمن فيها، وهي ظالمة بالشرك والمعاصي، إن أخذه أليم شديد لا يطاق، فهل يعتبر الظالمون اليوم قبل أن يأخذهم الله كما أخذ من قبلهم؟", "h": ["تقرير نبوة محمد ﷺ ونشر رسالته، وتسليته بما يقصّ الله عليه من أنباء السابقين.", "تنزّه الله تعالى عن الظلم في إهلاك أهل الشرك والمعاصي.", "آلهة المشركين لم تغن عنهم عند حلول النقمة بهم شيئاً.", "التنديد بالظلم وسوء عاقبة الظالمين."], "k": "«وما ظلمناهم ولكن ظلموا أنفسهم»… كل ما أصابني من سوء، أليس من نفسي أولاً؟"}, {"lbl": "الآيات ١٠٣ – ١٠٩", "q": "إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ ذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ ﴿١٠٣﴾ وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ ﴿١٠٤﴾ يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيّٞ وَسَعِيدٞ ﴿١٠٥﴾ فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ ﴿١٠٦﴾ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ ﴿١٠٧﴾ ۞وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ ﴿١٠٨﴾ فَلَا تَكُ فِي مِرۡيَةٖ مِّمَّا يَعۡبُدُ هَـٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصٖ ﴿١٠٩﴾", "w": [["لآية", "علامة على أن الذي عذّب في الدنيا قادر على أن يعذّب في الآخرة."], ["يوم مشهود", "يشهده جميع الخلائق، وهو يوم القيامة."], ["إلا لأجل معدود", "أجل الدنيا المعدود الأيام والساعات."], ["إلا بإذنه", "إلا بإذن الله تعالى."], ["شقي وسعيد", "فمن أهل الموقف من هو شقي أزلاً وسيدخل النار، ومنهم سعيد أزلاً وسيدخل الجنة."], ["زفير وشهيق", "صوت شديد وهو الزفير، وصوت ضعيف وهو الشهيق."], ["عطاء غير مجذوذ", "غير مقطوع، بل هو دائم أبداً."], ["فلا تك في مرية مما يعبد هؤلاء", "في شك من بطلان عبادة هؤلاء المشركين."], ["نصيبهم غير منقوص", "ما قُدّر لهم من خير أو شر، رحمة أو عذاب."]], "m": "إن في أخذ الله للأمم الظالمة وتعذيبها لآية واضحة على أن من عذّب في الدنيا قادر على أن يعذّب في الآخرة، يجد فيها المؤمنون بلقاء الله عبرة فيواصلون تقواهم. ذلك يوم القيامة، يوم مجموع له الناس لفصل القضاء، ويوم تشهده الخلائق كلها، وما نؤخّره إلا لإكمال عمر الدنيا المعدود بالسنين والأيام بل والساعات. يوم يأتي لا تكلّم نفس إلا بإذن الله، فمنهم شقي ومنهم سعيد، بما كُتب لكل إنسان في كتاب المقادير أولاً، ولما كسب من خير وشر ثانياً. فأما الذين شقوا ففي النار، لهم فيها زفير وشهيق، صوتان متلازمان، خالدين فيها ما دامت السماوات والأرض، إلا ما شاء ربك ألّا يخلد فيها، وهم أهل التوحيد ممن ماتوا على كبائر الذنوب، إن ربك فعّال لما يريد. وأما الذين سعدوا بما وفّقهم الله من الإيمان والعمل الصالح ففي الجنة خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك، إذ إرادة الله مطلقة، عطاءً من ربك غير مقطوع أبداً، وهذا دليل خلودهم فيها أبداً. فلا تك في شك من بطلان عبادة المشركين أصنامهم، فلا دليل لهم عليها، وإنما هم مقلّدون لآبائهم، وإنا لموفّوهم ما كُتب لهم من خير وشر توفية كاملة لا نقص فيها.", "h": ["فضل وفضيلة الإيمان بالآخرة.", "حتمية البعث الآخر، وأنه لا شك فيه.", "الشقاوة والسعادة مضى بهما القضاء والقدر قبل وجود الأشقياء والسعداء.", "عجز كل نفس عن الكلام يوم القيامة حتى يؤذن لها به.", "إرادة الله مطلقة، فلو شاء أن يُخرج أهل النار منها لأخرجهم."], "k": "«فمنهم شقي وسعيد»… الطريق إلى السعادة بيّن؛ فهل أعمل اليوم عمل السعداء؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 150;
insert into public.tdb_cards(topic, i, body) select 150, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٦ – ٩٩", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٩٦﴾ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدٖ ﴿٩٧﴾ يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ ﴿٩٨﴾ وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ ﴿٩٩﴾", "w": [["موسى", "هو موسى بن عمران، كليم الله ورسوله إلى بني إسرائيل."], ["بآياتنا", "هي الآيات التسع التي ذُكر أكثرها في آية الأعراف."], ["وسلطان مبين", "حجة قوية على عدو الله فرعون فهزمه بها."], ["وملئه", "أشراف رجال دولة فرعون."], ["وما أمر فرعون برشيد", "بذي رشد، بل هو السفه كله."], ["يقدم قومه", "يتقدّمهم إلى النار فأوردهم النار."], ["بئس الرفد المرفود", "قبُح الرفد الذي هو العطاء المرفود به، أي المعطى لهم، والمراد لعنة الدنيا ولعنة الآخرة."]], "m": "هذه لمحة خاطفة لقصة موسى ﵇ في أربع آيات: ولقد أرسلنا موسى بعد شعيب، مصحوباً بآياتنا الدالة على رسالته، وحجة قوية ظاهرة على وجوب توحيد الله وبطلان ألوهية من عداه كفرعون الذي قال: ما علمت لكم من إله غيري، أرسلناه إلى فرعون وأشراف جنده وزعماء دولته، فأمرهم باتباع الحق فأبوا واتبعوا أمر فرعون فأضلّهم، وما أمر فرعون برشيد يهدي إلى الفلاح. يتقدّم قومه يوم القيامة إلى النار فيوردهم حياضها، وبئس الورد المورود نار جهنم. وأُتبعوا في هذه الدنيا لعنة، ويوم القيامة يُلعنون أيضاً، بئس العطاء المعطى لهم: لعنة الدنيا ولعنة الآخرة.", "h": ["من كتب الله شقاءه لا يؤمن بالآيات، بل يردّها ويكذّب بها حتى يهلك.", "قوة الحجج وكثرة البراهين لا تستلزم إذعان الناس وإيمانهم.", "التحذير من اتباع رؤساء الشر وأئمة الفساد والضلال.", "ذم موارد الباطل والشر والفساد.", "شر المعذّبين من جُمع له بين عذاب الدنيا وعذاب الآخرة."], "k": "«يقدم قومه يوم القيامة»… من أتّبعه اليوم سيتقدّمني غداً؛ فإلى أين يقودني؟"}, {"lbl": "الآيات ١٠٠ – ١٠٢", "q": "ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ مِنۡهَا قَآئِمٞ وَحَصِيدٞ ﴿١٠٠﴾ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبٖ ﴿١٠١﴾ وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ ﴿١٠٢﴾", "w": [["ذلك", "الإشارة إلى قصص الأنبياء الذي تقدّم في السورة."], ["من أنباء القرى", "أخبار أهل القرى: قوم نوح، وعاد، وثمود، وقوم لوط، وأصحاب مدين، وفرعون."], ["منها قائم وحصيد", "منها مدن بقيت آثارها كمدائن صالح، ومنها مدن لم يبق منها شيء كديار عاد."], ["التي يدعون", "يعبدونها بالدعاء وغيره، كالذبح لها والنذور والحلف."], ["غير تتبيب", "تخسير وهلاك."], ["إذا أخذ القرى", "عاقبها بذنوبها."]], "m": "لما قصّ تعالى على رسوله ﷺ أخبار الأمم السابقة قال: ذلك من أنباء أهل القرى نقصّه عليك تقريراً لنبوتك وتثبيتاً لفؤادك وتسلية لك، منها آثار قائمة من جدران وأطلال، ومنها ما هو كالزرع المحصود ليس فيه قائم ولا شاخص. وما ظلمناهم بإهلاكهم، ولكن ظلموا أنفسهم بالشرك والمعاصي والمجاحدة لآياتنا والمكابرة لرسلنا، فما أغنت عنهم آلهتهم التي عبدوها بالدعاء والنذر والذبح والتعظيم من شيء لما جاء أمر ربك بعذابهم، وما زادوهم غير تخسير ودمار. وكذلك أخذ ربك إذا أخذ القرى، العواصم والحواضر بمن فيها، وهي ظالمة بالشرك والمعاصي، إن أخذه أليم شديد لا يطاق، فهل يعتبر الظالمون اليوم قبل أن يأخذهم الله كما أخذ من قبلهم؟", "h": ["تقرير نبوة محمد ﷺ ونشر رسالته، وتسليته بما يقصّ الله عليه من أنباء السابقين.", "تنزّه الله تعالى عن الظلم في إهلاك أهل الشرك والمعاصي.", "آلهة المشركين لم تغن عنهم عند حلول النقمة بهم شيئاً.", "التنديد بالظلم وسوء عاقبة الظالمين."], "k": "«وما ظلمناهم ولكن ظلموا أنفسهم»… كل ما أصابني من سوء، أليس من نفسي أولاً؟"}, {"lbl": "الآيات ١٠٣ – ١٠٩", "q": "إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ ذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ ﴿١٠٣﴾ وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ ﴿١٠٤﴾ يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيّٞ وَسَعِيدٞ ﴿١٠٥﴾ فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ ﴿١٠٦﴾ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ ﴿١٠٧﴾ ۞وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ ﴿١٠٨﴾ فَلَا تَكُ فِي مِرۡيَةٖ مِّمَّا يَعۡبُدُ هَـٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصٖ ﴿١٠٩﴾", "w": [["لآية", "علامة على أن الذي عذّب في الدنيا قادر على أن يعذّب في الآخرة."], ["يوم مشهود", "يشهده جميع الخلائق، وهو يوم القيامة."], ["إلا لأجل معدود", "أجل الدنيا المعدود الأيام والساعات."], ["إلا بإذنه", "إلا بإذن الله تعالى."], ["شقي وسعيد", "فمن أهل الموقف من هو شقي أزلاً وسيدخل النار، ومنهم سعيد أزلاً وسيدخل الجنة."], ["زفير وشهيق", "صوت شديد وهو الزفير، وصوت ضعيف وهو الشهيق."], ["عطاء غير مجذوذ", "غير مقطوع، بل هو دائم أبداً."], ["فلا تك في مرية مما يعبد هؤلاء", "في شك من بطلان عبادة هؤلاء المشركين."], ["نصيبهم غير منقوص", "ما قُدّر لهم من خير أو شر، رحمة أو عذاب."]], "m": "إن في أخذ الله للأمم الظالمة وتعذيبها لآية واضحة على أن من عذّب في الدنيا قادر على أن يعذّب في الآخرة، يجد فيها المؤمنون بلقاء الله عبرة فيواصلون تقواهم. ذلك يوم القيامة، يوم مجموع له الناس لفصل القضاء، ويوم تشهده الخلائق كلها، وما نؤخّره إلا لإكمال عمر الدنيا المعدود بالسنين والأيام بل والساعات. يوم يأتي لا تكلّم نفس إلا بإذن الله، فمنهم شقي ومنهم سعيد، بما كُتب لكل إنسان في كتاب المقادير أولاً، ولما كسب من خير وشر ثانياً. فأما الذين شقوا ففي النار، لهم فيها زفير وشهيق، صوتان متلازمان، خالدين فيها ما دامت السماوات والأرض، إلا ما شاء ربك ألّا يخلد فيها، وهم أهل التوحيد ممن ماتوا على كبائر الذنوب، إن ربك فعّال لما يريد. وأما الذين سعدوا بما وفّقهم الله من الإيمان والعمل الصالح ففي الجنة خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك، إذ إرادة الله مطلقة، عطاءً من ربك غير مقطوع أبداً، وهذا دليل خلودهم فيها أبداً. فلا تك في شك من بطلان عبادة المشركين أصنامهم، فلا دليل لهم عليها، وإنما هم مقلّدون لآبائهم، وإنا لموفّوهم ما كُتب لهم من خير وشر توفية كاملة لا نقص فيها.", "h": ["فضل وفضيلة الإيمان بالآخرة.", "حتمية البعث الآخر، وأنه لا شك فيه.", "الشقاوة والسعادة مضى بهما القضاء والقدر قبل وجود الأشقياء والسعداء.", "عجز كل نفس عن الكلام يوم القيامة حتى يؤذن لها به.", "إرادة الله مطلقة، فلو شاء أن يُخرج أهل النار منها لأخرجهم."], "k": "«فمنهم شقي وسعيد»… الطريق إلى السعادة بيّن؛ فهل أعمل اليوم عمل السعداء؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (151, 11, 110, 123, 'سورة هود ١١٠ – ١٢٣', '«فاستقم كما أمرت»، «إن الحسنات يذهبن السيئات»، «وكلاً نقص عليك من أنباء الرسل»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 151) = $j$[{"lbl": "الآيات ١١٠ – ١١٣", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿١١٠﴾ وَإِنَّ كُلّٗا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ خَبِيرٞ ﴿١١١﴾ فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١١٢﴾ وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ ﴿١١٣﴾", "w": [["الكتاب", "التوراة."], ["ولولا كلمة سبقت", "لولا ما جرى به قلم القدر من تأخير الحساب والجزاء إلى يوم القيامة."], ["لفي شك منه مريب", "موقع في الريب الذي هو اضطراب النفس وقلقها."], ["فاستقم كما أمرت", "على الأمر والنهي كما أمرك ربك بدون تقصير."], ["ولا تطغوا", "لا تجاوزوا حدود الله."], ["ولا تركنوا إلى الذين ظلموا", "لا تميلوا إليهم بموادّة أو رضا بأعمالهم."], ["فتمسكم النار", "تصيبكم، ولازم ذلك دخولها."]], "m": "ما زال السياق في تسلية النبي ﷺ وحمله على الصبر: ولقد آتينا موسى التوراة كما أنزلنا عليك القرآن، فاختلفت اليهود فيها فمنهم من آمن ومنهم من كفر، كما اختلف قومك في القرآن، فلا تحزن. ولولا كلمة سبقت من ربك بتأخير الجزاء إلى يوم القيامة لقُضي بينهم فنجّى المؤمنين وأهلك الكافرين، وإن قومك لفي شك من القرآن موقع في الريب والحيرة. وإن كلاً من العباد، مؤمناً أو كافراً، براً أو فاجراً، ليوفّينّه ربك جزاء عمله يوم القيامة، إنه بما يعملون خبير. فاستقم كما أمرك ربك، فاعتقد الحق واعمل الصالح واترك الباطل، أنت ومن تاب معك من المؤمنين، ولا تتجاوزوا ما حُدّ لكم في الاعتقاد والقول والعمل، إنه بما تعملون بصير، تحذيراً وتهديداً لمن طغى فتجاوز منهج الاعتدال. ولا تميلوا إلى المشركين بمداهنتهم أو الرضا بشركهم فتمسّكم النار كما مسّتهم، وما لكم من دون الله من وليّ يدافع عنكم، ثم لا تُنصرون. وهذا التحذير وإن وُجّه إلى الرسول ﷺ ابتداءً فالمقصود به أمته، أما هو ﷺ فمعصوم من أقل من الشرك فكيف بالشرك.", "h": ["تسلية الرسول ﷺ والتخفيف عنه مما يجده من جحود الكافرين.", "بيان سبب تأخّر العذاب في الدنيا، وهو أن الجزاء في الآخرة لا في الدنيا.", "الجزاء الأخروي حتمي لا يتخلّف أبداً، إذ به حكم الحق عز وجل.", "وجوب الاستقامة على دين الله تعالى عقيدةً وعبادةً وحكماً وأدباً.", "حرمة الغلوّ وتجاوز ما حدّ الله تعالى في شرعه.", "حرمة مداهنة المشركين أو الرضا بهم أو بعملهم، لأن الرضا بالكفر كفر."], "k": "«فاستقم كما أمرت»… لا كما أهوى، ولا كما يفعل الناس؛ فأين أحتاج أن أستقيم اليوم؟"}, {"lbl": "الآيتان ١١٤ – ١١٥", "q": "وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّـٰكِرِينَ ﴿١١٤﴾ وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿١١٥﴾", "w": [["وأقم الصلاة", "صلِّ الصلاة المفروضة."], ["طرفي النهار", "الصبح، وهي في الطرف الأول، والظهر والعصر، وهما في الطرف الثاني."], ["وزلفاً من الليل", "ساعات الليل، والمراد صلاة المغرب وصلاة العشاء."], ["ذلك ذكرى للذاكرين", "ذلك المذكور من قوله: «وأقم الصلاة» عظة للمتعظين."], ["المحسنين", "الذين يحسنون نياتهم وأقوالهم وأعمالهم بالإخلاص فيها لله، وأدائها على نحو ما شرع الله وبيّن رسوله ﷺ."]], "m": "أرشد الله رسوله والمؤمنين إلى ما فيه كمالهم وسعادتهم فقال: وأقم الصلاة طرفي النهار وزلفاً من الليل، وهذه أوقات الصلوات الخمس: الصبح والظهر والعصر والمغرب والعشاء، ومعنى أقمها: أدّها على الوجه الأكمل لأدائها، فيكون ذلك الأداء حسنات يمحو الله بها السيئات، إن الحسنات يذهبن السيئات. ذلك المأمور به وما يترتب عليه عظة للمتعظين. واصبر على الطاعات فعلاً وتركاً وعلى أذى المشركين ولا تجزع، فإن الله لا يضيع أجر المحسنين يوم القيامة، وهم الذين يخلصون أعمالهم لله ويؤدّونها على الوجه الأكمل فتنتج لهم الحسنات التي يذهب الله بها السيئات.", "h": ["بيان أوقات الصلوات الخمس، إذ طرفا النهار هما الصبح وفيه صلاة الصبح، والعشيّ وفيه صلاة الظهر والعصر، كما أن زلفاً من الليل هي ساعاته وفيها صلاة المغرب والعشاء.", "بيان سنة الله تعالى في أن الحسنة تمحو السيئة، وفي الحديث: «الصلاة إلى الصلاة كفارة لما بينهما ما لم تُغشَ الكبائر».", "وجوب الصبر والإحسان، وأنهما من أفضل الأعمال."], "k": "«إن الحسنات يذهبن السيئات»… بعد كل زلّة، ما الحسنة التي أُتبعها بها لتمحوها؟"}, {"lbl": "الآيات ١١٦ – ١١٩", "q": "فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ ﴿١١٦﴾ وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ ﴿١١٧﴾ وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ ﴿١١٨﴾ إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١١٩﴾", "w": [["فلولا", "كلمة تفيد الحض على الفعل والحث عليه."], ["من القرون", "أهل القرون، والقرن مائة سنة."], ["أولو بقية", "أصحاب بقيّة، أي دين وفضل."], ["ما أترفوا فيه", "ما نُعّموا فيه من طعام وشراب ولباس ومتع."], ["وكانوا مجرمين", "لأنفسهم بارتكاب المعاصي، ولغيرهم بحملهم عليها."], ["بظلم", "منه لها بدون ذنب اقترفته."], ["أمة واحدة", "على دين واحد، وهو الإسلام."], ["ولذلك خلقهم", "خلق أهل الاختلاف للاختلاف، وأهل الرحمة للرحمة."]], "m": "فهلّا كان من أهل القرون من قبلكم أصحاب فهم وعقل وفضل ودين ينهون عن الفساد في الأرض؟ لم يكن ذلك إلا قليلاً ممن أنجى الله من أتباع الرسل عند إهلاك أممهم، وما عداهم كانوا ظالمين لأنفسهم متّبعين ما نُعّموا فيه من ملاذّ الدنيا، وكانوا بذلك مجرمين فأهلكهم الله. وما كان ربك ليهلك القرى بظلم منه وأهلها مصلحون، ولكن يهلكهم بسبب ظلمهم لأنفسهم بالشرك والتكذيب والمعاصي، وهذه سنته في إهلاك الأمم السابقة. ولو شاء ربك لجعل الناس على الإسلام بأن خلق الهداية في قلوبهم، ولما لم يشأ ذلك لا يزالون مختلفين على أديان شتى، وأهل الدين الواحد يختلفون إلى طوائف ومذاهب، إلا من رحم ربك فإنهم لا يختلفون، بل يؤمنون بالله ورسوله ويعملون بطاعتهما، دينهم واحد وأمرهم واحد، وعلى ذلك خلقهم، فمنهم كافر شقي ومنهم مؤمن سعيد، وتمّت كلمة ربك: لأملأنّ جهنم من الجنة والناس أجمعين.", "h": ["ما يزال الناس بخير ما وُجد بينهم أولو الفضل والخير يأمرونهم بالمعروف وينهونهم عن المنكر.", "الترف كثيراً ما يقود إلى الإجرام على النفس باتباع الشهوات وترك الصالحات.", "متى كان أهل القرى صالحين فهم آمنون من كل المخاوف.", "الاتفاق رحمة، والخلاف عذاب."], "k": "«وما كان ربك ليهلك القرى بظلم وأهلها مصلحون»… مصلحون لا صالحون فقط؛ فهل أُصلح فيمن حولي؟"}, {"lbl": "الآيات ١٢٠ – ١٢٣", "q": "وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةٞ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿١٢٠﴾ وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ ﴿١٢١﴾ وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ﴿١٢٢﴾ وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿١٢٣﴾", "w": [["وكلاً نقص", "وكل ما تحتاج إليه من أنباء الرسل نقصّه عليك."], ["ما نثبت به فؤادك", "نقصّ عليك من القصص ما يثبّت قلبك لتصبر على دعوتنا وتبليغها."], ["وجاءك في هذه الحق", "في هذه السورة الحق الثابت من الله تعالى، كما جاءك في غيرها."], ["وموعظة وذكرى", "وجاءك فيها موعظة وذكرى للمؤمنين، إذ هم المنتفعون."], ["ولله غيب السماوات والأرض", "ما غاب علمه فيهما فالله يعلمه وحده، وليس لغيره فيه علم."], ["فاعبده", "وحّده في العبادة ولا تشرك به."], ["وتوكل عليه", "فوّض أمرك إليه وثق تمام الثقة فيه أن يكفيك."]], "m": "لما قصّ تعالى في هذه السورة أنباء الرسل مع أممهم، وما لاقوا من تكذيب وعناد، وكيف صبروا حتى جاءهم النصر، قال لرسوله ﷺ: وكل ما تحتاج إليه من أنباء الرسل نقصّه عليك لنثبّت به قلبك حتى تواصل دعوتك، وجاءك في هذه السورة الحق، وموعظة تعظ بها غيرك، وذكرى يتذكر بها المؤمنون فيثبتون على الحق ويصبرون على الطاعة والبلاء. وقل للذين لا يؤمنون من قومك: اعملوا على حالكم إنا عاملون على حالنا، وانتظروا إنا منتظرون أيّنا ينتصر في النهاية. ولله غيب السماوات والأرض، فهو وحده يعلم متى يجيء النصر، وإليه يرجع الأمر كله: الانتصار والانكسار، والهداية والإضلال، والإسعاد والإشقاء، فاعبده وحده وتوكّل عليه وحده فإنه كافيك كل ما يهمّك، وما ربك بغافل عما تعملون، وسيجزي كلاً بما عمل.", "h": ["بيان فائدة القصص القرآني، وهي أمور منها: تثبيت قلب النبي ﷺ، وإيجاد مواعظ وعبر للمؤمنين، وتقرير نبوة الرسول ﷺ.", "علم الغيب لله وحده، لا يعلمه غيره.", "مردّ الأمور كلها لله بدءاً وعوداً ونهاية."], "k": "«فاعبده وتوكل عليه»… خُتمت السورة بهما؛ عبادة تملأ يومي، وتوكل يريح قلبي."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 151;
insert into public.tdb_cards(topic, i, body) select 151, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٠ – ١١٣", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿١١٠﴾ وَإِنَّ كُلّٗا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ خَبِيرٞ ﴿١١١﴾ فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿١١٢﴾ وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ ﴿١١٣﴾", "w": [["الكتاب", "التوراة."], ["ولولا كلمة سبقت", "لولا ما جرى به قلم القدر من تأخير الحساب والجزاء إلى يوم القيامة."], ["لفي شك منه مريب", "موقع في الريب الذي هو اضطراب النفس وقلقها."], ["فاستقم كما أمرت", "على الأمر والنهي كما أمرك ربك بدون تقصير."], ["ولا تطغوا", "لا تجاوزوا حدود الله."], ["ولا تركنوا إلى الذين ظلموا", "لا تميلوا إليهم بموادّة أو رضا بأعمالهم."], ["فتمسكم النار", "تصيبكم، ولازم ذلك دخولها."]], "m": "ما زال السياق في تسلية النبي ﷺ وحمله على الصبر: ولقد آتينا موسى التوراة كما أنزلنا عليك القرآن، فاختلفت اليهود فيها فمنهم من آمن ومنهم من كفر، كما اختلف قومك في القرآن، فلا تحزن. ولولا كلمة سبقت من ربك بتأخير الجزاء إلى يوم القيامة لقُضي بينهم فنجّى المؤمنين وأهلك الكافرين، وإن قومك لفي شك من القرآن موقع في الريب والحيرة. وإن كلاً من العباد، مؤمناً أو كافراً، براً أو فاجراً، ليوفّينّه ربك جزاء عمله يوم القيامة، إنه بما يعملون خبير. فاستقم كما أمرك ربك، فاعتقد الحق واعمل الصالح واترك الباطل، أنت ومن تاب معك من المؤمنين، ولا تتجاوزوا ما حُدّ لكم في الاعتقاد والقول والعمل، إنه بما تعملون بصير، تحذيراً وتهديداً لمن طغى فتجاوز منهج الاعتدال. ولا تميلوا إلى المشركين بمداهنتهم أو الرضا بشركهم فتمسّكم النار كما مسّتهم، وما لكم من دون الله من وليّ يدافع عنكم، ثم لا تُنصرون. وهذا التحذير وإن وُجّه إلى الرسول ﷺ ابتداءً فالمقصود به أمته، أما هو ﷺ فمعصوم من أقل من الشرك فكيف بالشرك.", "h": ["تسلية الرسول ﷺ والتخفيف عنه مما يجده من جحود الكافرين.", "بيان سبب تأخّر العذاب في الدنيا، وهو أن الجزاء في الآخرة لا في الدنيا.", "الجزاء الأخروي حتمي لا يتخلّف أبداً، إذ به حكم الحق عز وجل.", "وجوب الاستقامة على دين الله تعالى عقيدةً وعبادةً وحكماً وأدباً.", "حرمة الغلوّ وتجاوز ما حدّ الله تعالى في شرعه.", "حرمة مداهنة المشركين أو الرضا بهم أو بعملهم، لأن الرضا بالكفر كفر."], "k": "«فاستقم كما أمرت»… لا كما أهوى، ولا كما يفعل الناس؛ فأين أحتاج أن أستقيم اليوم؟"}, {"lbl": "الآيتان ١١٤ – ١١٥", "q": "وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّـٰكِرِينَ ﴿١١٤﴾ وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿١١٥﴾", "w": [["وأقم الصلاة", "صلِّ الصلاة المفروضة."], ["طرفي النهار", "الصبح، وهي في الطرف الأول، والظهر والعصر، وهما في الطرف الثاني."], ["وزلفاً من الليل", "ساعات الليل، والمراد صلاة المغرب وصلاة العشاء."], ["ذلك ذكرى للذاكرين", "ذلك المذكور من قوله: «وأقم الصلاة» عظة للمتعظين."], ["المحسنين", "الذين يحسنون نياتهم وأقوالهم وأعمالهم بالإخلاص فيها لله، وأدائها على نحو ما شرع الله وبيّن رسوله ﷺ."]], "m": "أرشد الله رسوله والمؤمنين إلى ما فيه كمالهم وسعادتهم فقال: وأقم الصلاة طرفي النهار وزلفاً من الليل، وهذه أوقات الصلوات الخمس: الصبح والظهر والعصر والمغرب والعشاء، ومعنى أقمها: أدّها على الوجه الأكمل لأدائها، فيكون ذلك الأداء حسنات يمحو الله بها السيئات، إن الحسنات يذهبن السيئات. ذلك المأمور به وما يترتب عليه عظة للمتعظين. واصبر على الطاعات فعلاً وتركاً وعلى أذى المشركين ولا تجزع، فإن الله لا يضيع أجر المحسنين يوم القيامة، وهم الذين يخلصون أعمالهم لله ويؤدّونها على الوجه الأكمل فتنتج لهم الحسنات التي يذهب الله بها السيئات.", "h": ["بيان أوقات الصلوات الخمس، إذ طرفا النهار هما الصبح وفيه صلاة الصبح، والعشيّ وفيه صلاة الظهر والعصر، كما أن زلفاً من الليل هي ساعاته وفيها صلاة المغرب والعشاء.", "بيان سنة الله تعالى في أن الحسنة تمحو السيئة، وفي الحديث: «الصلاة إلى الصلاة كفارة لما بينهما ما لم تُغشَ الكبائر».", "وجوب الصبر والإحسان، وأنهما من أفضل الأعمال."], "k": "«إن الحسنات يذهبن السيئات»… بعد كل زلّة، ما الحسنة التي أُتبعها بها لتمحوها؟"}, {"lbl": "الآيات ١١٦ – ١١٩", "q": "فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ ﴿١١٦﴾ وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ ﴿١١٧﴾ وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ ﴿١١٨﴾ إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١١٩﴾", "w": [["فلولا", "كلمة تفيد الحض على الفعل والحث عليه."], ["من القرون", "أهل القرون، والقرن مائة سنة."], ["أولو بقية", "أصحاب بقيّة، أي دين وفضل."], ["ما أترفوا فيه", "ما نُعّموا فيه من طعام وشراب ولباس ومتع."], ["وكانوا مجرمين", "لأنفسهم بارتكاب المعاصي، ولغيرهم بحملهم عليها."], ["بظلم", "منه لها بدون ذنب اقترفته."], ["أمة واحدة", "على دين واحد، وهو الإسلام."], ["ولذلك خلقهم", "خلق أهل الاختلاف للاختلاف، وأهل الرحمة للرحمة."]], "m": "فهلّا كان من أهل القرون من قبلكم أصحاب فهم وعقل وفضل ودين ينهون عن الفساد في الأرض؟ لم يكن ذلك إلا قليلاً ممن أنجى الله من أتباع الرسل عند إهلاك أممهم، وما عداهم كانوا ظالمين لأنفسهم متّبعين ما نُعّموا فيه من ملاذّ الدنيا، وكانوا بذلك مجرمين فأهلكهم الله. وما كان ربك ليهلك القرى بظلم منه وأهلها مصلحون، ولكن يهلكهم بسبب ظلمهم لأنفسهم بالشرك والتكذيب والمعاصي، وهذه سنته في إهلاك الأمم السابقة. ولو شاء ربك لجعل الناس على الإسلام بأن خلق الهداية في قلوبهم، ولما لم يشأ ذلك لا يزالون مختلفين على أديان شتى، وأهل الدين الواحد يختلفون إلى طوائف ومذاهب، إلا من رحم ربك فإنهم لا يختلفون، بل يؤمنون بالله ورسوله ويعملون بطاعتهما، دينهم واحد وأمرهم واحد، وعلى ذلك خلقهم، فمنهم كافر شقي ومنهم مؤمن سعيد، وتمّت كلمة ربك: لأملأنّ جهنم من الجنة والناس أجمعين.", "h": ["ما يزال الناس بخير ما وُجد بينهم أولو الفضل والخير يأمرونهم بالمعروف وينهونهم عن المنكر.", "الترف كثيراً ما يقود إلى الإجرام على النفس باتباع الشهوات وترك الصالحات.", "متى كان أهل القرى صالحين فهم آمنون من كل المخاوف.", "الاتفاق رحمة، والخلاف عذاب."], "k": "«وما كان ربك ليهلك القرى بظلم وأهلها مصلحون»… مصلحون لا صالحون فقط؛ فهل أُصلح فيمن حولي؟"}, {"lbl": "الآيات ١٢٠ – ١٢٣", "q": "وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةٞ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿١٢٠﴾ وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ ﴿١٢١﴾ وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ﴿١٢٢﴾ وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿١٢٣﴾", "w": [["وكلاً نقص", "وكل ما تحتاج إليه من أنباء الرسل نقصّه عليك."], ["ما نثبت به فؤادك", "نقصّ عليك من القصص ما يثبّت قلبك لتصبر على دعوتنا وتبليغها."], ["وجاءك في هذه الحق", "في هذه السورة الحق الثابت من الله تعالى، كما جاءك في غيرها."], ["وموعظة وذكرى", "وجاءك فيها موعظة وذكرى للمؤمنين، إذ هم المنتفعون."], ["ولله غيب السماوات والأرض", "ما غاب علمه فيهما فالله يعلمه وحده، وليس لغيره فيه علم."], ["فاعبده", "وحّده في العبادة ولا تشرك به."], ["وتوكل عليه", "فوّض أمرك إليه وثق تمام الثقة فيه أن يكفيك."]], "m": "لما قصّ تعالى في هذه السورة أنباء الرسل مع أممهم، وما لاقوا من تكذيب وعناد، وكيف صبروا حتى جاءهم النصر، قال لرسوله ﷺ: وكل ما تحتاج إليه من أنباء الرسل نقصّه عليك لنثبّت به قلبك حتى تواصل دعوتك، وجاءك في هذه السورة الحق، وموعظة تعظ بها غيرك، وذكرى يتذكر بها المؤمنون فيثبتون على الحق ويصبرون على الطاعة والبلاء. وقل للذين لا يؤمنون من قومك: اعملوا على حالكم إنا عاملون على حالنا، وانتظروا إنا منتظرون أيّنا ينتصر في النهاية. ولله غيب السماوات والأرض، فهو وحده يعلم متى يجيء النصر، وإليه يرجع الأمر كله: الانتصار والانكسار، والهداية والإضلال، والإسعاد والإشقاء، فاعبده وحده وتوكّل عليه وحده فإنه كافيك كل ما يهمّك، وما ربك بغافل عما تعملون، وسيجزي كلاً بما عمل.", "h": ["بيان فائدة القصص القرآني، وهي أمور منها: تثبيت قلب النبي ﷺ، وإيجاد مواعظ وعبر للمؤمنين، وتقرير نبوة الرسول ﷺ.", "علم الغيب لله وحده، لا يعلمه غيره.", "مردّ الأمور كلها لله بدءاً وعوداً ونهاية."], "k": "«فاعبده وتوكل عليه»… خُتمت السورة بهما؛ عبادة تملأ يومي، وتوكل يريح قلبي."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (152, 12, 1, 10, 'سورة يوسف ١ – ١٠', '«نحن نقص عليك أحسن القصص»، ورؤيا يوسف ﵇', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 152) = $j$[{"lbl": "الآيات ١ – ٣", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿١﴾ إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ﴿٢﴾ نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَٰفِلِينَ ﴿٣﴾", "w": [["الر", "تُكتب «الر» وتُقرأ: ألف، لام، را، والله أعلم بمراده بذلك."], ["الكتاب المبين", "القرآن المظهر للحق في الاعتقادات والعبادات."], ["قرآناً عربياً", "بلغة العرب، العدنانيين والقحطانيين سواء."], ["نحن نقص", "نحدّثك متتبّعين آثار الحديث على وجهه الذي كان عليه."], ["بما أوحينا", "بإيحائنا إليك، فالوحي هو أداة القصص."], ["من قبله", "من قبل نزوله عليك."], ["لمن الغافلين", "كنت من قبل إيحائنا إليك غافلاً عنه، لا تذكره ولا تعلم منه شيئاً."]], "m": "المناسبة بين سورتي هود ويوسف أن الثانية تتميم للقصص الذي اشتملت عليه الأولى، وسورة يوسف اشتملت على أطول قصة في القرآن، أولها: «إذ قال يوسف لأبيه» وآخرها: «وما كنت لديهم إذ أجمعوا أمرهم»، وسبب نزولها أنه قيل للرسول ﷺ: لو قصصت علينا، فأنزل الله: «الر تلك آيات الكتاب المبين»، فقصّ أحداث أربعين سنة تقريباً. من هذه الحروف تألفت آيات القرآن، تلك آيات الكتاب المبين للحق ولكل ما يحتاجه الناس مما يصلح دينهم ودنياهم. إنا أنزلناه قرآناً بلسان العرب لعلكم تعقلون معانيه فتهتدوا فتكملوا وتسعدوا. نحن نقصّ عليك أحسن القصص، أصحّه وأصدقه وأنفعه وأجمله، بإيحائنا إليك هذا القرآن، وإن كنت من قبله لمن الغافلين عنه.", "h": ["تقرير إعجاز القرآن، إذ هو مؤلّف من مثل: الر، وطس، وق، ومع هذا لم يستطع العرب أن يأتوا بسورة مثله.", "بيان الحكمة في نزول القرآن باللغة العربية، وهي أن يعقله العرب ليبلّغوه إلى غيرهم.", "القرآن الكريم اشتمل على أحسن القصص، فلا معنى لسماع قصص غيره."], "k": "«نحن نقص عليك أحسن القصص»… أحسن القصص بين يديّ؛ فكم قصة منه أعرفها وأعتبر بها؟"}, {"lbl": "الآيات ٤ – ٦", "q": "إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ ﴿٤﴾ قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ﴿٥﴾ وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ ﴿٦﴾", "w": [["إني رأيت", "أي في منامي."], ["أحد عشر كوكباً", "من كواكب السماء."], ["ساجدين", "نزل الكل من السماء وسجدوا ليوسف وهو طفل."], ["فيكيدوا لك", "يحتالوا عليك بما يضرّك."], ["عدو مبين", "بيّن العداوة ظاهرها."], ["يجتبيك ربك", "يصطفيك له لتكون من عباده المخلَصين."], ["من تأويل الأحاديث", "تعبير الرؤيا."], ["ويتم نعمته عليك", "بأن ينبّئك ويرسلك رسولاً."]], "m": "هذا بداية القصص: اذكر إذ قال يوسف بن يعقوب لأبيه: يا أبت إني رأيت في منامي أحد عشر كوكباً والشمس والقمر رأيتهم لي ساجدين، نزلوا من السماء وسجدوا له تحية وتعظيماً، وسيظهر تأويلها بعد أربعين سنة حين يجمع الله شمله بأبويه وإخوته الأحد عشر ويسجد الكل له. قال يعقوب: يا بنيّ لا تقصص رؤياك على إخوتك، وهم إخوة له من أبيه دون أمه، فيحملهم الحسد على أن يكيدوك بما يضرّك، بطاعتهم للشيطان حين يغريهم بك، إن الشيطان للإنسان عدو مبين، إذ أخرج آدم وحواء من الجنة بتزيينه لهما الأكل من الشجرة. وكما أراك ربك هذه الرؤيا يصطفيك لتكون من عباده المخلَصين، ويعلّمك تعبير أحاديث الناس ورؤاهم، ويتم نعمته عليك بالنبوة وعلى آل يعقوب كما أتمها على أبويك من قبل: إبراهيم جدك الأعلى، وإسحاق جدك الأدنى، إن ربك عليم بخلقه، حكيم في تدبيره، فيكرم من هو أهل للإكرام ويحرم من هو أهل للحرمان.", "h": ["ثبوت الرؤيا شرعاً، ومشروعية تعبيرها.", "قد تتأخر الرؤيا فلا يظهر مصداقها إلا بعد السنين العديدة.", "مشروعية الحذر والأخذ بالحيطة في الأمور الهامة.", "بيان إفضال الله على آل إبراهيم بما أنعم عليهم، فجعلهم أنبياء آباءً وأبناءً وأحفاداً."], "k": "«لا تقصص رؤياك على إخوتك»… ليست كل نعمة تُحكى لكل أحد؛ فهل أحفظ نعمي من عين الحسد؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "۞لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ ﴿٧﴾ إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ ﴿٨﴾ ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ﴿٩﴾ قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ ﴿١٠﴾", "w": [["آيات للسائلين", "عبر للسائلين عن أخبارهم وما كان لهم من أحوال غريبة."], ["ونحن عصبة", "جماعة، إذ هم أحد عشر رجلاً."], ["أو اطرحوه أرضاً", "ألقوه في أرض بعيدة لا يُعثر عليه فيها."], ["في غيابة الجب", "في ظلمة البئر."], ["بعض السيارة", "المسافرين السائرين في الأرض."]], "m": "لقد كان في يوسف وإخوته عبر للمتطلعين إلى معرفة أخبارهم. إذ قال إخوة يوسف في خلوتهم: ليوسف وأخوه بنيامين، شقيقه دونهم، أحبّ إلى أبينا منا ونحن جماعة، فكيف يفضّل الاثنين على الجماعة؟ إن أبانا لفي خطأ بيّن. اقتلوا يوسف، أو ألقوه في أرض بعيدة فيهلك، يخلُ لكم وجه أبيكم، إذ كان مشغولاً بالنظر إلى يوسف، وتتوبوا بعد ذلك وتكونوا قوماً صالحين. قال قائل منهم، قيل: هو يهوذا أو روبيل، وكان أكبرهم سناً وأرجحهم عقلاً: لا تقتلوا يوسف، فالقتل جريمة لا ينبغي ارتكابها بحال، وألقوه في ظلمة البئر، وهي بئر معروفة في ديارهم بأرض فلسطين، يلتقطه بعض المسافرين، إن كنتم فاعلين شيئاً فهذا أفضل السبل.", "h": ["الميل إلى أحد الأبناء بالحب يورث العداوة بين الإخوة.", "الحسد سبب لكثير من الكوارث البشرية.", "ارتكاب أخف الضررين قاعدة شرعية عمل بها الأولون.", "الشفقة والمحبة في الشقيق أكبر منها في الأخ للأب."], "k": "«ليوسف وأخوه أحب إلى أبينا منا»… الحسد بدأ بكلمة؛ فهل أطفئ أول شرارته في قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 152;
insert into public.tdb_cards(topic, i, body) select 152, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿١﴾ إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ﴿٢﴾ نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَٰفِلِينَ ﴿٣﴾", "w": [["الر", "تُكتب «الر» وتُقرأ: ألف، لام، را، والله أعلم بمراده بذلك."], ["الكتاب المبين", "القرآن المظهر للحق في الاعتقادات والعبادات."], ["قرآناً عربياً", "بلغة العرب، العدنانيين والقحطانيين سواء."], ["نحن نقص", "نحدّثك متتبّعين آثار الحديث على وجهه الذي كان عليه."], ["بما أوحينا", "بإيحائنا إليك، فالوحي هو أداة القصص."], ["من قبله", "من قبل نزوله عليك."], ["لمن الغافلين", "كنت من قبل إيحائنا إليك غافلاً عنه، لا تذكره ولا تعلم منه شيئاً."]], "m": "المناسبة بين سورتي هود ويوسف أن الثانية تتميم للقصص الذي اشتملت عليه الأولى، وسورة يوسف اشتملت على أطول قصة في القرآن، أولها: «إذ قال يوسف لأبيه» وآخرها: «وما كنت لديهم إذ أجمعوا أمرهم»، وسبب نزولها أنه قيل للرسول ﷺ: لو قصصت علينا، فأنزل الله: «الر تلك آيات الكتاب المبين»، فقصّ أحداث أربعين سنة تقريباً. من هذه الحروف تألفت آيات القرآن، تلك آيات الكتاب المبين للحق ولكل ما يحتاجه الناس مما يصلح دينهم ودنياهم. إنا أنزلناه قرآناً بلسان العرب لعلكم تعقلون معانيه فتهتدوا فتكملوا وتسعدوا. نحن نقصّ عليك أحسن القصص، أصحّه وأصدقه وأنفعه وأجمله، بإيحائنا إليك هذا القرآن، وإن كنت من قبله لمن الغافلين عنه.", "h": ["تقرير إعجاز القرآن، إذ هو مؤلّف من مثل: الر، وطس، وق، ومع هذا لم يستطع العرب أن يأتوا بسورة مثله.", "بيان الحكمة في نزول القرآن باللغة العربية، وهي أن يعقله العرب ليبلّغوه إلى غيرهم.", "القرآن الكريم اشتمل على أحسن القصص، فلا معنى لسماع قصص غيره."], "k": "«نحن نقص عليك أحسن القصص»… أحسن القصص بين يديّ؛ فكم قصة منه أعرفها وأعتبر بها؟"}, {"lbl": "الآيات ٤ – ٦", "q": "إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ ﴿٤﴾ قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ﴿٥﴾ وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ ﴿٦﴾", "w": [["إني رأيت", "أي في منامي."], ["أحد عشر كوكباً", "من كواكب السماء."], ["ساجدين", "نزل الكل من السماء وسجدوا ليوسف وهو طفل."], ["فيكيدوا لك", "يحتالوا عليك بما يضرّك."], ["عدو مبين", "بيّن العداوة ظاهرها."], ["يجتبيك ربك", "يصطفيك له لتكون من عباده المخلَصين."], ["من تأويل الأحاديث", "تعبير الرؤيا."], ["ويتم نعمته عليك", "بأن ينبّئك ويرسلك رسولاً."]], "m": "هذا بداية القصص: اذكر إذ قال يوسف بن يعقوب لأبيه: يا أبت إني رأيت في منامي أحد عشر كوكباً والشمس والقمر رأيتهم لي ساجدين، نزلوا من السماء وسجدوا له تحية وتعظيماً، وسيظهر تأويلها بعد أربعين سنة حين يجمع الله شمله بأبويه وإخوته الأحد عشر ويسجد الكل له. قال يعقوب: يا بنيّ لا تقصص رؤياك على إخوتك، وهم إخوة له من أبيه دون أمه، فيحملهم الحسد على أن يكيدوك بما يضرّك، بطاعتهم للشيطان حين يغريهم بك، إن الشيطان للإنسان عدو مبين، إذ أخرج آدم وحواء من الجنة بتزيينه لهما الأكل من الشجرة. وكما أراك ربك هذه الرؤيا يصطفيك لتكون من عباده المخلَصين، ويعلّمك تعبير أحاديث الناس ورؤاهم، ويتم نعمته عليك بالنبوة وعلى آل يعقوب كما أتمها على أبويك من قبل: إبراهيم جدك الأعلى، وإسحاق جدك الأدنى، إن ربك عليم بخلقه، حكيم في تدبيره، فيكرم من هو أهل للإكرام ويحرم من هو أهل للحرمان.", "h": ["ثبوت الرؤيا شرعاً، ومشروعية تعبيرها.", "قد تتأخر الرؤيا فلا يظهر مصداقها إلا بعد السنين العديدة.", "مشروعية الحذر والأخذ بالحيطة في الأمور الهامة.", "بيان إفضال الله على آل إبراهيم بما أنعم عليهم، فجعلهم أنبياء آباءً وأبناءً وأحفاداً."], "k": "«لا تقصص رؤياك على إخوتك»… ليست كل نعمة تُحكى لكل أحد؛ فهل أحفظ نعمي من عين الحسد؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "۞لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ ﴿٧﴾ إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ ﴿٨﴾ ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ﴿٩﴾ قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ ﴿١٠﴾", "w": [["آيات للسائلين", "عبر للسائلين عن أخبارهم وما كان لهم من أحوال غريبة."], ["ونحن عصبة", "جماعة، إذ هم أحد عشر رجلاً."], ["أو اطرحوه أرضاً", "ألقوه في أرض بعيدة لا يُعثر عليه فيها."], ["في غيابة الجب", "في ظلمة البئر."], ["بعض السيارة", "المسافرين السائرين في الأرض."]], "m": "لقد كان في يوسف وإخوته عبر للمتطلعين إلى معرفة أخبارهم. إذ قال إخوة يوسف في خلوتهم: ليوسف وأخوه بنيامين، شقيقه دونهم، أحبّ إلى أبينا منا ونحن جماعة، فكيف يفضّل الاثنين على الجماعة؟ إن أبانا لفي خطأ بيّن. اقتلوا يوسف، أو ألقوه في أرض بعيدة فيهلك، يخلُ لكم وجه أبيكم، إذ كان مشغولاً بالنظر إلى يوسف، وتتوبوا بعد ذلك وتكونوا قوماً صالحين. قال قائل منهم، قيل: هو يهوذا أو روبيل، وكان أكبرهم سناً وأرجحهم عقلاً: لا تقتلوا يوسف، فالقتل جريمة لا ينبغي ارتكابها بحال، وألقوه في ظلمة البئر، وهي بئر معروفة في ديارهم بأرض فلسطين، يلتقطه بعض المسافرين، إن كنتم فاعلين شيئاً فهذا أفضل السبل.", "h": ["الميل إلى أحد الأبناء بالحب يورث العداوة بين الإخوة.", "الحسد سبب لكثير من الكوارث البشرية.", "ارتكاب أخف الضررين قاعدة شرعية عمل بها الأولون.", "الشفقة والمحبة في الشقيق أكبر منها في الأخ للأب."], "k": "«ليوسف وأخوه أحب إلى أبينا منا»… الحسد بدأ بكلمة؛ فهل أطفئ أول شرارته في قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (153, 12, 11, 22, 'سورة يوسف ١١ – ٢٢', 'إخوة يوسف والجبّ: «فصبر جميل والله المستعان»، ومن الجبّ إلى بيت العزيز', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 153) = $j$[{"lbl": "الآيات ١١ – ١٤", "q": "قَالُواْ يَـٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ ﴿١١﴾ أَرۡسِلۡهُ مَعَنَا غَدٗا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿١٢﴾ قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ ﴿١٣﴾ قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ ﴿١٤﴾", "w": [["لناصحون", "لمشفقون عليه، نحب له الخير كما نحبه لأنفسنا."], ["يرتع ويلعب", "يأكل ويشرب ويلعب بالمسابقة والمناضلة."], ["إني ليحزنني", "يوقعني في الحزن، الذي هو ألم النفس، ذهابكم به."], ["الذئب", "حيوان مفترس خدّاع شرس."], ["ونحن عصبة", "جماعة قوية."], ["لخاسرون", "ضعفاء عاجزون عرضة للخسران بفقدنا أخانا."]], "m": "بعد أن قرّروا إلقاءه في غيابة الجب، طلبوا من أبيهم أن يترك يوسف يخرج معهم إلى البر للنزهة، وكأنهم لاحظوا عدم ثقته فيهم، فقالوا: ما لك لا تأمنّا على يوسف وإنا له لناصحون، محبون له كل خير مشفقون عليه؟ أرسله معنا غداً يرتع في البادية فيأكل ويشرب، ويلعب بالسباق والمناضلة، وإنا له لحافظون من كل ما يضرّه. قال: إني ليحزنني أن تذهبوا به، وأخاف أن يأكله الذئب وأنتم عنه غافلون في رتعكم ولعبكم. قالوا: لئن أكله الذئب ونحن جماعة قوية إنا إذاً لخاسرون، لا خير في وجودنا. ومع الأسف أقنعوا بهذا الحديث والدهم، وغداً سيذهبون بيوسف لتنفيذ مؤامرتهم.", "h": ["تقرير قاعدة: لا حذر مع القدر، أي لا حذر ينفع في ردّ المقدور.", "صدق المؤمن يحمله على تصديق من يحلف له ويؤكد كلامه.", "جواز الحزن وأنه لا إثم فيه، وفي الحديث: «وإنا بفراقك يا إبراهيم لمحزونون».", "أكل الذئب للإنسان إن أصاب منه غفلة واقع وكثير أيضاً."], "k": "«وإنا له لناصحون»… قالوها وهم يُضمرون الكيد؛ فهل يوافق كلامي ما في قلبي؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ ﴿١٥﴾ وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ ﴿١٦﴾ قَالُواْ يَـٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ ﴿١٧﴾ وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ﴿١٨﴾", "w": [["وأجمعوا", "أجمعوا أمرهم على إلقائه في غيابة الجب."], ["في غيابة الجب", "في ظلمة البئر."], ["وأوحينا إليه", "أعلمناه بطريق خفي سريع."], ["عشاءً", "بعد غروب الشمس أول الليل."], ["نستبق", "بالمناضلة."], ["عند متاعنا", "أمتعتنا من ثياب وغيرها."], ["وما أنت بمؤمن لنا", "بمصدّق لنا."], ["بدم كذب", "بدم مكذوب، دم سخلة وليس دم يوسف."], ["بل سولت لكم", "زيّنت وحسّنت."], ["على ما تصفون", "من الكذب."]], "m": "أخذوه معهم إلى البر، وما إن بعدوا به حتى تغيّرت وجوههم عليه، وصار يتلقّى الكلمات النابية والضرب، وقد أجمعوا أمرهم على إلقائه في بئر معلومة لهم، فألقوه وهو يبكي بأعلى صوته، وقد انتزعوا منه قميصه وتركوه في قعر البئر. وهنا أوحى الله إليه: لتنبئنّهم بأمرهم هذا وهم لا يشعرون. ثم ذبحوا سخلة ولطّخوا بدمها قميصه، وجاؤوا أباهم عشاءً يبكون، قالوا: يا أبانا إنا ذهبنا نستبق وتركنا يوسف عند متاعنا فأكله الذئب، وما أنت بمصدّق لنا ولو كنا صادقين، وقد دلّت عباراتهم على كذبهم. ونظر يعقوب إلى القميص ملطّخاً بالدم ولم يكن به خرق ولا تمزيق فقال: إن هذا الذئب لحليم، أكل يوسف ولم يخرق ثوبه! بل زيّنت لكم أنفسكم أمراً فنفّذتموه، فأمري صبر جميل، لا جزع فيه ولا شكوى معه، والله المستعان على ما تصفون من الكذب.", "h": ["جواز صدور الذنب الكبير من الرجل المؤمن المهيّأ للكمال مستقبلاً.", "لطف الله تعالى بيوسف وإكرامه له بإعلامه إياه أنه سينبئ إخوته بفعلتهم هذه، وضمن ذلك بشّره بسلامة الحال وحسن المآل.", "اختيار الليل للاعتذار دون النهار، لأن العين تستحيي من العين كما يقال.", "فضيلة الصبر الجميل، وهو الخالي من الجزع والشكوى معاً."], "k": "«فصبر جميل والله المستعان»… صبر بلا شكوى للناس، واستعانة بالله وحده؛ فهل أصبر هكذا؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ ﴿١٩﴾ وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّـٰهِدِينَ ﴿٢٠﴾ وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢١﴾ وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٢٢﴾", "w": [["سيارة", "رفقة من الناس تسير مع بعضها بعضاً."], ["واردهم", "الذي يرد لهم الماء."], ["فأدلى دلوه", "دلّى دلوه في البئر."], ["وأسروه بضاعة", "أخفوه كبضاعة من البضائع."], ["وشروه بثمن بخس", "باعوه بثمن ناقص."], ["وقال الذي اشتراه", "الرجل الذي اشتراه، واسمه قطفير، ولقبه العزيز."], ["أكرمي مثواه", "أكرمي موضع إقامته، بمعنى: أكرميه وأحسني إليه."], ["أو نتخذه ولداً", "نتبنّاه، قال ذلك لأنه لم يكن يولد له."], ["ولما بلغ أشده", "قوته البدنية والعقلية."], ["حكماً وعلماً", "حكمة في التدبير ومعرفة في الدين."]], "m": "لما أُلقي يوسف في الجب جاءت قافلة من بلاد مدين تريد مصر، فأرسلوا من يستقي لهم الماء، فأدلى دلوه فتعلّق به يوسف فخرج معه، فصاح: يا بشراي هذا غلام! وكان إخوة يوسف يتردّدون على البئر، فلما رأوه قالوا: هذا عبد لنا أبَق، فباعوه لهم بثمن ناقص، دراهم معدودة غير موزونة دلالة على قلّتها، وكانوا فيه من الزاهدين، وأخفاه المشترون عن رجال القافلة كبضاعة. ولما وصلوا مصر باعوه من وزير يقال له قطفير العزيز، فتفرّس فيه الخير فقال لامرأته: أكرمي مقامه، عسى أن ينفعنا أو نتخذه ولداً. وكما نجّيناه من القتل والجب وعطفنا عليه العزيز مكّنا له في الأرض فيما بعد فصار ملك مصر يسوسها بالعدل، ولنعلّمه تعبير الرؤى، والله غالب على أمره فلم يقدر إخوته أن يبلغوا منه مرادهم، ولكن أكثر الناس لا يعلمون. وفي هذا تسلية لرسول الله ﷺ على ما يجد من أذى أقربائه. ولما بلغ يوسف اكتمال قوته البدنية والعقلية آتيناه حكمة وعلماً، وكذلك نجزي المحسنين، وفي هذا بشارة لرسول الله ﷺ بحسن العاقبة.", "h": ["جواز الفرح بما يسرّ والإعلان عنه.", "جواز الاحتياط لأمر الدين والدنيا.", "إطلاق لفظ الشراء على البيع.", "نسخ التبنّي في الإسلام.", "بلوغ الأشُدّ يبتدئ بانتهاء الصبا والدخول في البلوغ.", "حسن الجزاء مشروط بحسن القصد والعمل."], "k": "«والله غالب على أمره»… أرادوا إذلاله فصار عزيز مصر؛ فهل أثق بتدبير الله فيما يؤلمني الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 153;
insert into public.tdb_cards(topic, i, body) select 153, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٤", "q": "قَالُواْ يَـٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ ﴿١١﴾ أَرۡسِلۡهُ مَعَنَا غَدٗا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿١٢﴾ قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ ﴿١٣﴾ قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ ﴿١٤﴾", "w": [["لناصحون", "لمشفقون عليه، نحب له الخير كما نحبه لأنفسنا."], ["يرتع ويلعب", "يأكل ويشرب ويلعب بالمسابقة والمناضلة."], ["إني ليحزنني", "يوقعني في الحزن، الذي هو ألم النفس، ذهابكم به."], ["الذئب", "حيوان مفترس خدّاع شرس."], ["ونحن عصبة", "جماعة قوية."], ["لخاسرون", "ضعفاء عاجزون عرضة للخسران بفقدنا أخانا."]], "m": "بعد أن قرّروا إلقاءه في غيابة الجب، طلبوا من أبيهم أن يترك يوسف يخرج معهم إلى البر للنزهة، وكأنهم لاحظوا عدم ثقته فيهم، فقالوا: ما لك لا تأمنّا على يوسف وإنا له لناصحون، محبون له كل خير مشفقون عليه؟ أرسله معنا غداً يرتع في البادية فيأكل ويشرب، ويلعب بالسباق والمناضلة، وإنا له لحافظون من كل ما يضرّه. قال: إني ليحزنني أن تذهبوا به، وأخاف أن يأكله الذئب وأنتم عنه غافلون في رتعكم ولعبكم. قالوا: لئن أكله الذئب ونحن جماعة قوية إنا إذاً لخاسرون، لا خير في وجودنا. ومع الأسف أقنعوا بهذا الحديث والدهم، وغداً سيذهبون بيوسف لتنفيذ مؤامرتهم.", "h": ["تقرير قاعدة: لا حذر مع القدر، أي لا حذر ينفع في ردّ المقدور.", "صدق المؤمن يحمله على تصديق من يحلف له ويؤكد كلامه.", "جواز الحزن وأنه لا إثم فيه، وفي الحديث: «وإنا بفراقك يا إبراهيم لمحزونون».", "أكل الذئب للإنسان إن أصاب منه غفلة واقع وكثير أيضاً."], "k": "«وإنا له لناصحون»… قالوها وهم يُضمرون الكيد؛ فهل يوافق كلامي ما في قلبي؟"}, {"lbl": "الآيات ١٥ – ١٨", "q": "فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ ﴿١٥﴾ وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ ﴿١٦﴾ قَالُواْ يَـٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ ﴿١٧﴾ وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ﴿١٨﴾", "w": [["وأجمعوا", "أجمعوا أمرهم على إلقائه في غيابة الجب."], ["في غيابة الجب", "في ظلمة البئر."], ["وأوحينا إليه", "أعلمناه بطريق خفي سريع."], ["عشاءً", "بعد غروب الشمس أول الليل."], ["نستبق", "بالمناضلة."], ["عند متاعنا", "أمتعتنا من ثياب وغيرها."], ["وما أنت بمؤمن لنا", "بمصدّق لنا."], ["بدم كذب", "بدم مكذوب، دم سخلة وليس دم يوسف."], ["بل سولت لكم", "زيّنت وحسّنت."], ["على ما تصفون", "من الكذب."]], "m": "أخذوه معهم إلى البر، وما إن بعدوا به حتى تغيّرت وجوههم عليه، وصار يتلقّى الكلمات النابية والضرب، وقد أجمعوا أمرهم على إلقائه في بئر معلومة لهم، فألقوه وهو يبكي بأعلى صوته، وقد انتزعوا منه قميصه وتركوه في قعر البئر. وهنا أوحى الله إليه: لتنبئنّهم بأمرهم هذا وهم لا يشعرون. ثم ذبحوا سخلة ولطّخوا بدمها قميصه، وجاؤوا أباهم عشاءً يبكون، قالوا: يا أبانا إنا ذهبنا نستبق وتركنا يوسف عند متاعنا فأكله الذئب، وما أنت بمصدّق لنا ولو كنا صادقين، وقد دلّت عباراتهم على كذبهم. ونظر يعقوب إلى القميص ملطّخاً بالدم ولم يكن به خرق ولا تمزيق فقال: إن هذا الذئب لحليم، أكل يوسف ولم يخرق ثوبه! بل زيّنت لكم أنفسكم أمراً فنفّذتموه، فأمري صبر جميل، لا جزع فيه ولا شكوى معه، والله المستعان على ما تصفون من الكذب.", "h": ["جواز صدور الذنب الكبير من الرجل المؤمن المهيّأ للكمال مستقبلاً.", "لطف الله تعالى بيوسف وإكرامه له بإعلامه إياه أنه سينبئ إخوته بفعلتهم هذه، وضمن ذلك بشّره بسلامة الحال وحسن المآل.", "اختيار الليل للاعتذار دون النهار، لأن العين تستحيي من العين كما يقال.", "فضيلة الصبر الجميل، وهو الخالي من الجزع والشكوى معاً."], "k": "«فصبر جميل والله المستعان»… صبر بلا شكوى للناس، واستعانة بالله وحده؛ فهل أصبر هكذا؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ ﴿١٩﴾ وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّـٰهِدِينَ ﴿٢٠﴾ وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢١﴾ وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٢٢﴾", "w": [["سيارة", "رفقة من الناس تسير مع بعضها بعضاً."], ["واردهم", "الذي يرد لهم الماء."], ["فأدلى دلوه", "دلّى دلوه في البئر."], ["وأسروه بضاعة", "أخفوه كبضاعة من البضائع."], ["وشروه بثمن بخس", "باعوه بثمن ناقص."], ["وقال الذي اشتراه", "الرجل الذي اشتراه، واسمه قطفير، ولقبه العزيز."], ["أكرمي مثواه", "أكرمي موضع إقامته، بمعنى: أكرميه وأحسني إليه."], ["أو نتخذه ولداً", "نتبنّاه، قال ذلك لأنه لم يكن يولد له."], ["ولما بلغ أشده", "قوته البدنية والعقلية."], ["حكماً وعلماً", "حكمة في التدبير ومعرفة في الدين."]], "m": "لما أُلقي يوسف في الجب جاءت قافلة من بلاد مدين تريد مصر، فأرسلوا من يستقي لهم الماء، فأدلى دلوه فتعلّق به يوسف فخرج معه، فصاح: يا بشراي هذا غلام! وكان إخوة يوسف يتردّدون على البئر، فلما رأوه قالوا: هذا عبد لنا أبَق، فباعوه لهم بثمن ناقص، دراهم معدودة غير موزونة دلالة على قلّتها، وكانوا فيه من الزاهدين، وأخفاه المشترون عن رجال القافلة كبضاعة. ولما وصلوا مصر باعوه من وزير يقال له قطفير العزيز، فتفرّس فيه الخير فقال لامرأته: أكرمي مقامه، عسى أن ينفعنا أو نتخذه ولداً. وكما نجّيناه من القتل والجب وعطفنا عليه العزيز مكّنا له في الأرض فيما بعد فصار ملك مصر يسوسها بالعدل، ولنعلّمه تعبير الرؤى، والله غالب على أمره فلم يقدر إخوته أن يبلغوا منه مرادهم، ولكن أكثر الناس لا يعلمون. وفي هذا تسلية لرسول الله ﷺ على ما يجد من أذى أقربائه. ولما بلغ يوسف اكتمال قوته البدنية والعقلية آتيناه حكمة وعلماً، وكذلك نجزي المحسنين، وفي هذا بشارة لرسول الله ﷺ بحسن العاقبة.", "h": ["جواز الفرح بما يسرّ والإعلان عنه.", "جواز الاحتياط لأمر الدين والدنيا.", "إطلاق لفظ الشراء على البيع.", "نسخ التبنّي في الإسلام.", "بلوغ الأشُدّ يبتدئ بانتهاء الصبا والدخول في البلوغ.", "حسن الجزاء مشروط بحسن القصد والعمل."], "k": "«والله غالب على أمره»… أرادوا إذلاله فصار عزيز مصر؛ فهل أثق بتدبير الله فيما يؤلمني الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (154, 12, 23, 34, 'سورة يوسف ٢٣ – ٣٤', '«معاذ الله إنه ربي أحسن مثواي»، و«رب السجن أحب إليّ مما يدعونني إليه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 154) = $j$[{"lbl": "الآيات ٢٣ – ٢٩", "q": "وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٢٣﴾ وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ﴿٢٤﴾ وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ ﴿٢٥﴾ قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ ﴿٢٦﴾ وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٧﴾ فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ ﴿٢٨﴾ يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ ﴿٢٩﴾", "w": [["وراودته", "طالبته لحاجتها، تريد أن ينزل عن إرادته لإرادتها وهو يأبى."], ["التي هو في بيتها", "زليخا امرأة العزيز."], ["وغلّقت الأبواب", "أغلقتها بالمغاليق."], ["هيت لك", "تعالَ عندي."], ["معاذ الله", "أعوذ بالله، أي أتحصّن وأحتمي به من فعل ما لا يجوز."], ["أحسن مثواي", "أحسن إقامتي في بيته."], ["همّت به", "لتبطش به ضرباً."], ["وهمّ بها", "ليدفع صولتها عليه."], ["برهان ربه", "ألهمه ربه أن الخير في عدم ضربها."], ["المخلَصين", "الذين استخلصناهم لولايتنا وطاعتنا ومحبتنا."], ["وقدّت قميصه", "قطعته من وراء."], ["وألفيا سيدها", "وجدا العزيز زوجها، وكانوا يطلقون على الزوج لفظ السيد."], ["وشهد شاهد من أهلها", "ابن عمها."], ["قُدّ من قُبُل", "من قدّام."], ["يوسف أعرض عن هذا", "عن هذا الأمر ولا تذكره لكيلا يشيع."], ["من الخاطئين", "المرتكبين للخطايا الآثمين."]], "m": "أوصى العزيز امرأته بإكرام يوسف، ونظراً إلى ما تجلبه الخلوة بين الرجل والمرأة من إثارة الغريزة، لا سيما إذا طالت المدة وأمن الخوف وقلّت التقوى، راودته عن نفسه بعد أن غلّقت الأبواب وقالت: تعال إليّ. فكان ردّ يوسف حازماً قاطعاً للطمع، وهذا هو المطلوب في مثل هذا الموقف: معاذ الله، إن العزيز سيدي أحسن إقامتي فكيف أخونه في أهله؟ وفي الوقت نفسه سيده الحق الله جل جلاله أحسن مثواه فكيف يخونه، إنه لا يفلح الظالمون. ولقد همّت بضربه لامتناعه بعد مراودات طالت، وهمّ بضربها دفعاً لها عن نفسه، لولا أن أراه الله برهاناً في نفسه فلم يضربها وآثر الفرار، كذلك لنصرف عنه السوء فلا يفعله، والفحشاء فلا يقربها، إنه من عبادنا المخلَصين. واستبقا الباب: هو يريد الخروج، وهي تريد ردّه خشية الفضيحة، فشقّت قميصه من وراء، ووجدا زوجها عند الباب، فبادرت بالاعتذار: ما جزاء من أراد بأهلك سوءاً إلا أن يُسجن أو يُعذّب عذاباً أليماً. قال يوسف: هي راودتني عن نفسي، وشهد شاهد من أهلها: إن كان قميصه قُدّ من قُبُل فصدقت وهو من الكاذبين، وإن كان قُدّ من دُبُر فكذبت وهو من الصادقين. فلما رأى قميصه قُدّ من دبر قال: إنه من كيدكن، إن كيدكن عظيم، يا يوسف أعرض عن هذا ولا تذكره لأحد، وقال لزليخا: استغفري لذنبك، إنك كنت من الخاطئين.", "h": ["مشروعية الدفاع عن النفس ولو بما يُسيء إلى الخصم.", "إكرام الله تعالى لأوليائه، حيث أنطق طفلاً في المهد فحكم ببراءة يوسف.", "تقرير أن كيد النساء عظيم، وهو كذلك.", "استحباب الستر على المسيء، وكراهية إشاعة الذنوب بين الناس."], "k": "«معاذ الله»… في لحظة الخلوة والإغراء، هل أجد في قلبي هذه الكلمة حاضرة؟"}, {"lbl": "الآيات ٣٠ – ٣٤", "q": "۞وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ ﴿٣٠﴾ فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ ﴿٣١﴾ قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّـٰغِرِينَ ﴿٣٢﴾ قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ ﴿٣٣﴾ فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٤﴾", "w": [["في المدينة", "عاصمة مصر يومئذ."], ["تراود فتاها", "عبدها الكنعاني."], ["قد شغفها حباً", "دخل حبّه شغاف قلبها، أي أحاط بقلبها فتملّكه."], ["إنا لنراها في ضلال مبين", "في خطأ بيّن بسبب حبها إياه."], ["فلما سمعت بمكرهن", "بما تحدّثن به عنها في غيبتها."], ["وأعتدت لهن متكأً", "أعدّت لهن فراشاً ووسائد للاتكاء عليها."], ["أكبرنه", "أعظمنه في نفوسهن."], ["فذلكن الذي لمتنني فيه", "قلتنّ: كيف تحب عبداً كنعانياً؟"], ["فاستعصم", "امتنع مستمسكاً بعفّته وطهارته."], ["الصاغرين", "الذليلين المهانين."], ["أصبُ إليهن", "أمِلْ إليهن."], ["وأكن من الجاهلين", "المذنبين، إذ لا يذنب إلا من جهل قدرة الله واطلاعه عليه."]], "m": "انتقل الخبر إلى نساء بعض الوزراء فتحدّثن لوماً لامرأة العزيز: تراود عبدها عن نفسه، قد بلغ حبها إياه شغاف قلبها، إنا لنراها في خطأ واضح، كيف تحب عبداً وهي في شرفها وعلوّ مكانتها؟ فلما سمعت بما تحدّثن به في غيبتها قابلت مكرهن بمكر أعظم، فأعدّت لهن حفلة طعام، وأعطت كل واحدة سكيناً تقطع بها الفاكهة، ثم أمرته أن يخرج عليهن، فلما رأينه أعظمنه، وذُهلن عن أنفسهن فقطعن أيديهن بدل الفاكهة، وقلن: حاش لله ما هذا بشراً، إن هذا إلا ملك كريم، لجماله وحسن خَلقه وخُلقه. قالت: فذلكنّ الذي لمتنّني في حبه، ولقد راودته عن نفسه فاستعصم، ولئن لم يفعل ما آمره ليُسجننّ وليكونن من الصاغرين، فأسمعته تهديدها أمام النسوة. ففزع يوسف إلى ربه: رب السجن أحب إليّ مما يدعونني إليه من الإثم، وإلا تصرف عني كيدهن أمِل إليهن وأكن من الآثمين. فاستجاب له ربه فصرف عنه كيدهن، إنه هو السميع لأقوال عباده، العليم بأحوالهم.", "h": ["بيان طبيعة الإنسان في حب الاطلاع وتتبّع الأخبار.", "رغبة الإنسان في الثأر لكرامته وما يحميه من دم أو مال أو عرض.", "ضعف النساء أمام الرجال، وعدم قدرتهن على التحمّل كالرجال.", "إيثار يوسف ﵇ السجن على معصية الله تعالى، وهذه مظاهر الصدّيقية.", "الجهل بالله تعالى وبأسمائه وصفاته ووعده ووعيده وشرعه هو سبب كل الجرائم."], "k": "«رب السجن أحب إليّ»… ضيق مع الطاعة خير من سعة مع المعصية؛ فهل أختار كما اختار يوسف؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 154;
insert into public.tdb_cards(topic, i, body) select 154, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٣ – ٢٩", "q": "وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٢٣﴾ وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ﴿٢٤﴾ وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ ﴿٢٥﴾ قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ ﴿٢٦﴾ وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٧﴾ فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ ﴿٢٨﴾ يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ ﴿٢٩﴾", "w": [["وراودته", "طالبته لحاجتها، تريد أن ينزل عن إرادته لإرادتها وهو يأبى."], ["التي هو في بيتها", "زليخا امرأة العزيز."], ["وغلّقت الأبواب", "أغلقتها بالمغاليق."], ["هيت لك", "تعالَ عندي."], ["معاذ الله", "أعوذ بالله، أي أتحصّن وأحتمي به من فعل ما لا يجوز."], ["أحسن مثواي", "أحسن إقامتي في بيته."], ["همّت به", "لتبطش به ضرباً."], ["وهمّ بها", "ليدفع صولتها عليه."], ["برهان ربه", "ألهمه ربه أن الخير في عدم ضربها."], ["المخلَصين", "الذين استخلصناهم لولايتنا وطاعتنا ومحبتنا."], ["وقدّت قميصه", "قطعته من وراء."], ["وألفيا سيدها", "وجدا العزيز زوجها، وكانوا يطلقون على الزوج لفظ السيد."], ["وشهد شاهد من أهلها", "ابن عمها."], ["قُدّ من قُبُل", "من قدّام."], ["يوسف أعرض عن هذا", "عن هذا الأمر ولا تذكره لكيلا يشيع."], ["من الخاطئين", "المرتكبين للخطايا الآثمين."]], "m": "أوصى العزيز امرأته بإكرام يوسف، ونظراً إلى ما تجلبه الخلوة بين الرجل والمرأة من إثارة الغريزة، لا سيما إذا طالت المدة وأمن الخوف وقلّت التقوى، راودته عن نفسه بعد أن غلّقت الأبواب وقالت: تعال إليّ. فكان ردّ يوسف حازماً قاطعاً للطمع، وهذا هو المطلوب في مثل هذا الموقف: معاذ الله، إن العزيز سيدي أحسن إقامتي فكيف أخونه في أهله؟ وفي الوقت نفسه سيده الحق الله جل جلاله أحسن مثواه فكيف يخونه، إنه لا يفلح الظالمون. ولقد همّت بضربه لامتناعه بعد مراودات طالت، وهمّ بضربها دفعاً لها عن نفسه، لولا أن أراه الله برهاناً في نفسه فلم يضربها وآثر الفرار، كذلك لنصرف عنه السوء فلا يفعله، والفحشاء فلا يقربها، إنه من عبادنا المخلَصين. واستبقا الباب: هو يريد الخروج، وهي تريد ردّه خشية الفضيحة، فشقّت قميصه من وراء، ووجدا زوجها عند الباب، فبادرت بالاعتذار: ما جزاء من أراد بأهلك سوءاً إلا أن يُسجن أو يُعذّب عذاباً أليماً. قال يوسف: هي راودتني عن نفسي، وشهد شاهد من أهلها: إن كان قميصه قُدّ من قُبُل فصدقت وهو من الكاذبين، وإن كان قُدّ من دُبُر فكذبت وهو من الصادقين. فلما رأى قميصه قُدّ من دبر قال: إنه من كيدكن، إن كيدكن عظيم، يا يوسف أعرض عن هذا ولا تذكره لأحد، وقال لزليخا: استغفري لذنبك، إنك كنت من الخاطئين.", "h": ["مشروعية الدفاع عن النفس ولو بما يُسيء إلى الخصم.", "إكرام الله تعالى لأوليائه، حيث أنطق طفلاً في المهد فحكم ببراءة يوسف.", "تقرير أن كيد النساء عظيم، وهو كذلك.", "استحباب الستر على المسيء، وكراهية إشاعة الذنوب بين الناس."], "k": "«معاذ الله»… في لحظة الخلوة والإغراء، هل أجد في قلبي هذه الكلمة حاضرة؟"}, {"lbl": "الآيات ٣٠ – ٣٤", "q": "۞وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ ﴿٣٠﴾ فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ ﴿٣١﴾ قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّـٰغِرِينَ ﴿٣٢﴾ قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ ﴿٣٣﴾ فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٤﴾", "w": [["في المدينة", "عاصمة مصر يومئذ."], ["تراود فتاها", "عبدها الكنعاني."], ["قد شغفها حباً", "دخل حبّه شغاف قلبها، أي أحاط بقلبها فتملّكه."], ["إنا لنراها في ضلال مبين", "في خطأ بيّن بسبب حبها إياه."], ["فلما سمعت بمكرهن", "بما تحدّثن به عنها في غيبتها."], ["وأعتدت لهن متكأً", "أعدّت لهن فراشاً ووسائد للاتكاء عليها."], ["أكبرنه", "أعظمنه في نفوسهن."], ["فذلكن الذي لمتنني فيه", "قلتنّ: كيف تحب عبداً كنعانياً؟"], ["فاستعصم", "امتنع مستمسكاً بعفّته وطهارته."], ["الصاغرين", "الذليلين المهانين."], ["أصبُ إليهن", "أمِلْ إليهن."], ["وأكن من الجاهلين", "المذنبين، إذ لا يذنب إلا من جهل قدرة الله واطلاعه عليه."]], "m": "انتقل الخبر إلى نساء بعض الوزراء فتحدّثن لوماً لامرأة العزيز: تراود عبدها عن نفسه، قد بلغ حبها إياه شغاف قلبها، إنا لنراها في خطأ واضح، كيف تحب عبداً وهي في شرفها وعلوّ مكانتها؟ فلما سمعت بما تحدّثن به في غيبتها قابلت مكرهن بمكر أعظم، فأعدّت لهن حفلة طعام، وأعطت كل واحدة سكيناً تقطع بها الفاكهة، ثم أمرته أن يخرج عليهن، فلما رأينه أعظمنه، وذُهلن عن أنفسهن فقطعن أيديهن بدل الفاكهة، وقلن: حاش لله ما هذا بشراً، إن هذا إلا ملك كريم، لجماله وحسن خَلقه وخُلقه. قالت: فذلكنّ الذي لمتنّني في حبه، ولقد راودته عن نفسه فاستعصم، ولئن لم يفعل ما آمره ليُسجننّ وليكونن من الصاغرين، فأسمعته تهديدها أمام النسوة. ففزع يوسف إلى ربه: رب السجن أحب إليّ مما يدعونني إليه من الإثم، وإلا تصرف عني كيدهن أمِل إليهن وأكن من الآثمين. فاستجاب له ربه فصرف عنه كيدهن، إنه هو السميع لأقوال عباده، العليم بأحوالهم.", "h": ["بيان طبيعة الإنسان في حب الاطلاع وتتبّع الأخبار.", "رغبة الإنسان في الثأر لكرامته وما يحميه من دم أو مال أو عرض.", "ضعف النساء أمام الرجال، وعدم قدرتهن على التحمّل كالرجال.", "إيثار يوسف ﵇ السجن على معصية الله تعالى، وهذه مظاهر الصدّيقية.", "الجهل بالله تعالى وبأسمائه وصفاته ووعده ووعيده وشرعه هو سبب كل الجرائم."], "k": "«رب السجن أحب إليّ»… ضيق مع الطاعة خير من سعة مع المعصية؛ فهل أختار كما اختار يوسف؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (155, 12, 35, 42, 'سورة يوسف ٣٥ – ٤٢', 'يوسف ﵇ في السجن: «أأرباب متفرقون خير أم الله الواحد القهار»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 155) = $j$[{"lbl": "الآيات ٣٥ – ٣٨", "q": "ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ ﴿٣٥﴾ وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٣٦﴾ قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ﴿٣٧﴾ وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٣٨﴾", "w": [["ثم بدا لهم", "ظهر لهم."], ["الآيات", "الدلائل على براءة يوسف."], ["أعصر خمراً", "أعصر عنباً ليكون خمراً."], ["واتبعت ملة", "دين."], ["ما كان لنا", "ما انبغى لنا ولا صحّ منا."], ["أن نشرك بالله من شيء", "أن نشرك بالله شيئاً من الشرك وإن قلّ، ولا من الشركاء وإن عظموا أو حقروا."], ["ذلك من فضل الله علينا", "ذلك التوحيد والدين الحق."], ["وعلى الناس", "إذ جاءتهم الرسل به، ولكنهم ما شكروا فلم يتبعوا."]], "m": "ثم ظهر للعزيز ومن معه، من بعد ما رأوا الدلائل الواضحة على براءة يوسف، كقدّ القميص من دبر وحكم الشاهد، أن يسجنوه إلى حين، ريثما تسكن النفوس وتُنسى الحادثة. ودخل معه السجن فتيان كانا يخدمان ملك البلاد بتهمة وُجّهت إليهما، فلما أعجبا بسلوكه وحسن معاملته وعرفا أنه يعبّر الرؤيا، قال أحدهما: إني أراني أعصر خمراً، وقال الآخر: إني أراني أحمل فوق رأسي خبزاً تأكل الطير منه، نبّئنا بتأويله إنا نراك من المحسنين. قال: لا يأتيكما طعام تُرزقانه إلا نبّأتكما بتأويله قبل أن يأتيكما، ذلكما مما علّمني ربي، إني تركت ملة قوم لا يؤمنون بالله وهم بالآخرة كافرون، وهم الكنعانيون والمصريون، إذ كانوا مشركين يعبدون الشمس وغيرها، واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب، ما كان لنا أن نشرك بالله من شيء، ذلك من فضل الله علينا وعلى الناس، إذ خلقهم ورزقهم ودعاهم إلى الهدى، ولكن أكثر الناس لا يشكرون فلا يؤمنون ولا يعبدون.", "h": ["دخول يوسف السجن بداية أحداث ظاهرها محرق وباطنها مشرق.", "دخول السجن ليس دائماً دليلاً على أنه بيت المجرمين والمنحرفين، إذ دخله صفيّ الله يوسف ﵇.", "تعبير الرؤى تابع لصفاء الروح وقوة الفراسة، وهي في يوسف علم لدنّي خاص.", "استغلال المناسبات للدعوة إلى الله تعالى كما استغلها يوسف ﵇.", "وجوب البراءة من الشرك وأهله.", "إطلاق لفظ الآباء على الجدود، إذ كل واحد هو أب لمن بعده."], "k": "«ذلك من فضل الله علينا»… التوحيد الذي في قلبي نعمة لا جهد مني؛ فهل أشكرها؟"}, {"lbl": "الآيات ٣٩ – ٤٢", "q": "يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٣٩﴾ مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٤٠﴾ يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ ﴿٤١﴾ وَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ ﴿٤٢﴾", "w": [["أأرباب متفرقون", "آلهة متفرقون هنا وهناك."], ["ما أنزل الله بها من سلطان", "لم يأمر الله تعالى بعبادتها بأي نوع من أنواع العبادة."], ["فيسقي ربه خمراً", "يسقي سيده الذي هو ملك البلاد شراب الخمر."], ["فيُصلب", "يُقتل مصلوباً على خشبة كما هي عادة القتل عندهم."], ["قُضي الأمر", "فُرغ منه وبُتّ فيه."], ["ظن أنه ناجٍ منهما", "أيقن أنه محكوم ببراءته."], ["فأنساه الشيطان ذكر ربه", "أنسى الشيطان يوسف ذكر ربه تعالى."]], "m": "استغلّ يوسف الفرصة فواصل دعوته: يا صاحبي السجن، أأرباب متفرقون: هذا صنم، وهذا كوكب، وهذا إنسان، وهذا حيوان، خير أم الله الواحد في ذاته وصفاته القهار لكل ما عداه؟ ولم يكن لهم من جواب سوى: الله الواحد القهار. ثم خاطب أهل السجن: ما تعبدون من دونه إلا أسماء سمّيتموها أنتم وآباؤكم، فإطلاق لفظ إله أو رب على مخلوق لا يملك لنفسه نفعاً ولا ضراً كذب وزور، ما أنزل الله بها من حجة، إن الحكم إلا لله، وقد حكم ألّا يُعبد إلا هو، ذلك الدين القيم، ولكن أكثر الناس لا يعلمون. ثم عبّر الرؤيا: يا صاحبي السجن، أما أحدكما فيُبرّأ ويعود ساقياً لسيده الملك الخمر، وأما الآخر، طبّاخ الملك المتّهم بأنه أراد أن يضع السمّ في طعامه، فيُصلب فتأكل الطير من رأسه. قُضي الأمر الذي فيه تستفتيان. وقال للذي أيقن أنه ناجٍ: اذكرني عند سيدك، فأنسى الشيطان يوسف ذكر ربه تعالى حيث التفت بقلبه إلى الخادم والملك، فلبث في السجن بضع سنين، أي سبع سنوات عداً.", "h": ["وجوب اغتنام الفرص للدعوة إلى الله تعالى.", "تقرير التوحيد عن طريق أحاديث السابقين.", "لا حكم في شيء إلا بحكم الله تعالى، فالحق ما أحقّه الله، والباطل ما أبطله، والدين ما شرعه.", "مشروعية الاستفتاء في كل مشكل من الأمور.", "غفلة يوسف ﵇ بإقباله على الفتى وقوله له: «اذكرني عند ربك»، ناسياً مولاه الحق الذي أنجاه من القتل وغيابة الجب وفتنة النساء، جعلته يُحبس في السجن سبع سنين."], "k": "«أأرباب متفرقون خير أم الله الواحد القهار»… كم «ربّاً» صغيراً أرضيه على حساب رضا ربي الواحد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 155;
insert into public.tdb_cards(topic, i, body) select 155, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٥ – ٣٨", "q": "ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ ﴿٣٥﴾ وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٣٦﴾ قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ﴿٣٧﴾ وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٣٨﴾", "w": [["ثم بدا لهم", "ظهر لهم."], ["الآيات", "الدلائل على براءة يوسف."], ["أعصر خمراً", "أعصر عنباً ليكون خمراً."], ["واتبعت ملة", "دين."], ["ما كان لنا", "ما انبغى لنا ولا صحّ منا."], ["أن نشرك بالله من شيء", "أن نشرك بالله شيئاً من الشرك وإن قلّ، ولا من الشركاء وإن عظموا أو حقروا."], ["ذلك من فضل الله علينا", "ذلك التوحيد والدين الحق."], ["وعلى الناس", "إذ جاءتهم الرسل به، ولكنهم ما شكروا فلم يتبعوا."]], "m": "ثم ظهر للعزيز ومن معه، من بعد ما رأوا الدلائل الواضحة على براءة يوسف، كقدّ القميص من دبر وحكم الشاهد، أن يسجنوه إلى حين، ريثما تسكن النفوس وتُنسى الحادثة. ودخل معه السجن فتيان كانا يخدمان ملك البلاد بتهمة وُجّهت إليهما، فلما أعجبا بسلوكه وحسن معاملته وعرفا أنه يعبّر الرؤيا، قال أحدهما: إني أراني أعصر خمراً، وقال الآخر: إني أراني أحمل فوق رأسي خبزاً تأكل الطير منه، نبّئنا بتأويله إنا نراك من المحسنين. قال: لا يأتيكما طعام تُرزقانه إلا نبّأتكما بتأويله قبل أن يأتيكما، ذلكما مما علّمني ربي، إني تركت ملة قوم لا يؤمنون بالله وهم بالآخرة كافرون، وهم الكنعانيون والمصريون، إذ كانوا مشركين يعبدون الشمس وغيرها، واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب، ما كان لنا أن نشرك بالله من شيء، ذلك من فضل الله علينا وعلى الناس، إذ خلقهم ورزقهم ودعاهم إلى الهدى، ولكن أكثر الناس لا يشكرون فلا يؤمنون ولا يعبدون.", "h": ["دخول يوسف السجن بداية أحداث ظاهرها محرق وباطنها مشرق.", "دخول السجن ليس دائماً دليلاً على أنه بيت المجرمين والمنحرفين، إذ دخله صفيّ الله يوسف ﵇.", "تعبير الرؤى تابع لصفاء الروح وقوة الفراسة، وهي في يوسف علم لدنّي خاص.", "استغلال المناسبات للدعوة إلى الله تعالى كما استغلها يوسف ﵇.", "وجوب البراءة من الشرك وأهله.", "إطلاق لفظ الآباء على الجدود، إذ كل واحد هو أب لمن بعده."], "k": "«ذلك من فضل الله علينا»… التوحيد الذي في قلبي نعمة لا جهد مني؛ فهل أشكرها؟"}, {"lbl": "الآيات ٣٩ – ٤٢", "q": "يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٣٩﴾ مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٤٠﴾ يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ ﴿٤١﴾ وَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ ﴿٤٢﴾", "w": [["أأرباب متفرقون", "آلهة متفرقون هنا وهناك."], ["ما أنزل الله بها من سلطان", "لم يأمر الله تعالى بعبادتها بأي نوع من أنواع العبادة."], ["فيسقي ربه خمراً", "يسقي سيده الذي هو ملك البلاد شراب الخمر."], ["فيُصلب", "يُقتل مصلوباً على خشبة كما هي عادة القتل عندهم."], ["قُضي الأمر", "فُرغ منه وبُتّ فيه."], ["ظن أنه ناجٍ منهما", "أيقن أنه محكوم ببراءته."], ["فأنساه الشيطان ذكر ربه", "أنسى الشيطان يوسف ذكر ربه تعالى."]], "m": "استغلّ يوسف الفرصة فواصل دعوته: يا صاحبي السجن، أأرباب متفرقون: هذا صنم، وهذا كوكب، وهذا إنسان، وهذا حيوان، خير أم الله الواحد في ذاته وصفاته القهار لكل ما عداه؟ ولم يكن لهم من جواب سوى: الله الواحد القهار. ثم خاطب أهل السجن: ما تعبدون من دونه إلا أسماء سمّيتموها أنتم وآباؤكم، فإطلاق لفظ إله أو رب على مخلوق لا يملك لنفسه نفعاً ولا ضراً كذب وزور، ما أنزل الله بها من حجة، إن الحكم إلا لله، وقد حكم ألّا يُعبد إلا هو، ذلك الدين القيم، ولكن أكثر الناس لا يعلمون. ثم عبّر الرؤيا: يا صاحبي السجن، أما أحدكما فيُبرّأ ويعود ساقياً لسيده الملك الخمر، وأما الآخر، طبّاخ الملك المتّهم بأنه أراد أن يضع السمّ في طعامه، فيُصلب فتأكل الطير من رأسه. قُضي الأمر الذي فيه تستفتيان. وقال للذي أيقن أنه ناجٍ: اذكرني عند سيدك، فأنسى الشيطان يوسف ذكر ربه تعالى حيث التفت بقلبه إلى الخادم والملك، فلبث في السجن بضع سنين، أي سبع سنوات عداً.", "h": ["وجوب اغتنام الفرص للدعوة إلى الله تعالى.", "تقرير التوحيد عن طريق أحاديث السابقين.", "لا حكم في شيء إلا بحكم الله تعالى، فالحق ما أحقّه الله، والباطل ما أبطله، والدين ما شرعه.", "مشروعية الاستفتاء في كل مشكل من الأمور.", "غفلة يوسف ﵇ بإقباله على الفتى وقوله له: «اذكرني عند ربك»، ناسياً مولاه الحق الذي أنجاه من القتل وغيابة الجب وفتنة النساء، جعلته يُحبس في السجن سبع سنين."], "k": "«أأرباب متفرقون خير أم الله الواحد القهار»… كم «ربّاً» صغيراً أرضيه على حساب رضا ربي الواحد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (156, 12, 43, 52, 'سورة يوسف ٤٣ – ٥٢', 'رؤيا الملك وتأويلها، و«الآن حصحص الحق»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 156) = $j$[{"lbl": "الآيات ٤٣ – ٤٦", "q": "وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَـٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ ﴿٤٣﴾ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ ﴿٤٤﴾ وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ ﴿٤٥﴾ يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ ﴿٤٦﴾", "w": [["الملك", "ملك مصر الذي العزيز وزير من وزرائه، واسمه الريان بن الوليد."], ["سبع عجاف", "هزال غير سمان."], ["يا أيها الملأ", "أيها الأشراف والأعيان من رجال الدولة."], ["أفتوني في رؤياي", "عبّروها لي."], ["أضغاث أحلام", "أخلاط أحلام كاذبة لا تعبير لها."], ["وادّكر بعد أمة", "وتذكّر بعد حين من الزمن، قرابة سبع سنين."], ["يوسف أيها الصديق", "يا يوسف أيها الكثير الصدق."]], "m": "لما قارب الفرج أوانه رأى ملك مصر رؤيا أهالته، فقال: إني أرى في منامي سبع بقرات سمان يأكلهن سبع بقرات مهازيل في غاية الهزال، وسبع سنبلات خضر وأُخر يابسات، يا أيها الأشراف ورجال العلم أفتوني في رؤياي إن كنتم للرؤيا تعبرون. قالوا: هذه أخلاط أحلام لا تُعبّر، وما نحن بتأويل الأحلام بعالمين، وفي الحديث الصحيح: «الرؤيا من الرحمن، والحلم من الشيطان». وقال الذي نجا من صاحبي السجن، وتذكّر بعد قرابة سبع سنين وصية يوسف: أنا أنبئكم بتأويله فأرسلوني إلى يوسف في السجن، فأرسلوه فقال: يوسف أيها الصدّيق، أفتنا في سبع بقرات سمان يأكلهن سبع عجاف، وسبع سنبلات خضر وأُخر يابسات، لعلي أرجع إلى الملك ورجاله لعلهم يعلمون ما تعبّرها به فينتفعون.", "h": ["جواز الرؤيا الصالحة يراها الكافر والفاسق.", "الرؤى نوعان: حلم من الشيطان، ورؤيا من الرحمن.", "النسيان من صفات البشر.", "جواز وصف الإنسان بما فيه من غير إطراء، كقوله: «أيها الصديق».", "«لعل» تكون بمعنى «كي» التعليلية."], "k": "«أيها الصديق»… عُرف يوسف بالصدق حتى في السجن؛ فبماذا يعرفني الناس؟"}, {"lbl": "الآيات ٤٧ – ٤٩", "q": "قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ ﴿٤٧﴾ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ ﴿٤٨﴾ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ ﴿٤٩﴾", "w": [["دأباً", "متتابعة على عادتكم."], ["فذروه في سنبله", "اتركوه في سنبله لا تدرسوه."], ["سبع شداد", "صعاب قاسية لما فيها من الجدب."], ["مما تحصنون", "تحفظونه وتدّخرونه للبذر والحاجة."], ["يغاث الناس", "يغيثهم ربهم بالأمطار وجريان النيل."], ["وفيه يعصرون", "ما من شأنه أن يُعصر كالزيتون والعنب."]], "m": "قال يوسف في تأويل رؤيا الملك: ازرعوا سبع سنين متتالية كعادتكم في الزرع كل سنة، وهي تأويل البقرات السمان، فما حصدتم فاتركوه في سنبله بدون درس حتى لا يفسد، إلا قليلاً مما تأكلون فادرسوه. ثم يأتي من بعد المخصبات سبع مجدبات صعاب، وهي تأويل البقرات العجاف، يأكلن ما قدّمتم لهن من الحبوب التي احتفظتم بها، إلا قليلاً مما تدّخرونه للبذر. ثم يأتي من بعد ذلك عام فيه يُغاث الناس بالمطر، وفيه يعصرون العنب والزيت لوجود الخصب. وهذا العام لم تدلّ عليه الرؤيا، وإنما هو مما علّمه الله يوسف، فأفادهم به من غير ما سألوه إحساناً منه، ولحكمة أرادها الله.", "h": ["أرض مصر أرض فلاحة وزراعة من عهدها الأول.", "الاحتفاظ بالفائض في الصوامع وغيرها مبدأ اقتصادي هام ومفيد.", "كمال يوسف في حسن تعبير الرؤى شيء عظيم.", "فضل يوسف ﵇ على أهل مصر، حيث أفادهم بأكثر مما سألوا."], "k": "«ثم يأتي من بعد ذلك عام فيه يغاث الناس»… بعد الشدة فرج؛ فهل أدّخر في الرخاء لأيام الشدة؟"}, {"lbl": "الآيات ٥٠ – ٥٢", "q": "وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّـٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ ﴿٥٠﴾ قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ ﴿٥١﴾ ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ ﴿٥٢﴾", "w": [["وقال الملك ائتوني به", "أي بيوسف."], ["فلما جاءه الرسول", "مبعوث الملك."], ["ارجع إلى ربك", "سيدك."], ["ما بال النسوة", "ما حالهن."], ["ما خطبكن", "ما شأنكن."], ["حاش لله", "تنزيهاً لله تعالى عن العجز أن يخلق بشراً عفيفاً."], ["حصحص الحق", "وضح وظهر الحق."]], "m": "كانت رؤيا الملك تدبيراً من الله لإخراج يوسف من السجن، فلما أعجب الملكَ التعبيرُ أمر بإحضاره لإكرامه لما ظهر له من علمه وكماله، فلما جاءه الرسول، صاحبه في السجن، قال: ارجع إلى سيدك فاسأله ما بال النسوة اللاتي قطّعن أيديهن والمرأة التي اتهمتني؟ إن ربي بكيدهن عليم. فجمع الملك النسوة وقال: ما شأنكن إذ راودتنّ يوسف عن نفسه؟ قلن: حاش لله ما علمنا عليه من سوء. قالت امرأة العزيز: الآن وضح الحق وظهر، أنا راودته عن نفسه، وإنه لمن الصادقين. قال يوسف: ذلك، أي امتناعي من الخروج حتى تمّت براءتي على لسانهن، ليعلم العزيز أني لم أخنه في أهله في غيبته، وأن عرضه مصان، وأن الله لا يهدي كيد الخائنين، فلو كنت خائناً ما هداني لمثل هذا الموقف المشرّف.", "h": ["فضل العلم وشرفه، إذ به رفع الملكُ يوسفَ إلى حضرته.", "فضيلة الحلم والأناة وعدم التسرّع في الأمور.", "فضيلة الصدق وقول الحق ولو كان على النفس.", "شرف زليخا بإقرارها بذنبها، رفعها مقاماً سامياً."], "k": "«الآن حصحص الحق»… لم يتعجّل يوسف الخروج حتى ظهرت براءته؛ فهل أصبر حتى يُظهر الله الحق؟"}]$j$::jsonb then 0 else 1 end;
