insert into public.tdb_cards(topic, i, body) select 156, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٣ – ٤٦", "q": "وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَـٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ ﴿٤٣﴾ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ ﴿٤٤﴾ وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ ﴿٤٥﴾ يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ ﴿٤٦﴾", "w": [["الملك", "ملك مصر الذي العزيز وزير من وزرائه، واسمه الريان بن الوليد."], ["سبع عجاف", "هزال غير سمان."], ["يا أيها الملأ", "أيها الأشراف والأعيان من رجال الدولة."], ["أفتوني في رؤياي", "عبّروها لي."], ["أضغاث أحلام", "أخلاط أحلام كاذبة لا تعبير لها."], ["وادّكر بعد أمة", "وتذكّر بعد حين من الزمن، قرابة سبع سنين."], ["يوسف أيها الصديق", "يا يوسف أيها الكثير الصدق."]], "m": "لما قارب الفرج أوانه رأى ملك مصر رؤيا أهالته، فقال: إني أرى في منامي سبع بقرات سمان يأكلهن سبع بقرات مهازيل في غاية الهزال، وسبع سنبلات خضر وأُخر يابسات، يا أيها الأشراف ورجال العلم أفتوني في رؤياي إن كنتم للرؤيا تعبرون. قالوا: هذه أخلاط أحلام لا تُعبّر، وما نحن بتأويل الأحلام بعالمين، وفي الحديث الصحيح: «الرؤيا من الرحمن، والحلم من الشيطان». وقال الذي نجا من صاحبي السجن، وتذكّر بعد قرابة سبع سنين وصية يوسف: أنا أنبئكم بتأويله فأرسلوني إلى يوسف في السجن، فأرسلوه فقال: يوسف أيها الصدّيق، أفتنا في سبع بقرات سمان يأكلهن سبع عجاف، وسبع سنبلات خضر وأُخر يابسات، لعلي أرجع إلى الملك ورجاله لعلهم يعلمون ما تعبّرها به فينتفعون.", "h": ["جواز الرؤيا الصالحة يراها الكافر والفاسق.", "الرؤى نوعان: حلم من الشيطان، ورؤيا من الرحمن.", "النسيان من صفات البشر.", "جواز وصف الإنسان بما فيه من غير إطراء، كقوله: «أيها الصديق».", "«لعل» تكون بمعنى «كي» التعليلية."], "k": "«أيها الصديق»… عُرف يوسف بالصدق حتى في السجن؛ فبماذا يعرفني الناس؟"}, {"lbl": "الآيات ٤٧ – ٤٩", "q": "قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ ﴿٤٧﴾ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ ﴿٤٨﴾ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ ﴿٤٩﴾", "w": [["دأباً", "متتابعة على عادتكم."], ["فذروه في سنبله", "اتركوه في سنبله لا تدرسوه."], ["سبع شداد", "صعاب قاسية لما فيها من الجدب."], ["مما تحصنون", "تحفظونه وتدّخرونه للبذر والحاجة."], ["يغاث الناس", "يغيثهم ربهم بالأمطار وجريان النيل."], ["وفيه يعصرون", "ما من شأنه أن يُعصر كالزيتون والعنب."]], "m": "قال يوسف في تأويل رؤيا الملك: ازرعوا سبع سنين متتالية كعادتكم في الزرع كل سنة، وهي تأويل البقرات السمان، فما حصدتم فاتركوه في سنبله بدون درس حتى لا يفسد، إلا قليلاً مما تأكلون فادرسوه. ثم يأتي من بعد المخصبات سبع مجدبات صعاب، وهي تأويل البقرات العجاف، يأكلن ما قدّمتم لهن من الحبوب التي احتفظتم بها، إلا قليلاً مما تدّخرونه للبذر. ثم يأتي من بعد ذلك عام فيه يُغاث الناس بالمطر، وفيه يعصرون العنب والزيت لوجود الخصب. وهذا العام لم تدلّ عليه الرؤيا، وإنما هو مما علّمه الله يوسف، فأفادهم به من غير ما سألوه إحساناً منه، ولحكمة أرادها الله.", "h": ["أرض مصر أرض فلاحة وزراعة من عهدها الأول.", "الاحتفاظ بالفائض في الصوامع وغيرها مبدأ اقتصادي هام ومفيد.", "كمال يوسف في حسن تعبير الرؤى شيء عظيم.", "فضل يوسف ﵇ على أهل مصر، حيث أفادهم بأكثر مما سألوا."], "k": "«ثم يأتي من بعد ذلك عام فيه يغاث الناس»… بعد الشدة فرج؛ فهل أدّخر في الرخاء لأيام الشدة؟"}, {"lbl": "الآيات ٥٠ – ٥٢", "q": "وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّـٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ ﴿٥٠﴾ قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ ﴿٥١﴾ ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ ﴿٥٢﴾", "w": [["وقال الملك ائتوني به", "أي بيوسف."], ["فلما جاءه الرسول", "مبعوث الملك."], ["ارجع إلى ربك", "سيدك."], ["ما بال النسوة", "ما حالهن."], ["ما خطبكن", "ما شأنكن."], ["حاش لله", "تنزيهاً لله تعالى عن العجز أن يخلق بشراً عفيفاً."], ["حصحص الحق", "وضح وظهر الحق."]], "m": "كانت رؤيا الملك تدبيراً من الله لإخراج يوسف من السجن، فلما أعجب الملكَ التعبيرُ أمر بإحضاره لإكرامه لما ظهر له من علمه وكماله، فلما جاءه الرسول، صاحبه في السجن، قال: ارجع إلى سيدك فاسأله ما بال النسوة اللاتي قطّعن أيديهن والمرأة التي اتهمتني؟ إن ربي بكيدهن عليم. فجمع الملك النسوة وقال: ما شأنكن إذ راودتنّ يوسف عن نفسه؟ قلن: حاش لله ما علمنا عليه من سوء. قالت امرأة العزيز: الآن وضح الحق وظهر، أنا راودته عن نفسه، وإنه لمن الصادقين. قال يوسف: ذلك، أي امتناعي من الخروج حتى تمّت براءتي على لسانهن، ليعلم العزيز أني لم أخنه في أهله في غيبته، وأن عرضه مصان، وأن الله لا يهدي كيد الخائنين، فلو كنت خائناً ما هداني لمثل هذا الموقف المشرّف.", "h": ["فضل العلم وشرفه، إذ به رفع الملكُ يوسفَ إلى حضرته.", "فضيلة الحلم والأناة وعدم التسرّع في الأمور.", "فضيلة الصدق وقول الحق ولو كان على النفس.", "شرف زليخا بإقرارها بذنبها، رفعها مقاماً سامياً."], "k": "«الآن حصحص الحق»… لم يتعجّل يوسف الخروج حتى ظهرت براءته؛ فهل أصبر حتى يُظهر الله الحق؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;